// Generated by `deno task mcp:data` from the docs, examples and JSDoc. Do not edit.
import type { IoCKnowledge } from './knowledge.ts';

/** The @fathym/ioc knowledge base for this version: docs sections, verified examples, API and errors. */
export const IOC_KNOWLEDGE: IoCKnowledge = JSON.parse("{\"SourceUrl\":\"https://github.com/fathym/ioc/blob/main/\",\"Sections\":[{\"Path\":\"README.md\",\"Title\":\"@fathym/ioc › Dependency injection for modern TypeScript. No decorators. No metadata. Async from the ground up.\",\"Text\":\"[![npm](https://img.shields.io/npm/v/@fathym/ioc)](https://www.npmjs.com/package/@fathym/ioc)\\n[![JSR](https://jsr.io/badges/@fathym/ioc)](https://jsr.io/@fathym/ioc)\\n[![JSR Score](https://jsr.io/badges/@fathym/ioc/score)](https://jsr.io/@fathym/ioc/score)\\n[![Build](https://github.com/fathym/ioc/actions/workflows/build.yml/badge.svg)](https://github.com/fathym/ioc/actions/workflows/build.yml)\\n[![License: MIT](https://img.shields.io/badge/license-MIT-blue.svg)](https://github.com/fathym/ioc/blob/main/LICENSE)\\n\\nMost TypeScript DI containers were built for a world of `experimentalDecorators` and\\n`reflect-metadata`. They break under esbuild, Vite and Vitest, they resolve synchronously while\\nyour database connects asynchronously, and they tell you about a missing dependency when the first\\nrequest hits it.\\n\\n**@fathym/ioc is built for how TypeScript apps are written today.** Plain classes. Typed keys.\\nAsync factories that just work. Wiring mistakes caught by the compiler, and the rest caught at\\nstartup. Clean shutdown when you're done. It runs on Deno, Node.js and Bun, in about 6 KB gzipped,\\nwith zero dependencies.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\ninterface Mailer {\\n  send(to: string, body: string): Promise<void>;\\n}\\n\\nclass Db {\\n  static async connect(url: string) {\\n    return new Db(url); // open your real connection pool here\\n  }\\n\\n  constructor(public url: string) {}\\n\\n  async [Symbol.asyncDispose]() {\\n    console.log('db closed');\\n  }\\n}\\n\\nclass Signup {\\n  constructor(private db: Db, private mailer: Mailer) {}\\n\\n  async register(email: string) {\\n    await this.mailer.send(email, `Welcome! (saved to ${this.db.url})`);\\n  }\\n}\\n\\nconst $Mailer = IoCToken<Mailer>('app/Mailer');\\n\\n{\\n  await using ioc = new IoCContainer()\\n    .RegisterFactory(Db, () => Db.connect('postgres://localhost/app')) // async, built once\\n    .RegisterValue($Mailer, { send: async (to, body) => console.log(`to ${to}: ${body}`) })\\n    .RegisterClass(Signup, { Deps: [Db, $Mailer] }); // checked against the constructor\\n\\n  ioc.Validate(); // every wiring mistake, reported before anything runs\\n\\n  const signup = await ioc.Resolve(Signup); // typed as Signup\\n\\n  await signup.register('ada@example.com'); // to ada@example.com: Welcome! (saved to …)\\n} // db closed: whatever the container built is disposed, in reverse order\\n```\"},{\"Path\":\"README.md\",\"Title\":\"@fathym/ioc › Why teams pick it\",\"Text\":\"- **🧩 No decorators, no metadata, no build step.** Your classes stay plain TypeScript. Nothing\\n  depends on `emitDecoratorMetadata`, so it works the same under esbuild, Vite, tsx, Vitest, Deno,\\n  Node.js and Bun.\\n- **🛡️ Mistakes caught by the compiler.** `Deps` is checked against your constructor, in order\\n  and by type. Turn on `Typed()` and using a service before it's registered won't compile.\\n- **🔍 The rest caught at startup.** `Validate()` lists every missing dependency, cycle and\\n  lifetime mistake in one go, without building anything. Put it in one test and wiring bugs never\\n  reach production.\\n- **⚡ Async is first-class.** Factories can be `async`. Concurrent requests share one build, and a\\n  connection that fails is retried on the next resolve instead of being cached as broken.\\n- **🧹 Clean shutdown, built in.** One scope per request with `await using`. Everything the\\n  container built is disposed in reverse order. Modules start in dependency order and stop in\\n  reverse, so your server drains before your database closes.\\n- **🧪 Easy to test.** `Override()` swaps any service for a fake and hands you a restore\\n  function. Test against the real wiring, not a hand-built copy of it.\\n- **📖 Errors that explain themselves.** Every error has a stable code and an\\n  [entry in the catalog](https://github.com/fathym/ioc/blob/main/docs/reference/errors.md) with\\n  the cause and the fix.\"},{\"Path\":\"README.md\",\"Title\":\"@fathym/ioc › See it in action\",\"Text\":\"**A scope per request,** cleaned up when the request ends:\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Request = IoCToken<{ path: string }>('app/Request');\\n\\nclass RequestContext {\\n  public id = crypto.randomUUID().slice(0, 8);\\n}\\n\\nclass Handler {\\n  constructor(private req: { path: string }, private ctx: RequestContext) {}\\n\\n  handle() {\\n    return `${this.ctx.id} handled ${this.req.path}`;\\n  }\\n}\\n\\nconst app = new IoCContainer()\\n  .RegisterClass(RequestContext, { Lifetime: 'scoped' }) // one per request\\n  .RegisterClass(Handler, { Deps: [$Request, RequestContext], Lifetime: 'transient' });\\n\\nfor (const path of ['/notes', '/users']) {\\n  await using scope = app.CreateScope().RegisterValue($Request, { path });\\n\\n  console.log((await scope.Resolve(Handler)).handle()); // 3f9c1a2b handled /notes …\\n}\\n```\\n\\n**A constructor change the wiring didn't follow** doesn't compile:\\n\\n```ts\\nimport { IoCContainer } from '@fathym/ioc';\\n\\nclass Db {}\\nclass Cache {}\\n\\nclass Repo {\\n  constructor(public db: Db, public cache: Cache) {} // gained a Cache parameter\\n}\\n\\nconst ioc = new IoCContainer().RegisterClass(Db).RegisterClass(Cache);\\n\\nioc.RegisterClass(Repo, {\\n  // @ts-expect-error Source has 1 element(s) but target requires 2.\\n  Deps: [Db],\\n});\\n```\\n\\n**Modules with a lifecycle,** started in order and stopped in reverse:\\n\\n```ts\\nimport { DefineModule, IoCContainer } from '@fathym/ioc';\\n\\nconst Database = DefineModule({\\n  Name: 'Database',\\n  Register: (ioc) => ioc,\\n  OnStart: () => console.log('database connected'),\\n  OnStop: () => console.log('database closed'),\\n});\\n\\nconst Api = DefineModule({\\n  Name: 'Api',\\n  Requires: [Database], // started after Database, stopped before it\\n  Register: (ioc) => ioc,\\n  OnStart: () => console.log('api listening'),\\n  OnStop: () => console.log('api drained'),\\n});\\n\\n{\\n  await using app = new IoCContainer().Use(Api);\\n\\n  await app.Start(); // database connected, api listening\\n} // api drained, database closed\\n```\"},{\"Path\":\"README.md\",\"Title\":\"@fathym/ioc › How it compares\",\"Text\":\"|                                                        | @fathym/ioc | InversifyJS | tsyringe | awilix  | NestJS |\\n| ------------------------------------------------------ | :---------: | :---------: | :------: | :-----: | :----: |\\n| No decorators or `reflect-metadata`                    |      ✓      |      ~      |    ✗     |    ✓    |   ✗    |\\n| A wrong dependency fails to compile †                  |      ✓      |      ~      |    ✗     |    ✗    |   ✗    |\\n| An async dependency is injected ready, not a promise † |      ✓      |      ✓      |    ✗     |    ✗    |   ✓    |\\n| A failed async build is retried, not cached †          |      ✓      |      ✗      |    ✗     |    ✗    |   –    |\\n| Disposes a service before its dependencies †           |      ✓      |      ✗      |    ✗     |    ✗    |   –    |\\n| A missing dependency is found at startup †             |      ✓      |      ✗      |    ✗     |    ✗    |   ✓    |\\n| Modules with start/stop lifecycle                      |      ✓      |      ~      |    ✗     |    ✗    |   ✓    |\\n| Standalone library, not a framework                    |      ✓      |      ✓      |    ✓     |    ✓    |   ✗    |\\n| Synchronous resolve                                    |      ✗      |      ✓      |    ✓     |    ✓    |   ✓    |\\n| Minified + gzipped                                     | **6.1 KB**  |   24.7 KB   | 11.0 KB  | 30.1 KB | 141 KB |\\n| Runtime dependencies                                   |    **0**    |    6 + 1    |  1 + 1   |   18    | 18 + 2 |\\n\\n✓ yes · ~ partly · ✗ no · – not measured. **Rows marked † are measured, not taken from docs:**\\n`deno task compare` runs the same scenarios and benchmarks against each library at pinned versions\\n(InversifyJS 8.2, tsyringe 4.10, awilix 13.0) and writes the\\n[comparison page](https://github.com/fathym/ioc/blob/main/docs/reference/comparison.md), with the\\ncode for every cell. InversifyJS checks dependencies at compile time with `toResolvedValue`, not\\nwith `@inject` decorators, and loads `reflect-metadata` itself. NestJS cells come from its\\ndocumentation. On raw speed the synchronous containers win: a resolve here takes about 1 µs\\nagainst 50–200 ns; the comparison page has the numbers.\\n\\nSizes are each whole library bundled with its required polyfill and measured with\\n`deno task size --compare` (NestJS 12.3 core and common). Dependencies count indirect ones;\\n\\\"+ 1\\\" is `reflect-metadata`, and NestJS's \\\"+ 2\\\" adds rxjs. awilix's browser build leaves out file\\nscanning and is 3.6 KB.\\n\\nNeed several implementations of one interface, such as a chain of handlers or one cache per\\nregion? Register each under a\\n[name](https://github.com/fathym/ioc/blob/main/docs/reference/api.md#resolveallkey) and\\ncollect them with `ResolveAll`. A whole folder of modules registers with one call, too: see\\n[registering many modules](https://github.com/fathym/ioc/blob/main/docs/guides/registering-many-modules.md).\\n\\n**Pick something else if** you need synchronous resolution everywhere, auto-registration by\\nscanning files and naming conventions (awilix does this well), property injection or bindings\\nchosen by tags and injection target (InversifyJS), or you're inside a framework with its own DI,\\nsuch as NestJS or Angular.\"},{\"Path\":\"README.md\",\"Title\":\"@fathym/ioc › Install\",\"Text\":\"```sh\\nnpm install @fathym/ioc      # Node.js 20+ (or pnpm add, yarn add)\\nbun add @fathym/ioc          # Bun\\ndeno add jsr:@fathym/ioc     # Deno\\n```\\n\\nTypeScript 5.4 or later. See the\\n[requirements](https://github.com/fathym/ioc/blob/main/docs/getting-started/installation.md#requirements).\"},{\"Path\":\"README.md\",\"Title\":\"@fathym/ioc › Learn it in 15 minutes\",\"Text\":\"| Start here                                                                                | What you get                                         |\\n| ----------------------------------------------------------------------------------------- | ---------------------------------------------------- |\\n| [Getting started](https://github.com/fathym/ioc/blob/main/docs/getting-started/README.md) | Five short steps, from a first container to tests    |\\n| [API reference](https://github.com/fathym/ioc/blob/main/docs/reference/api.md)            | Every method and option, each with an example        |\\n| [Error catalog](https://github.com/fathym/ioc/blob/main/docs/reference/errors.md)         | Every error message: what it means and how to fix it |\\n| [Examples](https://github.com/fathym/ioc/blob/main/examples/README.md)                    | Small programs you can run and copy, an HTTP app too |\\n| [Upgrading from 0.x](https://github.com/fathym/ioc/blob/main/docs/migration/from-0.x.md)  | Every old call next to its replacement               |\\n\\nEvery code example in the docs is type-checked and run in CI, so what you read is what works. The\\ngenerated API docs are on [JSR](https://jsr.io/@fathym/ioc/doc), and AI tools can start from\\n[`llms.txt`](https://github.com/fathym/ioc/blob/main/llms.txt).\"},{\"Path\":\"README.md\",\"Title\":\"@fathym/ioc › Built to be depended on\",\"Text\":\"- **A stable 1.x API.** Breaking changes only in a major release, each with a migration guide, and\\n  anything deprecated keeps working for at least six months. The\\n  [versioning policy](https://github.com/fathym/ioc/blob/main/docs/policy.md) defines exactly what\\n  counts as breaking.\\n- **Proven, not just promised.** The\\n  [guarantees](https://github.com/fathym/ioc/blob/main/docs/reference/guarantees.md) list what\\n  the container promises about builds, disposal, startup, timeouts and `Validate()`, each linked\\n  to the test that proves it. CI fails if a linked test goes away, and test coverage of the source\\n  is 98.8% of lines and 97.1% of branches, with CI failing below 97% and 95%.\\n- **Measured against the alternatives.** The\\n  [comparison](https://github.com/fathym/ioc/blob/main/docs/reference/comparison.md) runs the\\n  same scenarios and benchmarks against InversifyJS, awilix and tsyringe, and you can re-run it.\\n- **Tested on every runtime it supports:** the full suite on Deno, and the published build on\\n  Node.js 20, 22 and 24 and Bun, type-checked with TypeScript 5.4 and the latest.\\n- **Answered:** security reports are acknowledged within 3 business days and new issues triaged\\n  within 5 ([maintainers](https://github.com/fathym/ioc/blob/main/MAINTAINERS.md)).\\n- **Yours to own if you need to:** MIT, no dependencies, and about 2,700 lines including\\n  documentation comments.\\n- **Every change** is in the [changelog](https://github.com/fathym/ioc/blob/main/CHANGELOG.md).\\n\\nDeciding whether to adopt it?\\n[Evaluating @fathym/ioc](https://github.com/fathym/ioc/blob/main/docs/evaluating.md) covers\\nsupport, the honest risks, and how to adopt it safely.\\n\\nBuilt and maintained by [Fathym](https://github.com/fathym), whose own platform, from the CLI to\\nthe runtime, is built on it.\"},{\"Path\":\"README.md\",\"Title\":\"@fathym/ioc › Contributing\",\"Text\":\"Issues and pull requests are welcome. See\\n[CONTRIBUTING](https://github.com/fathym/ioc/blob/main/CONTRIBUTING.md) for setup, tests and\\ndocumentation conventions. Please report security issues privately as described in\\n[SECURITY](https://github.com/fathym/ioc/blob/main/SECURITY.md), and follow the\\n[Code of Conduct](https://github.com/fathym/ioc/blob/main/CODE_OF_CONDUCT.md).\"},{\"Path\":\"README.md\",\"Title\":\"@fathym/ioc › License\",\"Text\":\"[MIT](https://github.com/fathym/ioc/blob/main/LICENSE) © Fathym\"},{\"Path\":\"docs/README.md\",\"Title\":\"@fathym/ioc Documentation\",\"Text\":\"Small, async-first, decorator-free dependency injection for Deno, Node.js and Bun. Every code\\nexample in these docs is type-checked and run in CI.\\n\\n| If you…                          | Start with                                                  |\\n| -------------------------------- | ----------------------------------------------------------- |\\n| Are new to the container         | [Getting started](./getting-started/README.md) _[Tutorial]_ |\\n| Have one task to get done        | [Guides](./guides/README.md) _[How-to]_                     |\\n| Want to look something up        | [API reference](./reference/api.md) _[Reference]_           |\\n| Hit an error                     | [Error catalog](./reference/errors.md) _[Reference]_        |\\n| Are upgrading from 0.0.x or 0.1  | [Migrating from 0.x](./migration/from-0.x.md) _[How-to]_    |\\n| Want to know why it is this way  | [IoC 1.0 design](./design/ioc-1.0.md) _[Explanation]_       |\\n| Are deciding whether to adopt it | [Evaluating @fathym/ioc](./evaluating.md) _[Explanation]_   |\"},{\"Path\":\"docs/README.md\",\"Title\":\"@fathym/ioc Documentation › All pages\",\"Text\":\"| Folder                                          | What's in it                                                            |\\n| ----------------------------------------------- | ----------------------------------------------------------------------- |\\n| [getting-started/](./getting-started/README.md) | Install, a first container, async services, scopes, testing             |\\n| [guides/](./guides/README.md)                   | One-task recipes, such as registering many modules                      |\\n| [reference/](./reference/README.md)             | The API reference, the error catalog, the guarantees and the comparison |\\n| [migration/](./migration/README.md)             | Upgrading from 0.x                                                      |\\n| [design/](./design/ioc-1.0.md)                  | Why 1.0 looks the way it does, and what dependents change               |\\n| [evaluating.md](./evaluating.md)                | Support, stability, risks and how to adopt it safely                    |\\n| [policy.md](./policy.md)                        | Versioning, deprecations, supported runtimes and releases               |\\n\\nDesign notes: [IoC 1.0](./design/ioc-1.0.md) and\\n[dependent follow-ups](./design/dependent-follow-ups.md).\"},{\"Path\":\"docs/README.md\",\"Title\":\"@fathym/ioc Documentation › Conventions\",\"Text\":\"How these docs are written. [CONTRIBUTING](../CONTRIBUTING.md#documentation) explains how to add a\\npage.\\n\\n- **Frontmatter on every page** in the house schema (`FrontmatterVersion`, `DocumentType`,\\n  `Title`, `Summary`, `Created`, `Updated`, `Owners`, `References`).\\n- **One idea per example.** Each example is a complete module that type-checks and runs in CI.\\n  Tokens are written `IoCToken<T, 'Name'>('Name')` where a typed container needs the name in the\\n  type, and `IoCToken<T>('Name')` otherwise.\\n- **1.0 as it is.** Pages describe the current API only; changes from 0.x live in the\\n  [migration guide](./migration/from-0.x.md) and the [changelog](../CHANGELOG.md).\\n- **Links are tagged by type** (_[Tutorial]_, _[How-to]_, _[Explanation]_, _[Reference]_), and\\n  every page ends with **What's Next**.\\n- **Limits are stated plainly.** No page implies a capability the container doesn't have.\"},{\"Path\":\"docs/evaluating.md\",\"Title\":\"Evaluating @fathym/ioc\",\"Text\":\"> **Goal:** decide whether your team should depend on `@fathym/ioc`, with the evidence in one\\n> place.\\n\\nA dependency injection container sits under the whole application, so the question isn't only\\n\\\"is the API nice\\\" but \\\"can we rely on it\\\". This page answers the questions reviewers ask, and\\nstates the risks plainly.\"},{\"Path\":\"docs/evaluating.md\",\"Title\":\"Evaluating @fathym/ioc › At a glance\",\"Text\":\"| What                     | Where it stands                                                                                                                  |\\n| ------------------------ | -------------------------------------------------------------------------------------------------------------------------------- |\\n| Stable since             | 1.0, November 2026 (`1.0.18` was the first stable release); the 0.x line ran from 2025                                           |\\n| Breaking changes         | Only in a major release, with a migration guide ([policy](./policy.md#semantic-versioning))                                      |\\n| Behavior you can rely on | [Guarantees](./reference/guarantees.md), each linked to the test that proves it; CI fails if one is removed                      |\\n| Test coverage of `src/`  | 98.8% of lines, 97.1% of branches; CI fails below 97% / 95% (`deno task coverage`)                                               |\\n| Runtimes                 | Full suite on Deno 2; the published build on Node.js 20, 22 and 24 and Bun; TypeScript 5.4 and later                             |\\n| Size and dependencies    | About 6 KB minified and gzipped; no runtime dependencies                                                                         |\\n| Compared with others     | [The same scenarios and benchmarks](./reference/comparison.md) against InversifyJS, awilix and tsyringe                          |\\n| License                  | MIT                                                                                                                              |\\n| Maintainers              | Listed in [MAINTAINERS.md](../MAINTAINERS.md); new issues triaged within 5 business days, security reports acknowledged within 3 |\"},{\"Path\":\"docs/evaluating.md\",\"Title\":\"Evaluating @fathym/ioc › Questions reviewers ask\",\"Text\":\"- **What is the support commitment for 1.x?** The latest 1.x release gets bug and security fixes.\\n  Anything deprecated keeps working for at least one minor release and at least six months, and is\\n  removed only in a major release. Dropping a runtime version is announced a release ahead. The\\n  details are in the [versioning and support policy](./policy.md).\\n- **Are breaking changes limited to major releases?** Yes. The policy defines breaking precisely:\\n  exports, signatures, error codes, documented behavior (lifetimes, ordering, disposal, what\\n  `Validate()` reports, option defaults) and supported runtimes. Error message text is not part of\\n  the contract; error codes are.\\n- **How are security issues handled?** Privately, through GitHub security advisories, with an\\n  acknowledgement within three business days. See the [security policy](../SECURITY.md).\\n- **Is it feature-complete, and what's the roadmap?** It is intentionally small. A feature is added\\n  only when it fixes a bug real applications hit or replaces something they do by hand; the\\n  [design notes](./design/ioc-1.0.md) list what was left out and why. Expect fixes and small,\\n  additive minor releases, not a growing framework. Synchronous resolution of already-built\\n  services is the one addition under consideration.\\n- **Who else uses it in production?** Fathym's own platform, from its CLI to its runtime, runs on\\n  the 0.x line, and is moving to 1.0. Outside adoption is new. If you adopt it, tell us in an issue or a discussion; it helps everyone judge\\n  the same question.\\n- **What if the maintainers stop?** You can own it. It is MIT-licensed, has no dependencies, and is\\n  about 2,700 lines including its documentation comments, in one folder (`src/ioc/`). The tests\\n  and the docs check come with it.\"},{\"Path\":\"docs/evaluating.md\",\"Title\":\"Evaluating @fathym/ioc › The honest risks\",\"Text\":\"- **It is young.** The stable API dates from November 2026 and the user base is small, so there\\n  are fewer answers online than for InversifyJS, awilix or tsyringe.\\n- **Resolution is always asynchronous.** Every `Resolve` returns a promise. A resolve takes about a\\n  microsecond where the synchronous containers take a tenth of that or less; the\\n  [comparison](./reference/comparison.md#benchmarks) has the numbers. That rarely matters for an\\n  application, but code that must resolve synchronously can't use it.\\n- **Wiring is explicit.** Each class lists its `Deps`. The compiler checks them against the\\n  constructor, and `Validate()` checks the whole graph, but it is more code than auto-wiring.\\n- **Some advanced features are left out on purpose:** property injection, contextual bindings and\\n  auto-registration by scanning files.\"},{\"Path\":\"docs/evaluating.md\",\"Title\":\"Evaluating @fathym/ioc › Adopting it safely\",\"Text\":\"1. **Pin to the major version** (`^1` on npm or JSR), and read the changelog when you take a minor\\n   release.\\n2. **Validate the wiring in a test**, so a broken graph fails CI rather than a deploy:\\n\\n   ```ts ignore\\n   // A fragment from a test file: build the app's container the way main.ts does, then check it.\\n   Deno.test('the container is wired correctly', () => {\\n     const app = buildContainer();\\n\\n     app.Validate(); // throws IoCValidationError listing every problem\\n   });\\n   ```\\n\\n3. **Start with one bounded service,** where async initialization and clean shutdown matter most,\\n   then expand.\\n4. **Check our claims yourself:** `deno task compare` re-runs the comparison, and every\\n   [guarantee](./reference/guarantees.md) links to its test.\"},{\"Path\":\"docs/evaluating.md\",\"Title\":\"Evaluating @fathym/ioc › What's Next\",\"Text\":\"- Five short steps from a first container to tests: [getting started](./getting-started/README.md)\\n  _[Tutorial]_\\n- What the container promises, with proof: [guarantees](./reference/guarantees.md) _[Reference]_\\n- What may change between releases: [versioning and support policy](./policy.md) _[Reference]_\"},{\"Path\":\"docs/getting-started/README.md\",\"Title\":\"Getting Started\",\"Text\":\"In about fifteen minutes you'll build a small **notes API** on `Deno.serve`. Along the way you'll\\nlearn what you need for most apps:\\n\\n- **registering services** (classes, factories, values);\\n- **resolving** them;\\n- **async services** such as Deno KV, checked and built at startup;\\n- **giving each HTTP request its own scope**;\\n- **packaging the app as a module** and **swapping a dependency in a test**.\\n\\nEach step introduces one idea with a small notes app, and every code block is a complete program\\nyou can run. The steps share names (`NotesStore`, `Clock`), but each program stands on its own;\\n[`examples/per-request-server.ts`](../../examples/per-request-server.ts) puts them together.\\n\\n> **Note:** You need [Deno](https://deno.com) 2.x. Steps 3 and 5 use Deno KV, so run them with\\n> `--unstable-kv`; step 4 runs a server, so it needs `--allow-net`.\\n\\n| Step | Document                                                      | You'll learn                                                           |\\n| ---- | ------------------------------------------------------------- | ---------------------------------------------------------------------- |\\n| 1    | [installation.md](./installation.md) _[Tutorial]_             | Add the package and import it                                          |\\n| 2    | [first-container.md](./first-container.md) _[Tutorial]_       | Register and resolve classes, factories, values and typed tokens       |\\n| 3    | [async-services.md](./async-services.md) _[Tutorial]_         | Open Deno KV from an async factory, check the wiring, build it at boot |\\n| 4    | [per-request-scopes.md](./per-request-scopes.md) _[Tutorial]_ | Give every HTTP request its own scope                                  |\\n| 5    | [testing-your-app.md](./testing-your-app.md) _[Tutorial]_     | Put the wiring in a module, and swap the store for a fake in a test    |\\n\\nWhen you're done, the [API reference](../reference/api.md) lists every method and option, the\\n[error catalog](../reference/errors.md) explains every error message, and the\\n[examples](../../examples/README.md) are small programs you can run and copy.\\n\\nStart with [step 1: installation](./installation.md).\"},{\"Path\":\"docs/getting-started/async-services.md\",\"Title\":\"Step 3: Async Services\",\"Text\":\"> **Goal:** Store notes in Deno KV. Opening a database is asynchronous, which is exactly what this\\n> container is built for.\"},{\"Path\":\"docs/getting-started/async-services.md\",\"Title\":\"Step 3: Async Services › Register an async factory\",\"Text\":\"```ts\\nimport { IoCContainer } from '@fathym/ioc';\\n\\nclass NotesStore {\\n  constructor(private kv: Deno.Kv) {}\\n\\n  public async add(text: string): Promise<void> {\\n    await this.kv.set(['notes', crypto.randomUUID()], text);\\n  }\\n\\n  public async list(): Promise<string[]> {\\n    const notes: string[] = [];\\n\\n    for await (const entry of this.kv.list<string>({ prefix: ['notes'] })) {\\n      notes.push(entry.value);\\n    }\\n\\n    return notes;\\n  }\\n}\\n\\nawait using ioc = new IoCContainer() // disposed (KV closed) at the end of the program\\n  .Typed()\\n  // Deno.Kv is a class, so it works as a key. The factory is async; that's fine.\\n  .RegisterFactory(Deno.Kv, () => Deno.openKv(':memory:'))\\n  .RegisterClass(NotesStore, { Deps: [Deno.Kv] });\\n\\nawait ioc.Start(); // checks the wiring; builds nothing\\nawait ioc.Activate(); // opens KV now, so a bad connection fails at startup\\n\\nconst store = await ioc.Resolve(NotesStore);\\n\\nawait store.add('Buy milk');\\n\\nconsole.log(await store.list()); // [ \\\"Buy milk\\\" ]\\n```\\n\\nRun it with `deno run --unstable-kv main.ts`.\"},{\"Path\":\"docs/getting-started/async-services.md\",\"Title\":\"Step 3: Async Services › What just happened\",\"Text\":\"- **Nothing is built at registration.** A singleton is built the first time something needs it.\\n- **`Start()` checks the wiring.** It runs `Validate()`, which reports every missing, cyclic or\\n  captive dependency at once, then starts the app's modules (you'll write one in step 5). It\\n  doesn't build services.\\n- **`Activate()` builds every singleton now.** It reports all failures together in one\\n  `IoCActivationError`. That's how you get lazy registration _and_ fail-fast startup.\\n- **Concurrent resolves share one creation.** If ten requests resolve `NotesStore` at the same\\n  moment, KV is still opened once.\\n- **A failed creation is retried, not cached.** If KV isn't reachable on the first try, the next\\n  resolve (or `Activate()`) tries again.\\n- **Disposing the container cleans up what it created.** `await using` calls `Dispose()` when\\n  `ioc` goes out of scope. `Deno.Kv` implements `Symbol.dispose`, so the container closes it.\\n  Things are disposed last created, first disposed. A value you register with `RegisterValue` is\\n  yours: the container doesn't dispose it unless you pass a `Dispose` option.\\n- **Nothing waits forever.** A resolve that is still pending after 30 seconds fails with an\\n  `IoCResolveTimeoutError` naming the service. `new IoCContainer({ PendingTimeoutMs })` changes\\n  the limit; `0` turns it off.\\n\\n> **Note:** `Resolve` is always `async`, even for services that aren't. One rule, everywhere: you\\n> never have to know whether a dependency's setup is async.\"},{\"Path\":\"docs/getting-started/async-services.md\",\"Title\":\"Step 3: Async Services › What's Next\",\"Text\":\"- Give each HTTP request its own scope: [per-request-scopes.md](./per-request-scopes.md)\\n  _[Tutorial]_\\n- `Start()`, `Activate()`, `Dispose()` and their options in full:\\n  [api.md](../reference/api.md) _[Reference]_\\n- What each startup error means and how to fix it: [errors.md](../reference/errors.md)\\n  _[Reference]_\"},{\"Path\":\"docs/getting-started/first-container.md\",\"Title\":\"Step 2: Your First Container\",\"Text\":\"> **Goal:** Wire up the core of the notes app. You'll register services three different ways and\\n> resolve them without writing a single `new` for the app's objects.\"},{\"Path\":\"docs/getting-started/first-container.md\",\"Title\":\"Step 2: Your First Container › What you'll build\",\"Text\":\"A `NotesService` that stamps each note with the time from a `Clock`, plus the app's name as a\\nplain value.\"},{\"Path\":\"docs/getting-started/first-container.md\",\"Title\":\"Step 2: Your First Container › Register and resolve\",\"Text\":\"```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\n// A typed token: a key that carries the type of what's registered under it.\\nconst $AppName = IoCToken<string, 'AppName'>('AppName');\\n\\nclass Clock {\\n  public now(): Date {\\n    return new Date();\\n  }\\n}\\n\\nclass NotesService {\\n  readonly #notes: string[] = [];\\n\\n  constructor(private clock: Clock) {}\\n\\n  public add(text: string): string {\\n    const note = `${this.clock.now().toISOString()} ${text}`;\\n    this.#notes.push(note);\\n    return note;\\n  }\\n\\n  public list(): string[] {\\n    return [...this.#notes];\\n  }\\n}\\n\\nconst ioc = new IoCContainer();\\n\\nioc.RegisterValue($AppName, 'Notes'); // 1. a value you already have\\nioc.RegisterClass(Clock); // 2. a class the container constructs\\nioc.RegisterFactory(NotesService, async (c) => new NotesService(await c.Resolve(Clock))); // 3. a factory\\n\\nconst notes = await ioc.Resolve(NotesService);\\n\\nnotes.add('Buy milk');\\n\\nconsole.log(await ioc.Resolve($AppName), notes.list());\\n// Notes [ \\\"2026-10-13T12:00:00.000Z Buy milk\\\" ]\\n```\\n\\nThree things to notice:\\n\\n1. **`Resolve($AppName)` returns a `string`.** The token carries the type, so there is no generic\\n   to write and nothing to cast.\\n2. **The factory receives the container (`c`).** Resolve dependencies through that parameter,\\n   not through a captured `ioc`. It's what makes scopes, overrides and immediate cycle detection\\n   work later.\\n3. **You never called `new Clock()`.** The container did.\\n\\n> **Note:** A token is its name: `IoCToken('AppName')` is `Symbol.for('AppName')`, so every call\\n> with the same name, in any package, gives the same key. Pick names that won't collide with other\\n> packages (`'notes/AppName'`), declare each token once, and import it wherever you need it. A\\n> class key is the class itself, so two different classes named `Clock` are two different keys.\"},{\"Path\":\"docs/getting-started/first-container.md\",\"Title\":\"Step 2: Your First Container › Let the container call the constructor\",\"Text\":\"Writing a factory just to pass dependencies along gets repetitive. Declare the dependencies\\ninstead, and the container checks them against the constructor's parameters at compile time:\\n\\n```ts\\nimport { IoCContainer } from '@fathym/ioc';\\n\\nclass Clock {\\n  public now(): Date {\\n    return new Date();\\n  }\\n}\\n\\nclass NotesService {\\n  constructor(public clock: Clock) {}\\n}\\n\\nconst ioc = new IoCContainer();\\n\\nioc.RegisterClass(Clock);\\nioc.RegisterClass(NotesService, { Deps: [Clock] }); // a type error if NotesService's constructor changes\\n\\nconst notes = await ioc.Resolve(NotesService);\\n\\nconsole.log(notes.clock instanceof Clock); // true\\n```\"},{\"Path\":\"docs/getting-started/first-container.md\",\"Title\":\"Step 2: Your First Container › Catch missing registrations at compile time\",\"Text\":\"`Deps` checks types, but on its own it can't tell whether `Clock` was registered at all. Make the\\ncontainer **typed** and chain the registrations. Then `Deps` may only name what's registered\\nabove it:\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $AppName = IoCToken<string, 'AppName'>('AppName');\\n\\nclass Clock {\\n  public now(): Date {\\n    return new Date();\\n  }\\n}\\n\\nclass NotesService {\\n  constructor(public clock: Clock, public appName: string) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  .Typed()\\n  .RegisterValue($AppName, 'Notes')\\n  .RegisterClass(Clock)\\n  .RegisterClass(NotesService, { Deps: [Clock, $AppName] });\\n\\nconst notes = await ioc.Resolve(NotesService);\\n\\nconsole.log(notes.appName); // Notes\\n```\\n\\nMove `.RegisterClass(Clock)` below `NotesService` and the code no longer compiles. The error names\\nwhat is registered so far, so you know what to move. Typed containers are optional; later steps\\nuse them where they help.\"},{\"Path\":\"docs/getting-started/first-container.md\",\"Title\":\"Step 2: Your First Container › Same instance, or a new one?\",\"Text\":\"By default every service is a **singleton**: built once and shared. Ask for a **transient**\\nlifetime when you want a fresh instance on every resolve:\\n\\n```ts\\nimport { IoCContainer } from '@fathym/ioc';\\n\\nclass Draft {\\n  public text = '';\\n}\\n\\nclass Clock {}\\n\\nconst ioc = new IoCContainer();\\n\\nioc.RegisterClass(Clock); // singleton (the default)\\nioc.RegisterClass(Draft, { Lifetime: 'transient' });\\n\\nconsole.log((await ioc.Resolve(Clock)) === (await ioc.Resolve(Clock))); // true\\nconsole.log((await ioc.Resolve(Draft)) === (await ioc.Resolve(Draft))); // false\\n```\\n\\nThere's a third lifetime, `scoped`, which you'll use in [step 4](./per-request-scopes.md).\"},{\"Path\":\"docs/getting-started/first-container.md\",\"Title\":\"Step 2: Your First Container › What's Next\",\"Text\":\"- Start an async service (Deno KV) and check the wiring at startup:\\n  [async-services.md](./async-services.md) _[Tutorial]_\\n- Every registration option and lifetime: [api.md](../reference/api.md) _[Reference]_\"},{\"Path\":\"docs/getting-started/installation.md\",\"Title\":\"Step 1: Installation\",\"Text\":\"> **Goal:** Add the container to your project and confirm the import works.\"},{\"Path\":\"docs/getting-started/installation.md\",\"Title\":\"Step 1: Installation › Deno\",\"Text\":\"```sh\\ndeno add jsr:@fathym/ioc\\n```\\n\\nThis adds an entry to your `deno.json` import map:\\n\\n```jsonc\\n{\\n  \\\"imports\\\": {\\n    \\\"@fathym/ioc\\\": \\\"jsr:@fathym/ioc@^1.0.0\\\"\\n  }\\n}\\n```\"},{\"Path\":\"docs/getting-started/installation.md\",\"Title\":\"Step 1: Installation › Node.js and Bun\",\"Text\":\"The package is published on [npm](https://www.npmjs.com/package/@fathym/ioc):\\n\\n```sh\\nnpm install @fathym/ioc         # npm\\nbun add @fathym/ioc             # Bun\\npnpm add @fathym/ioc            # pnpm\\nyarn add @fathym/ioc            # Yarn\\n```\\n\\nEvery stable release is published to npm and [JSR](https://jsr.io/@fathym/ioc) with the same\\nversion, so you can also install it from JSR (`npx jsr add @fathym/ioc`,\\n`bunx jsr add @fathym/ioc`, `pnpm add jsr:@fathym/ioc`).\\n\\nYou import it as `@fathym/ioc` either way. It is plain ESM with no runtime dependencies, and it\\nimports no Deno, Node.js or browser modules.\"},{\"Path\":\"docs/getting-started/installation.md\",\"Title\":\"Step 1: Installation › Requirements\",\"Text\":\"| What                    | Supported                                         | Checked in CI                                   |\\n| ----------------------- | ------------------------------------------------- | ----------------------------------------------- |\\n| Deno                    | 2.x                                               | the full test suite                             |\\n| Node.js                 | 20 and later                                      | a smoke test on 20, 22 and 24                   |\\n| Bun                     | 1.x                                               | a smoke test                                    |\\n| TypeScript              | 5.4 and later                                     | a consumer type-checked with 5.4 and the latest |\\n| Browsers, workers, edge | any runtime with ES2022 and `Symbol.asyncDispose` | not yet                                         |\\n\\n**TypeScript settings.** The types use `Symbol.asyncDispose`, so your `lib` needs\\n`esnext.disposable` (or `esnext`), or turn on `skipLibCheck` (most project templates do). Using\\n`await using` in your own code needs that `lib` anyway:\\n\\n```jsonc\\n{\\n  \\\"compilerOptions\\\": {\\n    \\\"target\\\": \\\"ES2022\\\",\\n    \\\"lib\\\": [\\\"ES2022\\\", \\\"ESNext.Disposable\\\"]\\n  }\\n}\\n```\\n\\n> **Note:** A class key is the class itself, so minifying class names never changes which\\n> service you get. Errors and `Describe()` print class names, though: keep them readable with\\n> `keepNames: true` in esbuild and Vite (`keep_classnames: true` in Terser).\\n\\n**Runtimes without explicit resource management.** `await using` needs runtime support (or a\\ncompiler that down-levels it). Without it, call `await scope.Dispose()` yourself.\"},{\"Path\":\"docs/getting-started/installation.md\",\"Title\":\"Step 1: Installation › Check it works\",\"Text\":\"Create `main.ts`:\\n\\n```ts\\nimport { IoCContainer } from '@fathym/ioc';\\n\\nclass Greeter {\\n  public greet(name: string): string {\\n    return `Hello, ${name}!`;\\n  }\\n}\\n\\nconst ioc = new IoCContainer();\\n\\nioc.RegisterClass(Greeter);\\n\\nconst greeter = await ioc.Resolve(Greeter);\\n\\nconsole.log(greeter.greet('IoC'));\\n```\\n\\nRun it:\\n\\n```sh\\ndeno run main.ts\\n# Hello, IoC!\\n```\\n\\nThat's the whole loop: **register** a service, then **resolve** it. The container builds the\\n`Greeter` for you and hands back the same instance every time you ask, because services are\\nsingletons unless you say otherwise.\"},{\"Path\":\"docs/getting-started/installation.md\",\"Title\":\"Step 1: Installation › What's Next\",\"Text\":\"- Register classes, factories and values, and meet typed tokens:\\n  [first-container.md](./first-container.md) _[Tutorial]_\\n- Every registration method and option: [api.md](../reference/api.md) _[Reference]_\"},{\"Path\":\"docs/getting-started/per-request-scopes.md\",\"Title\":\"Step 4: Per-Request Scopes\",\"Text\":\"> **Goal:** Serve the notes API over HTTP, with services that belong to a single request, such as\\n> the request itself and a request ID.\"},{\"Path\":\"docs/getting-started/per-request-scopes.md\",\"Title\":\"Step 4: Per-Request Scopes › Create a scope per request\",\"Text\":\"```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Request = IoCToken<Request, 'Request'>('Request');\\n\\nclass RequestContext {\\n  public readonly id = crypto.randomUUID();\\n}\\n\\nclass NotesHandler {\\n  constructor(private ctx: RequestContext, private req: Request) {}\\n\\n  public handle(): Response {\\n    return Response.json({ requestId: this.ctx.id, path: new URL(this.req.url).pathname });\\n  }\\n}\\n\\nconst ioc = new IoCContainer()\\n  .Typed()\\n  .Expect($Request) // registered on each request's scope, below\\n  .RegisterClass(RequestContext, { Lifetime: 'scoped' })\\n  .RegisterClass(NotesHandler, { Deps: [RequestContext, $Request], Lifetime: 'transient' });\\n\\nconst server = Deno.serve({ port: 0, onListen() {} }, async (req) => {\\n  await using scope = ioc.CreateScope(); // disposed when the handler returns\\n\\n  scope.RegisterValue($Request, req); // this request only\\n\\n  return (await scope.Resolve(NotesHandler)).handle();\\n});\\n\\nconst res = await fetch(`http://localhost:${server.addr.port}/notes`);\\n\\nconsole.log(await res.json()); // { requestId: \\\"…\\\", path: \\\"/notes\\\" }\\n\\nawait server.shutdown();\\n```\\n\\nRun it with `deno run --allow-net main.ts`.\"},{\"Path\":\"docs/getting-started/per-request-scopes.md\",\"Title\":\"Step 4: Per-Request Scopes › What just happened\",\"Text\":\"- **`CreateScope()` makes a cheap child container.** It can resolve everything the root can.\\n  Nothing is copied. A scope that owns something to dispose (a disposable scoped instance) is\\n  tracked by the root, so even a forgotten scope is closed when the root is disposed. This one\\n  owns nothing to dispose, so it isn't tracked at all.\\n- **`scoped` services get one instance per scope.** Every service in this request shares the same\\n  `RequestContext`; the next request gets a new one.\\n- **Registrations on a scope stay in that scope.** `$Request` exists only inside this request's\\n  scope. `Expect($Request)` tells the typed container it will be there, so `Deps` may name it,\\n  and `Validate()` counts it as registered. A scope may also register a key the root already has;\\n  its registration wins inside the scope.\\n- **Transient services built in a scope receive the scope.** That's how `NotesHandler` sees this\\n  request's `$Request` and `RequestContext`.\\n- **`await using` disposes the scope** when the handler finishes, disposing the scoped instances\\n  it built.\\n\\n> **Warning:** A scope is a child container _you_ create. It is not tied to an HTTP request\\n> unless you create one per request, as above. A singleton is built once, by the container it is\\n> registered in, and shared by every scope. Resolving a `scoped` service from the root throws\\n> `IoCScopeRequiredError`, and `Validate()` reports a singleton that depends on a scoped service\\n> (a `captive`), so one request's data can't leak into a shared instance.\"},{\"Path\":\"docs/getting-started/per-request-scopes.md\",\"Title\":\"Step 4: Per-Request Scopes › What's Next\",\"Text\":\"- Swap the store for a fake in a test: [testing-your-app.md](./testing-your-app.md) _[Tutorial]_\\n- `CreateScope()`, `Isolate()` and lifetimes in full: [api.md](../reference/api.md) _[Reference]_\\n- A complete server with a scope per request and graceful shutdown:\\n  [examples/per-request-server.ts](../../examples/per-request-server.ts) _[Example]_\"},{\"Path\":\"docs/getting-started/testing-your-app.md\",\"Title\":\"Step 5: Testing Your App\",\"Text\":\"> **Goal:** Package the app's wiring as a module, then test `NotesService` without a real\\n> database by swapping the store for a fake.\\n\\nDeno doesn't support Jest-style module mocking. That's fine: the container _is_ the seam. Put the\\nreal wiring in a module, add it to a test container, and override the one service you want to\\nfake.\"},{\"Path\":\"docs/getting-started/testing-your-app.md\",\"Title\":\"Step 5: Testing Your App › Put the wiring in a module\",\"Text\":\"A module is a named set of registrations, with optional `OnStart` and `OnStop` hooks. Its\\n`Register`, `OnStart` and `OnStop` each receive the container. `main.ts` and the tests both add\\nthe same module with `Use()`:\\n\\n```ts\\nimport { DefineModule, IoCContainer } from '@fathym/ioc';\\n\\nclass NotesService {\\n  public list(): string[] {\\n    return [];\\n  }\\n}\\n\\n// notes-app.ts: the app's real wiring.\\nconst NotesApp = DefineModule({\\n  Name: 'NotesApp',\\n  Register: (ioc) => ioc.RegisterClass(NotesService),\\n  OnStart: () => console.log('notes ready'),\\n  OnStop: () => console.log('notes stopped'),\\n});\\n\\n// main.ts\\nawait using ioc = new IoCContainer().Use(NotesApp);\\n\\nawait ioc.Start(); // validates the wiring, then runs OnStart: notes ready\\n\\nconsole.log((await ioc.Resolve(NotesService)).list()); // []\\n\\n// At the end of the program, `await using` disposes the container: notes stopped\\n```\"},{\"Path\":\"docs/getting-started/testing-your-app.md\",\"Title\":\"Step 5: Testing Your App › Override a dependency in a test\",\"Text\":\"```ts\\nimport { assertEquals } from 'jsr:@std/assert@1.0.16';\\nimport { DefineModule, IoCContainer } from '@fathym/ioc';\\n\\n// The abstract class is the key; the app and the test provide different implementations.\\nabstract class NotesStore {\\n  public abstract add(text: string): Promise<void>;\\n  public abstract list(): Promise<string[]>;\\n}\\n\\nclass KvNotesStore extends NotesStore {\\n  constructor(private kv: Deno.Kv) {\\n    super();\\n  }\\n\\n  public async add(text: string) {\\n    await this.kv.set(['notes', crypto.randomUUID()], text);\\n  }\\n\\n  public async list() {\\n    const notes: string[] = [];\\n    for await (const e of this.kv.list<string>({ prefix: ['notes'] })) notes.push(e.value);\\n    return notes;\\n  }\\n}\\n\\nclass NotesService {\\n  constructor(private store: NotesStore) {}\\n\\n  public async addNote(text: string): Promise<string[]> {\\n    await this.store.add(text.trim());\\n    return await this.store.list();\\n  }\\n}\\n\\n// The app's real wiring, shared by main.ts and the tests.\\nconst NotesApp = DefineModule({\\n  Name: 'NotesApp',\\n  Register: (ioc) =>\\n    ioc\\n      .RegisterFactory(Deno.Kv, () => Deno.openKv(':memory:'))\\n      .RegisterFactory(NotesStore, (_ioc, kv) => new KvNotesStore(kv), { Deps: [Deno.Kv] })\\n      .RegisterClass(NotesService, { Deps: [NotesStore] }),\\n});\\n\\nDeno.test('the real wiring is valid', () => {\\n  new IoCContainer().Use(NotesApp).Validate(); // throws IoCValidationError if anything is missing\\n});\\n\\nDeno.test('NotesService trims notes before saving', async () => {\\n  await using ioc = new IoCContainer().Use(NotesApp);\\n\\n  const saved: string[] = [];\\n\\n  ioc.Override(NotesStore, {\\n    add: (text) => Promise.resolve(void saved.push(text)),\\n    list: () => Promise.resolve(saved),\\n  });\\n\\n  const service = await ioc.Resolve(NotesService);\\n\\n  assertEquals(await service.addNote('  Buy milk  '), ['Buy milk']);\\n});\\n```\\n\\nRun it with `deno test --unstable-kv`.\"},{\"Path\":\"docs/getting-started/testing-your-app.md\",\"Title\":\"Step 5: Testing Your App › Why this works\",\"Text\":\"- **The test uses the real wiring** (`NotesApp`), so the first test also proves the registrations\\n  are right.\\n- **`Override()` works on any container.** It replaces the registration with a value and returns\\n  a function that puts back exactly what was there before. Use that function when a container is\\n  shared across tests; here each test makes its own, and `await using` disposes it when the test\\n  ends.\\n- **Override before you resolve.** `NotesService` is a singleton; it is built on the first\\n  `Resolve`, after the override, so it receives the fake. An instance built earlier keeps what it\\n  was given.\\n- **The real KV store is never opened.** Nothing is built at registration, and nothing resolves\\n  it.\\n\\n> **Note:** You can also register a fake on a scope (`ioc.CreateScope().RegisterValue(...)`),\\n> which leaves the container itself untouched. Scope registrations reach **transient and scoped**\\n> services resolved from the scope; a singleton is built by the container it was registered in.\"},{\"Path\":\"docs/getting-started/testing-your-app.md\",\"Title\":\"Step 5: Testing Your App › You're done\",\"Text\":\"You've used most of what you'll need day to day:\\n\\n- **registration:** classes, factories, values and tokens;\\n- **lifetimes:** singleton, transient and scoped;\\n- **async startup** with `Start()` and `Activate()`;\\n- **per-request scopes** with disposal;\\n- **modules** that package the wiring, with start and stop hooks;\\n- **test overrides** with `Override()`.\"},{\"Path\":\"docs/getting-started/testing-your-app.md\",\"Title\":\"Step 5: Testing Your App › What's Next\",\"Text\":\"- Every method, option and type: [api.md](../reference/api.md) _[Reference]_\\n- Every error message, its cause and the fix: [errors.md](../reference/errors.md) _[Reference]_\\n- Modules that require each other, defaults the app replaces, and a failed start that is retried:\\n  [examples/modules-lifecycle.ts](../../examples/modules-lifecycle.ts) _[Example]_\\n- Coming from 0.x: [from-0.x.md](../migration/from-0.x.md) _[How-to]_\"},{\"Path\":\"docs/guides/README.md\",\"Title\":\"Guides\",\"Text\":\"Recipes for one task each. To learn the container step by step, start with\\n[getting started](../getting-started/README.md).\\n\\n| Guide                                                                | What it shows                                                          |\\n| -------------------------------------------------------------------- | ---------------------------------------------------------------------- |\\n| [Registering many modules](./registering-many-modules.md) _[How-to]_ | Add a folder of modules with one call, without a file-scanning step    |\\n| [Working with AI coding agents](./ai-coding-agents.md) _[How-to]_    | Teach Claude Code, Cursor or Copilot the conventions, and the fix loop |\"},{\"Path\":\"docs/guides/ai-coding-agents.md\",\"Title\":\"Working with AI coding agents\",\"Text\":\"> **Goal:** have an AI coding agent write and change `@fathym/ioc` wiring correctly the first\\n> time, and fix it on its own when it doesn't.\\n\\n`@fathym/ioc` keeps the wiring explicit: every registration and every `Deps` list is in the code,\\nchecked by the compiler, and checked again by `Validate()`. That gives an agent something it can\\nread and a loop it can follow. Three things make the most of it.\"},{\"Path\":\"docs/guides/ai-coding-agents.md\",\"Title\":\"Working with AI coding agents › 1. Install the agent kit\",\"Text\":\"The kit is the library's conventions written for agents, as each tool's instruction file:\\n\\n```sh\\ndeno run -A jsr:@fathym/ioc/init-agents\\n```\\n\\nIt writes:\\n\\n| File                                 | Read by                           |\\n| ------------------------------------ | --------------------------------- |\\n| `.claude/skills/fathym-ioc/SKILL.md` | Claude Code (as a skill)          |\\n| `.cursor/rules/fathym-ioc.mdc`       | Cursor                            |\\n| `AGENTS.md` (a marked section)       | Codex and other `AGENTS.md` tools |\\n| `.github/copilot-instructions.md`    | GitHub Copilot                    |\\n\\nPick some with `--targets=claude,agents-md`. Running it again updates the `@fathym/ioc` section\\nof `AGENTS.md` and the Copilot file without touching the rest. From Node.js or Bun, call\\n`writeAgentKit()` from `@fathym/ioc/agents`, or read the rules as text from `IOC_AGENT_RULES`.\"},{\"Path\":\"docs/guides/ai-coding-agents.md\",\"Title\":\"Working with AI coding agents › 2. Point the agent at the full docs\",\"Text\":\"[`llms-full.txt`](https://raw.githubusercontent.com/fathym/ioc/main/llms-full.txt) holds every docs\\npage and example program in one file, and [`llms.txt`](https://raw.githubusercontent.com/fathym/ioc/main/llms.txt)\\nis its index. Every code example in both is type-checked and run in CI, so an agent that reads\\nthem copies code that works.\"},{\"Path\":\"docs/guides/ai-coding-agents.md\",\"Title\":\"Working with AI coding agents › 3. Let it use the fix loop\",\"Text\":\"The kit teaches this loop; it works because each step returns something an agent can act on:\\n\\n1. **The compiler** rejects `Deps` that don't match the constructor (order, count or type).\\n2. **`Validate()`** lists every wiring problem at once, each with a `Fix:` line:\\n\\n   ```ts\\n   import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\n   class Repo {\\n     constructor(public url: string) {}\\n   }\\n\\n   const $Url = IoCToken<string, 'app/Url'>('app/Url');\\n\\n   const issues = new IoCContainer().RegisterClass(Repo, { Deps: [$Url] }).Validate({\\n     Throw: false,\\n   });\\n\\n   console.log(issues[0].Hint); // Register app/Url with RegisterClass, RegisterFactory or RegisterValue, …\\n   ```\\n\\n3. **Runtime errors** have a stable `code` and a `DocsUrl` that opens the code's section of the\\n   [error catalog](../reference/errors.md#error-codes), with the cause and the fix.\\n\\nKeep a test that builds the container and calls `Validate()`, so the agent finds wiring mistakes\\nby running the tests, not by running the app.\"},{\"Path\":\"docs/guides/ai-coding-agents.md\",\"Title\":\"Working with AI coding agents › What's Next\",\"Text\":\"- The conventions in full: [`src/agents/rules.ts`](../../src/agents/rules.ts) _[Reference]_\\n- Every error code and its fix: [errors.md](../reference/errors.md#error-codes) _[Reference]_\\n- Every guide: [guides](./README.md) _[How-to]_\"},{\"Path\":\"docs/guides/registering-many-modules.md\",\"Title\":\"Registering many modules\",\"Text\":\"> **Goal:** register every module in a folder with one call, and keep adding modules without\\n> touching the app's startup code.\\n\\nSome containers scan the file system and register whatever they find by naming convention. That\\nneeds file-system access at startup and a glob library, and it hides the wiring. With\\n@fathym/ioc, a module already carries its own registrations and lifecycle, so all you need is one\\nlist of modules. Two ways to keep that list:\"},{\"Path\":\"docs/guides/registering-many-modules.md\",\"Title\":\"Registering many modules › A barrel file\",\"Text\":\"Give the folder one file that lists its modules. Adding a module is one line there:\\n\\n```ts ignore\\n// modules/mod.ts: a fragment showing the barrel file itself.\\nimport { Database } from './database.ts';\\nimport { Mailer } from './mailer.ts';\\nimport { Api } from './api.ts';\\n\\nexport const AppModules = [Database, Mailer, Api] as const;\\n```\\n\\nThe app then adds them all at once. `Use()` also adds each module's `Requires` for you, and\\n`Start()` starts them in dependency order, so the order in the list doesn't matter:\\n\\n```ts\\nimport { DefineModule, IoCContainer, IoCToken } from '@fathym/ioc';\\n\\ninterface Db {\\n  query(sql: string): Promise<string[]>;\\n}\\n\\nconst $Db = IoCToken<Db, 'app/Db'>('app/Db');\\n\\n// These three would live in modules/database.ts, modules/mailer.ts and modules/api.ts.\\nconst Database = DefineModule({\\n  Name: 'Database',\\n  Register: (ioc) => ioc.RegisterValue($Db, { query: async () => ['ada'] }),\\n  OnStart: () => console.log('database connected'),\\n});\\n\\nconst Mailer = DefineModule({\\n  Name: 'Mailer',\\n  Register: (ioc) => ioc,\\n  OnStart: () => console.log('mailer ready'),\\n});\\n\\nconst Api = DefineModule({\\n  Name: 'Api',\\n  Requires: [Database],\\n  Register: (ioc) => ioc,\\n  OnStart: () => console.log('api listening'),\\n});\\n\\n// modules/mod.ts\\nconst AppModules = [Api, Mailer, Database] as const;\\n\\n// main.ts\\nawait using app = new IoCContainer().Use(...AppModules);\\n\\nawait app.Start(); // database connected, api listening, mailer ready\\n\\nconsole.log(await (await app.Resolve($Db)).query('select name from users')); // ['ada']\\n```\\n\\nKeeping the list `as const` keeps the types: on a [typed container](../reference/api.md#typed),\\n`Use(...AppModules)` checks every module's `Needs` and adds what each one provides.\"},{\"Path\":\"docs/guides/registering-many-modules.md\",\"Title\":\"Registering many modules › `import.meta.glob` under Vite\",\"Text\":\"Vite (and Vitest) can collect a folder at build time, so new files are picked up without editing a\\nlist. Every export that looks like a module is added:\\n\\n```ts ignore\\n// A fragment: import.meta.glob is provided by Vite, not by Deno, Node.js or Bun.\\nimport { IoCContainer, type IoCModule } from '@fathym/ioc';\\n\\nconst files = import.meta.glob<Record<string, unknown>>('./modules/*.ts', { eager: true });\\n\\nconst isModule = (value: unknown): value is IoCModule =>\\n  typeof (value as IoCModule)?.Name === 'string' &&\\n  typeof (value as IoCModule)?.Register === 'function';\\n\\nconst modules = Object.values(files).flatMap((file) => Object.values(file).filter(isModule));\\n\\nawait using app = new IoCContainer().Use(...modules);\\n\\nawait app.Start();\\n```\\n\\nThe glob version gives up the compile-time `Needs` check, because the list is only known when\\nthe bundle is built. `Start()` still validates the wiring and fails with every problem listed.\"},{\"Path\":\"docs/guides/registering-many-modules.md\",\"Title\":\"Registering many modules › What's Next\",\"Text\":\"- `Use()`, `Requires` and `DefineModule` in detail: [api.md](../reference/api.md#modules)\\n  _[Reference]_\\n- Modules that require each other, defaults the app replaces, and a failed start that is retried:\\n  [examples/modules-lifecycle.ts](../../examples/modules-lifecycle.ts) _[Example]_\\n- Every guide: [guides](./README.md) _[How-to]_\"},{\"Path\":\"docs/migration/README.md\",\"Title\":\"Migration\",\"Text\":\"| Guide                                   | For you if…                                                               |\\n| --------------------------------------- | ------------------------------------------------------------------------- |\\n| [from-0.x.md](./from-0.x.md) _[How-to]_ | You use `@fathym/ioc` 0.0.x (up to 0.0.36) or 0.1.x and are moving to 1.0 |\\n\\nThe guide starts with a table of old and new calls, then explains each change.\\n\\nFrom 1.0, breaking changes only come in major releases, each with its own guide here. The\\n[versioning and support policy](../policy.md) says what counts as breaking and how long a\\ndeprecated API keeps working.\"},{\"Path\":\"docs/migration/from-0.x.md\",\"Title\":\"Migrating from 0.x to 1.0\",\"Text\":\"> **Goal:** Move code written for `@fathym/ioc` 0.0.x (up to 0.0.36) or 0.1.x to 1.0, and know\\n> exactly what behaves differently.\\n\\n**Keys don't change.** A 1.0 token is `Symbol.for(name)`, as 0.x keys were, so `IoCToken('Db')`\\nand a `Symbol.for('Db')` key in code you haven't migrated yet are the same key. Most changes are\\nmechanical: explicit registration methods, no modes to configure, and modules instead of copying\\ncontainers. The compiler finds most of them.\\n\\nA 1.0 container and a 0.x container are different classes and don't share registrations, so\\nevery package that shares one container moves to 1.0 in the same release.\"},{\"Path\":\"docs/migration/from-0.x.md\",\"Title\":\"Migrating from 0.x to 1.0 › Old call → new call\",\"Text\":\"Rows marked _0.0.x_ only apply when you come from 0.0.x; rows marked _0.1_ only from 0.1.\\n\\n| 0.x                                                                  | 1.0                                                                            | Notes                                                     |\\n| -------------------------------------------------------------------- | ------------------------------------------------------------------------------ | --------------------------------------------------------- |\\n| `ioc.Register(Clock)`, `Register(Clock, { Lifetime })`               | `ioc.RegisterClass(Clock, { Lifetime })`                                       | Add `Deps` when the constructor takes parameters          |\\n| `Register(PgDb, { Type: sym })`                                      | `RegisterClass(PgDb, { Type: $Db })`                                           | The class must satisfy the token's type                   |\\n| `Register(Cache, (c) => …)`, `Register(sym, (c) => …)`               | `RegisterFactory(Cache, (c) => …)`, `RegisterFactory($Token, (c) => …)`        |                                                           |\\n| `const remove = Register(…); remove()` _0.0.x_                       | `Unregister(key, name?)`                                                       | Registration methods return the container, for chaining   |\\n| `ioc.Symbol('Db')`, `Symbol.for('Db')`                               | `export const $Db = IoCToken<Db, 'Db'>('Db')`                                  | The same key, now typed                                   |\\n| String keys (`Resolve('Db')`)                                        | A token                                                                        | Throws `IOC_INVALID_KEY`                                  |\\n| `Resolve<Db>(sym)`, `TryResolve<T>`, `ResolveAll<T>`                 | `Resolve($Db)`: the type comes from the key                                    | An explicit type argument no longer compiles              |\\n| Registering a key and name again (last one wins)                     | `{ Replace: true }` on the replacement, or `{ Default: true }` on the default  | Otherwise throws `IOC_DUPLICATE_REGISTRATION`             |\\n| `{ Lazy: true }`, `LazyByDefault: true`                              | Remove them                                                                    | Everything is built on first resolve                      |\\n| `{ Lazy: false }`, eager singletons (the 0.0.x default)              | `await ioc.Activate()` at startup                                              | Builds every singleton, reports every failure             |\\n| `new IoCContainer({ Strict: true })`, `IoCContainer.Create()`        | `new IoCContainer()`                                                           | Always strict                                             |\\n| `PendingTimeoutMs` unset (wait forever)                              | 30 000 ms by default; `PendingTimeoutMs: 0` to wait forever                    | Also bounds `OnStart`, `OnStop` and disposers             |\\n| `AsyncContext: …` _0.1_                                              | Remove it; resolve through the factory's `ioc`                                 | [Cycles](#cycles)                                         |\\n| `Diagnostics: (d) => …` _0.1_                                        | Remove it                                                                      |                                                           |\\n| `await ioc.Start()` building every singleton _0.1_                   | `await ioc.Start(); await ioc.Activate();`                                     | `Start()` validates and starts modules; it builds nothing |\\n| `IoCKeyCollisionError`, `IOC_KEY_COLLISION` _0.1_                    | Remove it                                                                      | Tokens are names; a name is one key by design             |\\n| `Describe()` levels, observed deps, build state _0.1_                | `Describe()` lists registrations and modules only                              |                                                           |\\n| `source.CopyTo(target)`                                              | A module: `target.Use(SourceModule)`; or a child scope: `source.CreateScope()` | [Modules instead of CopyTo](#modules-instead-of-copyto)   |\\n| `ModuleFromContainer('Plugin', pluginIoc, { Defaults: true })` _0.1_ | The plugin exports an `IoCModule` whose registrations use `Default: true`      |                                                           |\\n| `RegisterDirect` / `ResolveDirect`                                   | `RegisterValue` / `Resolve`                                                    |                                                           |\\n| `ioc.services`, `ioc.symbols`                                        | `ioc.Describe()`, `ioc.Names(key)`, `ioc.Has(key)`                             |                                                           |\\n| `CreateScope({ Level })`, `ScopeLevel` _0.1_                         | `CreateScope()`; register per-level services on the scope that owns them       | [Scopes](#scopes)                                         |\\n| `Decorate(key, (inner) => …)` _0.1_                                  | Register the inner service under a name and wrap it in a factory               | [Decorate, IoCLazy, IoCAll](#decorate-ioclazy-iocall)     |\\n| `IoCLazy`/`IoCAll` in `ResolveRecord` _0.1_                          | Resolve those entries separately, or with a factory                            | [Decorate, IoCLazy, IoCAll](#decorate-ioclazy-iocall)     |\\n| `IoCLazy($X)` in `Deps` _0.1_                                        | A factory that keeps `ioc` and calls `ioc.Resolve($X)` later                   | [Decorate, IoCLazy, IoCAll](#decorate-ioclazy-iocall)     |\\n| `IoCAll($X)` in `Deps` _0.1_                                         | A factory that calls `await ioc.ResolveAll($X)`                                | [Decorate, IoCLazy, IoCAll](#decorate-ioclazy-iocall)     |\\n| `err.Symbol` on `IoCServiceNotFoundError`                            | `err.Key` (the token name or class name)                                       |                                                           |\\n| Matching messages (`No Service for symbol '…'`)                      | `isIoCError(err, 'IOC_SERVICE_NOT_FOUND')`                                     | Match on codes, not messages                              |\\n\\nA typical composition root, after the change:\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\ninterface Db {\\n  url: string;\\n}\\n\\nexport const $Db = IoCToken<Db, 'Db'>('Db'); // was: ioc.Symbol('Db')\\n\\nclass Clock {\\n  public now = () => Date.now();\\n}\\n\\nclass Notes {\\n  constructor(public db: Db, public clock: Clock) {}\\n}\\n\\nconst ioc = new IoCContainer() // was: IoCContainer.Create() or { Strict: true }\\n  .RegisterClass(Clock) // was: ioc.Register(Clock)\\n  .RegisterFactory($Db, () => ({ url: 'kv://local' })) // was: ioc.Register($Db, …)\\n  .RegisterClass(Notes, { Deps: [$Db, Clock] });\\n\\nioc.Validate(); // the wiring is sound\\nawait ioc.Activate(); // build every singleton now (0.0.x did this by default)\\n\\nconsole.log((await ioc.Resolve(Notes)).db.url); // kv://local\\n\\nawait ioc.Dispose();\\n```\"},{\"Path\":\"docs/migration/from-0.x.md\",\"Title\":\"Migrating from 0.x to 1.0 › Behavior changes › Registering twice throws\",\"Text\":\"**0.x:** a second registration of the same key and name replaced the first, silently.\\n\\n**1.0:** it throws `IoCDuplicateRegistrationError` unless it says `Replace: true`, or the first\\nwas registered with `Default: true`. Frameworks register their replaceable services with\\n`Default: true`, and the application registers its own without any flag, before or after. The\\nexact rules are under [defaults](../reference/api.md#defaults).\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Greeting = IoCToken<string, 'Greeting'>('Greeting');\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Greeting, 'hello from the framework', { Default: true })\\n  .RegisterValue($Greeting, 'hello from the app'); // the default yields\\n\\nconsole.log(await ioc.Resolve($Greeting)); // hello from the app\\n```\"},{\"Path\":\"docs/migration/from-0.x.md\",\"Title\":\"Migrating from 0.x to 1.0 › Behavior changes › Built on first resolve\",\"Text\":\"**0.0.x** built singletons when they were registered. **1.0** builds a service the first time it\\nis resolved. Call `await ioc.Activate()` at startup to build every singleton now, so a broken\\nservice fails the boot instead of the first request; it throws one `IoCActivationError` naming\\nevery service that failed. `Start()` validates and starts modules, but builds nothing.\"},{\"Path\":\"docs/migration/from-0.x.md\",\"Title\":\"Migrating from 0.x to 1.0 › Behavior changes › Timeouts\",\"Text\":\"A `Resolve`, a module's `OnStart`/`OnStop`, or a disposer still pending after 30 seconds fails\\nwith `IoCResolveTimeoutError` instead of hanging. Raise it with\\n`new IoCContainer({ PendingTimeoutMs: 60_000 })`, or turn it off with `0`.\"},{\"Path\":\"docs/migration/from-0.x.md\",\"Title\":\"Migrating from 0.x to 1.0 › Behavior changes › Class keys are the class\",\"Text\":\"**0.x** keyed a class by its name, so two different classes named `Config` could resolve each\\nother's registrations. **1.0** keys a class by the class itself. Tokens are still names.\"},{\"Path\":\"docs/migration/from-0.x.md\",\"Title\":\"Migrating from 0.x to 1.0 › Behavior changes › Cycles\",\"Text\":\"A factory should resolve through the `ioc` it receives: then a cycle throws\\n`IoCCircularDependencyError` at once, naming the path. A cycle through a container captured in a\\nclosure, after an `await`, can't be seen; it fails at the pending timeout instead.\"},{\"Path\":\"docs/migration/from-0.x.md\",\"Title\":\"Migrating from 0.x to 1.0 › Behavior changes › Modules instead of CopyTo\",\"Text\":\"`CopyTo` copied one container's registrations into another. In 1.0 a package exports a module,\\nand the host adds it with `Use()`. A module lists the modules it builds on in `Requires`; they are\\nadded first, once. `Start()` runs each module's `OnStart` in that order; if one fails, the\\nstarted modules are stopped again and `Start()` can be retried. `Dispose()` runs `OnStop` in\\nreverse.\\n\\n```ts\\nimport { IoCContainer, type IoCModule, IoCToken } from '@fathym/ioc';\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\n\\n// Was: a plugin container, copied into the host with CopyTo.\\nexport const PluginModule: IoCModule = {\\n  Name: 'Plugin',\\n  Register: (ioc) => ioc.RegisterValue($Url, 'kv://plugin', { Default: true }),\\n  OnStart: () => console.log('plugin started'),\\n};\\n\\nawait using host = new IoCContainer().Use(PluginModule);\\n\\nawait host.Start(); // plugin started\\n\\nconsole.log(await host.Resolve($Url)); // kv://plugin\\n```\"},{\"Path\":\"docs/migration/from-0.x.md\",\"Title\":\"Migrating from 0.x to 1.0 › Behavior changes › Scopes\",\"Text\":\"`CreateScope()` makes a child container: `scoped` services get one instance per scope, and\\nregistrations made on the scope override the parent's for that scope. Nested scopes work, but\\nthere are no named levels: register a service on the scope that should own it (a tenant scope, a\\nrequest scope inside it). Disposing a container now disposes its live scopes too, and every\\ninstance it built, in reverse order.\"},{\"Path\":\"docs/migration/from-0.x.md\",\"Title\":\"Migrating from 0.x to 1.0 › Behavior changes › Decorate, IoCLazy, IoCAll\",\"Text\":\"0.1 had three dependency helpers that 1.0 leaves out. Each has a short replacement:\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\ninterface Mailer {\\n  send(to: string): string;\\n}\\n\\nconst $Mailer = IoCToken<Mailer, 'Mailer'>('Mailer');\\nconst $Handler = IoCToken<(path: string) => string, 'Handler'>('Handler');\\n\\nclass Signup {\\n  constructor(private mailer: () => Promise<Mailer>) {}\\n\\n  async welcome(to: string) {\\n    return (await this.mailer()).send(to);\\n  }\\n}\\n\\nclass Router {\\n  constructor(public handlers: ((path: string) => string)[]) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  // Decorate: register the inner service under a name, and wrap it as the default.\\n  .RegisterValue($Mailer, { send: (to) => `sent to ${to}` }, { Name: 'inner' })\\n  .RegisterFactory($Mailer, async (c) => {\\n    const inner = await c.Resolve($Mailer, 'inner');\\n\\n    return { send: (to) => inner.send(to).toUpperCase() };\\n  })\\n  // IoCLazy: keep the factory's ioc and resolve later.\\n  .RegisterFactory(Signup, (c) => new Signup(() => c.Resolve($Mailer)))\\n  // IoCAll: resolve every named registration in the factory.\\n  .RegisterValue($Handler, (p) => `api:${p}`, { Name: 'api' })\\n  .RegisterFactory(Router, async (c) => new Router(await c.ResolveAll($Handler)));\\n\\nconsole.log(await (await ioc.Resolve(Signup)).welcome('ada')); // SENT TO ADA\\nconsole.log((await ioc.Resolve(Router)).handlers.length); // 1\\n```\\n\\n`Validate()` doesn't see what a factory resolves in its body, only declared `Deps`.\"},{\"Path\":\"docs/migration/from-0.x.md\",\"Title\":\"Migrating from 0.x to 1.0 › Checklist for a dependent repository\",\"Text\":\"1. **Find what changes.** Search for `Register(`, `.Symbol(`, `CopyTo`, `ModuleFromContainer`,\\n   `RegisterDirect`, `ResolveDirect`, `.services`, `.symbols`, `Strict`, `IoCContainer.Create`,\\n   `Lazy`, `Diagnostics`, `AsyncContext`, `Level:`, `ScopeLevel`, `Decorate`, `IoCLazy`,\\n   `IoCAll`, `Resolve<` and `.Symbol` on errors.\\n2. **Type the keys.** Replace `ioc.Symbol('X')` and bare `Symbol.for('X')` with\\n   `IoCToken<T, 'X'>('X')`, exported from the package that owns the service. The name stays the\\n   same, so code you haven't migrated yet keeps finding it.\\n3. **Bump the dependency** to `jsr:@fathym/ioc@^1.0.0` (Node.js and Bun: `npx jsr add @fathym/ioc@^1.0.0`) in every\\n   package that shares a container, in the same release.\\n4. **Replace the calls** using [the table](#old-call--new-call), then run `deno check` and fix\\n   what it reports: explicit `Resolve<T>` arguments, string keys, `Deps` order.\\n5. **Make intended replacements explicit** with `Replace: true`, and framework defaults with\\n   `Default: true`.\\n6. **Move `CopyTo` and plugin containers to modules**, and `OnInit`/`OnDestroy` hooks to\\n   `OnStart`/`OnStop`.\\n7. **Start and stop through the container.** Call `await ioc.Start()` at boot (and\\n   `await ioc.Activate()` if you want every singleton built then), and `await ioc.Dispose()` (or\\n   `await using`) at shutdown, including on signals. Check that the 30-second pending timeout\\n   fits your slowest step.\\n8. **Add a wiring test** that calls `Validate()` on the real container.\\n9. **Match errors by code** with `isIoCError(err, code)` instead of their messages.\\n10. **Run the test suite** on every runtime you ship to (Node.js 20 or later, Bun, Deno), then\\n    release with a major version bump and a changelog entry that points your users here.\"},{\"Path\":\"docs/migration/from-0.x.md\",\"Title\":\"Migrating from 0.x to 1.0 › What's Next\",\"Text\":\"- Every method and option: [API reference](../reference/api.md) _[Reference]_\\n- Every error message, explained: [error catalog](../reference/errors.md) _[Reference]_\\n- What each Fathym repository changes:\\n  [dependent follow-ups](../design/dependent-follow-ups.md) _[Explanation]_\\n- Why 1.0 looks the way it does: [IoC 1.0 design](../design/ioc-1.0.md) _[Explanation]_\"},{\"Path\":\"docs/policy.md\",\"Title\":\"Versioning and Support Policy\",\"Text\":\"This page is the contract between `@fathym/ioc` and the code that depends on it, from 1.0.0 on.\\nRead it to know which upgrades are safe to take without reading the changelog, and how much\\nwarning you get before something goes away.\"},{\"Path\":\"docs/policy.md\",\"Title\":\"Versioning and Support Policy › Semantic versioning\",\"Text\":\"Releases follow [Semantic Versioning 2.0.0](https://semver.org/):\\n\\n| Release             | May contain                                                                                 |\\n| ------------------- | ------------------------------------------------------------------------------------------- |\\n| **Patch** (`1.0.x`) | Bug fixes and documentation. No new API.                                                    |\\n| **Minor** (`1.x.0`) | New API, new options, new error codes and validation kinds, deprecations. Nothing breaks.   |\\n| **Major** (`x.0.0`) | Breaking changes, each listed in the changelog with a migration guide in `docs/migration/`. |\"},{\"Path\":\"docs/policy.md\",\"Title\":\"Versioning and Support Policy › Semantic versioning › What counts as breaking\",\"Text\":\"The public API is everything exported from `@fathym/ioc` (`mod.ts`) and documented in the\\n[API reference](./reference/api.md). A change is **breaking**, and only ships in a major release,\\nwhen it:\\n\\n- **removes or renames an export,** a public method, an option, or a public property of an error\\n  or a description (`Describe()`);\\n- **changes a public type or signature** so that code which compiled and ran correctly before no\\n  longer does, on the [supported TypeScript versions](#supported-runtimes);\\n- **removes an error code, renames one, or changes what it means,** or makes a condition throw a\\n  different code than before;\\n- **changes documented behavior:** lifetimes and ownership, resolution order, start and stop\\n  order, disposal order, the duplicate and default rules, what `Validate()` reports, and the\\n  default value of any option (such as `PendingTimeoutMs`);\\n- **drops a supported runtime,** except as described under\\n  [supported runtimes](#dropping-a-runtime-version).\"},{\"Path\":\"docs/policy.md\",\"Title\":\"Versioning and Support Policy › Semantic versioning › What doesn't count\",\"Text\":\"These can change in any release:\\n\\n- **Error message text.** Messages are written for people and may gain detail or be reworded.\\n  Match on `code` (`isIoCError(err, code)`), never on the message.\\n- **New members of open sets:** a new `IoCErrorCode` or `IoCValidationIssue` `Kind` arrives in a\\n  minor release. Code that switches over them should keep a default branch.\\n- **New optional fields** on options, issues and descriptions.\\n- **Fixes to undocumented behavior,** including type changes that only reject code that would\\n  already have failed at runtime. Each is listed in the changelog under _Fixed_.\\n- **Internals:** members marked `@ignore` or `protected`, the `'@fathym/ioc/…'` marker properties\\n  on types, the order of entries the docs don't promise, and performance.\\n- **Development tooling:** scripts, tests, CI and the docs themselves.\\n\\nWhen a bug fix has to change documented behavior because the documented behavior is unsafe (for\\nexample, a security issue), it ships in a minor release with a changelog entry under _Changed_\\nthat says so plainly.\"},{\"Path\":\"docs/policy.md\",\"Title\":\"Versioning and Support Policy › Deprecation\",\"Text\":\"Nothing is removed without warning. A deprecated API:\\n\\n1. **gets a JSDoc `@deprecated` tag** that names its replacement, so editors and `deno doc` show\\n   it;\\n2. **gets a changelog entry** under _Deprecated_ in the release that deprecates it, and a section\\n   in the next major release's migration guide;\\n3. **keeps working** for **at least one minor release and at least six months**, whichever is\\n   longer;\\n4. **is removed only in a major release.**\\n\\nA deprecated behavior that can't carry a JSDoc tag (an option value, an implicit default) is\\nannounced the same way.\"},{\"Path\":\"docs/policy.md\",\"Title\":\"Versioning and Support Policy › Supported runtimes\",\"Text\":\"| Runtime    | Supported versions | Checked in CI                                   |\\n| ---------- | ------------------ | ----------------------------------------------- |\\n| Deno       | 2.x                | Full test suite, docs examples                  |\\n| Node.js    | 20, 22, 24         | Smoke test against the npm build                |\\n| Bun        | 1.x                | Smoke test against the npm build and the source |\\n| TypeScript | 5.4 and later      | A consumer type-checked with TypeScript 5.4     |\\n\\nThe package has no runtime dependencies. The core (`@fathym/ioc`) imports no Node.js modules; the\\nagent kit (`@fathym/ioc/agents`) writes files with `node:fs` and `node:path`, which Deno, Node.js\\nand Bun all provide. It needs ES2022 and\\n`Symbol.asyncDispose` (provided by Deno, Bun and Node.js 20+, or by the TypeScript `esnext.disposable`\\nlibrary for typing). Other ES2022 runtimes, browsers included, may work but aren't tested.\"},{\"Path\":\"docs/policy.md\",\"Title\":\"Versioning and Support Policy › Supported runtimes › Dropping a runtime version\",\"Text\":\"**Dropping a runtime version after its upstream end of life is a minor release, announced at\\nleast one minor release ahead** under _Deprecated_ in the changelog. So is raising the minimum\\nTypeScript version to one released at least a year earlier. **Dropping a whole runtime, or a\\nversion that its maintainers still support, is a major release.**\\n\\n**Why a minor, with notice:** runtime versions end on a schedule everyone can see (Node.js 20,\\nfor example, reached its end of life in April 2026), and a project on an end-of-life runtime\\nalready gets no security fixes from its runtime. Requiring a major release for each of those\\nwould force a new major version roughly every year, and every major release asks every dependent\\nto read a migration guide. A minor release with advance notice keeps majors for real API changes,\\nwhile a project pinned to `^1` still gets a full release cycle of warning, and can stay on the\\nlast minor that supports its runtime.\"},{\"Path\":\"docs/policy.md\",\"Title\":\"Versioning and Support Policy › Releases\",\"Text\":\"1. **Changelog first.** Every change that affects users lands with an entry under _Unreleased_ in\\n   the [changelog](../CHANGELOG.md). Before a release, those entries move under the new version.\\n   A release without changelog entries isn't made.\\n2. **The version comes from the commit.** The release commit's message carries `(MAJOR)` or\\n   `(MINOR)`; any other commit to `main` is a patch.\\n3. **Checks before publishing:** `deno task build` (format, lint, type check, docs check),\\n   `deno task test`, `deno task test:runtimes --require-all`, and the test suites of the main\\n   dependents against the release candidate.\\n4. **JSR and npm from CI.** The `fathym/build-n-publish` workflow publishes to\\n   [JSR](https://jsr.io/@fathym/ioc) and tags the release. For each stable release from `main`,\\n   the `Publish to npm` workflow then publishes the same version to\\n   [npm](https://www.npmjs.com/package/@fathym/ioc), built by `deno task build:npm` and smoke-tested\\n   on Node.js first, with provenance. Prereleases stay on JSR only.\\n5. **Provenance** (sources, release channels, version pins) is recorded in `UPSTREAM.md`.\\n\\nThe step-by-step checklist is in [CONTRIBUTING](../CONTRIBUTING.md#releasing).\"},{\"Path\":\"docs/policy.md\",\"Title\":\"Versioning and Support Policy › Security fixes\",\"Text\":\"- **Report privately,** as described in the [security policy](../SECURITY.md). Don't open a\\n  public issue.\\n- **Fixes ship as a patch release** of the latest minor version, as soon as a fix is ready, with\\n  a changelog entry and a GitHub security advisory.\\n- **After a new major release,** the last minor release of the previous major receives security\\n  fixes for at least six months.\\n- **0.x releases receive no fixes.** Upgrade with the [migration guide](./migration/from-0.x.md).\"},{\"Path\":\"docs/policy.md\",\"Title\":\"Versioning and Support Policy › What's Next\",\"Text\":\"- What changed in each release: [CHANGELOG](../CHANGELOG.md) _[Reference]_\\n- Upgrading from 0.x: [from-0.x.md](./migration/from-0.x.md) _[How-to]_\\n- Every public method, option and type: [api.md](./reference/api.md) _[Reference]_\"},{\"Path\":\"docs/reference/README.md\",\"Title\":\"Reference\",\"Text\":\"Look things up here. To learn the container step by step, start with\\n[getting started](../getting-started/README.md).\\n\\n| Document                                       | Contents                                                                                                           |\\n| ---------------------------------------------- | ------------------------------------------------------------------------------------------------------------------ |\\n| [api.md](./api.md) _[Reference]_               | Every public method, option, type and error class, with an example each                                            |\\n| [errors.md](./errors.md) _[Reference]_         | Every error message the container can produce: what each part means, the likely causes, and the fix                |\\n| [guarantees.md](./guarantees.md) _[Reference]_ | What the container promises about building, disposal, startup, timeouts and `Validate()`, each linked to its tests |\\n| [comparison.md](./comparison.md) _[Reference]_ | The same scenarios and benchmarks run against InversifyJS, awilix and tsyringe, generated by `deno task compare`   |\\n\\nThe generated API documentation on [JSR](https://jsr.io/@fathym/ioc/doc) is built from the same\\nJSDoc as the source and always matches a release. What counts as a breaking change, and which\\nruntimes are supported, is in the [versioning and support policy](../policy.md).\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference\",\"Text\":\"Everything is exported from `@fathym/ioc`. The generated docs on\\n[JSR](https://jsr.io/@fathym/ioc/doc) come from the same JSDoc and always match a release. This\\npage groups the API by task and adds behavior notes and examples.\\n\\nSignature blocks are declarations, shown for reading (they are marked `ts ignore`). Every other\\ncode block is a complete, runnable example, checked in CI.\\n\\n**Contents:**\\n\\n- **Creating:** [new IoCContainer](#new-ioccontaineroptions), [State](#state)\\n- **Registration:** [keys and IoCToken](#keys-and-ioctokenname),\\n  [RegisterClass](#registerclassclass-options),\\n  [RegisterFactory](#registerfactorykey-factory-options),\\n  [RegisterValue](#registervaluekey-value-options), [options](#registration-options),\\n  [Unregister](#unregisterkey-name)\\n- **Typed containers:** [Typed](#typed), [Expect](#expectkeys)\\n- **Resolution:** [Resolve](#resolvekey-name), [TryResolve](#tryresolvekey-name),\\n  [ResolveAll](#resolveallkey), [ResolveNamed](#resolvenamedkey),\\n  [ResolveRecord](#resolverecordrecord), [Names](#nameskey), [Has](#haskey-name),\\n  [how resolution behaves](#how-resolution-behaves)\\n- **Scopes:** [CreateScope](#createscope), [Isolate](#isolatekeys)\\n- **Modules:** [Use](#usemodules), [IoCModule](#iocmodule),\\n  [DefineModule](#definemoduledefinition)\\n- **Lifecycle:** [Start](#startoptions), [Activate](#activate), [Dispose](#dispose),\\n  [what gets disposed](#what-gets-disposed)\\n- **Inspection:** [Validate](#validateoptions), [Describe](#describe)\\n- **Testing:** [Override](#overridekey-value-options)\\n- **Types:** [keys and dependencies](#key-and-dependency-types),\\n  [registry types](#registry-types), [module types](#module-types),\\n  [other types](#other-types)\\n- **Errors:** [isIoCError and the error classes](#errors)\\n\\n---\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Creating a container › new IoCContainer(options?)\",\"Text\":\"```ts ignore\\nnew IoCContainer(options?: IoCContainerOptions)\\n```\\n\\nCreates a root container. With no options it is already strict (registering a key and name twice\\nthrows), lazy (nothing is built until it is resolved or [`Activate()`](#activate) runs) and\\nprotected against hangs.\\n\\n`IoCContainerOptions` has one option, **`PendingTimeoutMs`** (default `30000`): a `Resolve`, a\\nmodule's `OnStart`/`OnStop`, or an instance's disposer still pending after this many milliseconds\\nfails with [`IoCResolveTimeoutError`](./errors.md#-did-not-finish-within-ms). `0` turns it off;\\nthe maximum is 2147483647.\\n\\nThe options are frozen when the container is created. Scopes inherit them.\\n\\n**Throws:** [`IoCRegistrationError`](./errors.md#pendingtimeoutms-must-be-a-number-of-milliseconds-from-0-off-to-2147483647-about-248-days)\\nwhen `PendingTimeoutMs` is negative, above 2147483647, or not a number.\\n\\n```ts\\nimport { IoCContainer } from '@fathym/ioc';\\n\\nconst ioc = new IoCContainer({ PendingTimeoutMs: 10_000 });\\n\\nconsole.log(ioc.State); // idle\\n```\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Creating a container › State\",\"Text\":\"```ts ignore\\nget State(): IoCContainerState // 'idle' | 'starting' | 'started' | 'stopping' | 'disposed'\\n```\\n\\n| State      | Means                                              |\\n| ---------- | -------------------------------------------------- |\\n| `idle`     | Created, or a `Start()` failed and was rolled back |\\n| `starting` | `Start()` is running                               |\\n| `started`  | `Start()` succeeded                                |\\n| `stopping` | `Dispose()` is running                             |\\n| `disposed` | Done; resolving, registering and starting throw    |\\n\\nA scope has its own state: the parent's `Start()` doesn't start it.\\n\\n```ts\\nimport { IoCContainer } from '@fathym/ioc';\\n\\nconst ioc = new IoCContainer();\\n\\nawait ioc.Start();\\nconsole.log(ioc.State); // started\\n\\nawait ioc.Dispose();\\nconsole.log(ioc.State); // disposed\\n```\\n\\n---\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Registration\",\"Text\":\"Nothing is built at registration. Registering the same key and name twice in one container throws\\n[`IoCDuplicateRegistrationError`](./errors.md#-is-already-registered), unless the new registration\\nsays `Replace: true` or the existing one was registered with `Default: true`. A registration on a\\nscope is not a duplicate of the parent's: it overrides it for that scope.\\n\\nEvery registration method returns the container, so calls chain. On a disposed container\\n`RegisterClass`, `RegisterFactory`, `RegisterValue` and `Override` throw\\n[`IoCContainerDisposedError`](./errors.md#the-ioc-container-has-been-disposed).\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Registration › Keys and IoCToken(name)\",\"Text\":\"```ts ignore\\nfunction IoCToken<T, const TId extends string = string>(id: TId): IoCToken<T, TId>;\\n```\\n\\nA key is either a token or a class.\\n\\n- **A token is its name.** `IoCToken<Db>('Db')` returns `Symbol.for('Db')`, typed with the service\\n  it resolves. Two packages that call `IoCToken('Db')` share one key, and a plain `Symbol.for('Db')`\\n  from 0.x code is the same key at runtime. Pick names that won't collide across packages\\n  (`'eac/Config'` rather than `'Config'`).\\n- **A unique symbol** works as a private key if you type it as a token:\\n  `Symbol('Secret') as IoCToken<Secret, 'Secret'>`. A bare `Symbol()` or `Symbol.for()` doesn't\\n  compile as a key; it carries no service type.\\n- **A class is keyed by reference.** Two different classes named `Config` are two keys. Abstract\\n  classes work as typed \\\"interface\\\" keys for `RegisterFactory`.\\n- **Anything else is rejected:** strings, plain objects, arrow functions and other non-class\\n  functions used as keys throw\\n  [`IoCRegistrationError` with `IOC_INVALID_KEY`](./errors.md#keys-must-be-tokens-or-classes-but-a--was-given).\\n  (`RegisterClass` given a non-class throws `IOC_INVALID_REGISTRATION` instead.)\\n\\nThe optional second type argument keeps the name in the token's type. A\\n[typed container](#typed) needs it to tell apart two tokens of the same service type, such as two\\n`string` settings.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $DbUrl = IoCToken<string, 'eac/DbUrl'>('eac/DbUrl');\\n\\nconsole.log($DbUrl === Symbol.for('eac/DbUrl')); // true\\n\\nconst ioc = new IoCContainer().RegisterValue($DbUrl, 'kv://local');\\n\\nconsole.log(await ioc.Resolve($DbUrl)); // kv://local\\n```\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Registration › RegisterClass(class, options?)\",\"Text\":\"```ts ignore\\nRegisterClass<C, TName = '$default', TType = never>(\\n  clazz: C,\\n  options?: IoCRegisterClassOptions<C, TKeys, TName, TType>,\\n): IoCContainer<TKeys | IoCRegistered<C or TType, TName>>\\n```\\n\\nRegisters a class the container constructs with `new clazz(...deps)`. The key is the class itself,\\nor the token given as `Type`.\\n\\n- **`Deps`** lists the services passed to the constructor, in parameter order. Each entry is a key\\n  or `[key, name]`. It is type-checked against the constructor's parameters, and on a\\n  [typed container](#typed) against the keys registered so far. The dependencies are resolved by\\n  the container that builds the instance: for a singleton, the container it is registered in; for\\n  `scoped` and `transient` services, the scope that resolves it. To make a singleton see a scope's\\n  overrides, [`Isolate`](#isolatekeys) it in that scope.\\n- **Without `Deps`** the class is constructed with no arguments. [`Validate()`](#validateoptions)\\n  reports a class whose constructor declares parameters.\\n- **`Type`** registers the class under a token instead (`{ Type: $Db }`). The class's instances\\n  must satisfy the token's type, or the call doesn't compile.\\n\\n**Throws:** [`RegisterClass expects a class`](./errors.md#registerclass-expects-a-class) for\\nanything that isn't a class.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\ninterface Db {\\n  url: string;\\n}\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\nconst $Db = IoCToken<Db, 'Db'>('Db');\\n\\nclass KvDb implements Db {\\n  constructor(public url: string) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Url, 'kv://local')\\n  .RegisterClass(KvDb, { Deps: [$Url], Type: $Db });\\n\\nconsole.log((await ioc.Resolve($Db)).url); // kv://local\\n```\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Registration › RegisterFactory(key, factory, options?)\",\"Text\":\"```ts ignore\\nRegisterFactory<K, TName = '$default', TDeps = []>(\\n  key: K,\\n  factory: (ioc: IoCContainer, ...deps: IoCDependencyValues<TDeps>) =>\\n    IoCServiceOf<K> | Promise<IoCServiceOf<K>>,\\n  options?: IoCRegisterOptions<TName, IoCServiceOf<K>> & { Deps?: TDeps },\\n): IoCContainer<TKeys | IoCRegistered<K, TName>>\\n```\\n\\nRegisters a function that builds the service, under a token or a class (abstract classes\\nincluded). The return type is checked against the key, and the function may be async.\\n\\n- **The first parameter is the container that builds the service** (the registering container\\n  for a singleton, the resolving scope for scoped and transient services). Resolve through it, not\\n  through a container captured in a closure: then a cycle throws\\n  [`IoCCircularDependencyError`](./errors.md#circular-dependency-detected-) at once, and a scope\\n  gets its own scoped services.\\n- **`Deps`** lists services to resolve and pass after the container, each parameter typed from its\\n  key. `Validate()` checks them; what the factory resolves in its body can't be checked before it\\n  runs.\\n\\n**Throws:** [`RegisterFactory expects a factory function.`](./errors.md#registerfactory-expects-a-factory-function)\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Host = IoCToken<string, 'Host'>('Host');\\nconst $Endpoint = IoCToken<string, 'Endpoint'>('Endpoint');\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Host, 'localhost')\\n  .RegisterFactory($Endpoint, (_ioc, host) => `${host}:8080`, { Deps: [$Host] });\\n\\nconsole.log(await ioc.Resolve($Endpoint)); // localhost:8080\\n```\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Registration › RegisterValue(key, value, options?)\",\"Text\":\"```ts ignore\\nRegisterValue<K, TName = '$default'>(\\n  key: K,\\n  value: IoCServiceOf<K>,\\n  options?: { Name?: TName; Dispose?: (value) => unknown; Default?: boolean; Replace?: boolean },\\n): IoCContainer<TKeys | IoCRegistered<K, TName>>\\n```\\n\\nRegisters an existing value, shared as it is by every scope.\\n\\n- **Functions are stored, never called.**\\n- **A promise (or thenable) is stored as it is,** but `Resolve` awaits it, so you get its result.\\n- **The container never disposes a value** unless you pass `Dispose`, which tells it how. The\\n  value belongs to the code that created it.\\n- **A value has no lifetime option;** it acts as a singleton and can't be [isolated](#isolatekeys).\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Handler = IoCToken<(path: string) => string, 'Handler'>('Handler');\\n\\nconst ioc = new IoCContainer().RegisterValue($Handler, (path) => `handled ${path}`);\\n\\nconsole.log((await ioc.Resolve($Handler))('/notes')); // handled /notes\\n```\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Registration › Registration options\",\"Text\":\"| Option     | On                                 | Default      | Meaning                                                                                                                                                                                                    |\\n| ---------- | ---------------------------------- | ------------ | ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |\\n| `Lifetime` | `RegisterClass`, `RegisterFactory` | singleton    | `'singleton'` (or omitted): one shared instance. `'transient'`: a new instance per resolve. `'scoped'`: one instance per [scope](#createscope); resolving it from the root throws `IoCScopeRequiredError`. |\\n| `Name`     | all three                          | `'$default'` | Registers under a name, so several services share one key. Named and unnamed registrations never stand in for each other.                                                                                  |\\n| `Default`  | all three                          | `false`      | A replaceable default; see [defaults](#defaults) below.                                                                                                                                                    |\\n| `Replace`  | all three                          | `false`      | Replaces an existing registration in this container on purpose. Without it, registering a key and name again throws.                                                                                       |\\n| `Dispose`  | all three                          | none         | `(instance) => …`: cleanup run when the owning container is disposed, for resources without `Symbol.asyncDispose` / `Symbol.dispose` (`(kv) => kv.close()`).                                               |\\n| `Deps`     | `RegisterClass`, `RegisterFactory` | none         | The services to inject, in order: keys or `[key, name]`.                                                                                                                                                   |\\n| `Type`     | `RegisterClass`                    | the class    | The token to register the class under; the class must satisfy its type.                                                                                                                                    |\\n\\n#### Defaults\\n\\nFrameworks and modules register what an application may replace with `Default: true`:\\n\\n- If a non-default registration of the key and name already exists, here or in a parent, the\\n  `Default` call does nothing. A parent registration made later also wins over a scope's\\n  default.\\n- Any later registration replaces a default without `Replace: true`; a later `Default` replaces an\\n  earlier one.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Greeting = IoCToken<string, 'Greeting'>('Greeting');\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Greeting, 'hello', { Default: true }) // a framework default\\n  .RegisterValue($Greeting, 'hi'); // the application's choice wins, no error\\n\\nconsole.log(await ioc.Resolve($Greeting)); // hi\\n```\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Registration › Unregister(key, name?)\",\"Text\":\"```ts ignore\\nUnregister(key: IoCServiceKey<unknown>, name?: string): boolean\\n```\\n\\nRemoves a registration from this container, not from its parents. Returns `true` when one existed.\\nInstances already built from it are kept, and still disposed with the container.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Flag = IoCToken<boolean, 'Flag'>('Flag');\\n\\nconst ioc = new IoCContainer().RegisterValue($Flag, true);\\n\\nconsole.log(ioc.Unregister($Flag)); // true\\nconsole.log(ioc.Has($Flag)); // false\\n```\\n\\n---\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Typed containers\",\"Text\":\"A typed container tracks, in its type, every key registered so far. `Deps` may then only name keys\\nthat are already registered, so a missing dependency is a compile error rather than a runtime one.\\nRuntime behavior is unchanged.\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Typed containers › Typed()\",\"Text\":\"```ts ignore\\nTyped(): IoCContainer<IoCNoKeys>\\n```\\n\\nReturns the same container, typed with an empty registry. Each registration then adds its key (or\\n`[key, name]` for a named registration) to the type. Give tokens a name type argument\\n(`IoCToken<string, 'Url'>('Url')`) so that tokens of the same service type stay distinct.\\n\\nTypeScript compares classes by shape, so an unregistered class with the same members as a\\nregistered one passes the check; a class with a private field doesn't. `Validate()` catches it.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\n\\nclass Repo {\\n  constructor(public url: string) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  .Typed()\\n  .RegisterValue($Url, 'kv://local')\\n  .RegisterClass(Repo, { Deps: [$Url] }); // Deps: [$Url] before RegisterValue would not compile\\n\\nconsole.log((await ioc.Resolve(Repo)).url); // kv://local\\n```\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Typed containers › Expect(...keys)\",\"Text\":\"```ts ignore\\nExpect<const TDeps extends readonly (IoCDependencyKey<any> | readonly [IoCDependencyKey<any>, string])[]>(\\n  ...deps: TDeps\\n): IoCContainer<TKeys | IoCExpected<TDeps>>\\n```\\n\\nDeclares keys that are registered later or elsewhere (on each request scope, or by the code that\\nhosts the container), so `Deps` may name them now. Nothing is registered. `Validate()` treats\\nexpected keys as registered. Resolving one that was never registered throws\\n`IoCServiceNotFoundError` with a hint that it was expected.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $UserId = IoCToken<string, 'UserId'>('UserId');\\n\\nclass Greeter {\\n  constructor(public userId: string) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  .Typed()\\n  .Expect($UserId) // registered on each request scope\\n  .RegisterClass(Greeter, { Deps: [$UserId], Lifetime: 'scoped' });\\n\\nawait using scope = ioc.CreateScope().RegisterValue($UserId, 'ada');\\n\\nconsole.log((await scope.Resolve(Greeter)).userId); // ada\\n```\\n\\n---\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Resolution\",\"Text\":\"Every resolution method is async. A service is built the first time it is resolved.\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Resolution › Resolve(key, name?)\",\"Text\":\"```ts ignore\\nResolve<K extends IoCServiceKey<unknown>>(key: K, name?: string): Promise<IoCServiceOf<K>>\\n```\\n\\nResolves the nearest registration of the key and name (`$default` when no name is given),\\nsearching this container, then its parents. The result is typed from the key; don't pass a type\\nargument.\\n\\n**Throws:** [`IoCServiceNotFoundError`](./errors.md#no-service-is-registered-for-),\\n[`IoCScopeRequiredError`](./errors.md#scoped-service--was-resolved-outside-a-scope),\\n[`IoCCircularDependencyError`](./errors.md#circular-dependency-detected-),\\n[`IoCResolveTimeoutError`](./errors.md#-did-not-finish-within-ms),\\n[`IoCContainerDisposedError`](./errors.md#the-ioc-container-has-been-disposed), or whatever the\\nfactory or constructor throws.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Db = IoCToken<{ url: string }, 'Db'>('Db');\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Db, { url: 'kv://primary' })\\n  .RegisterValue($Db, { url: 'kv://replica' }, { Name: 'replica' });\\n\\nconsole.log((await ioc.Resolve($Db, 'replica')).url); // kv://replica\\n```\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Resolution › TryResolve(key, name?)\",\"Text\":\"```ts ignore\\nTryResolve<K>(key: K, name?: string): Promise<IoCServiceOf<K> | undefined>\\n```\\n\\nLike `Resolve`, but returns `undefined` when nothing is registered for the key and name. If a\\nregistration exists and building it fails, the error is still thrown.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Cache = IoCToken<Map<string, string>, 'Cache'>('Cache');\\n\\nconst cache = await new IoCContainer().TryResolve($Cache);\\n\\nconsole.log(cache); // undefined\\n```\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Resolution › ResolveAll(key)\",\"Text\":\"```ts ignore\\nResolveAll<K>(key: K): Promise<IoCServiceOf<K>[]>\\n```\\n\\nResolves every registration of a key, one per name, in the order of [`Names`](#nameskey): this\\ncontainer's names first, then names only a parent has. Returns `[]` when there are none.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Plugin = IoCToken<string, 'Plugin'>('Plugin');\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Plugin, 'auth', { Name: 'auth' })\\n  .RegisterValue($Plugin, 'metrics', { Name: 'metrics' });\\n\\nconsole.log(await ioc.ResolveAll($Plugin)); // [ \\\"auth\\\", \\\"metrics\\\" ]\\n```\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Resolution › ResolveNamed(key)\",\"Text\":\"```ts ignore\\nResolveNamed<K>(key: K): Promise<Map<string, IoCServiceOf<K>>>\\n```\\n\\nLike `ResolveAll`, but returns a `Map` from name to service.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Plugin = IoCToken<string, 'Plugin'>('Plugin');\\n\\nconst ioc = new IoCContainer().RegisterValue($Plugin, 'auth', { Name: 'auth' });\\n\\nconsole.log((await ioc.ResolveNamed($Plugin)).get('auth')); // auth\\n```\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Resolution › ResolveRecord(record)\",\"Text\":\"```ts ignore\\nResolveRecord<const R extends Record<string, IoCDependency<any>>>(\\n  record: R,\\n): Promise<{ -readonly [K in keyof R]: IoCDependencyValue<R[K]> }>\\n```\\n\\nResolves several services at once into an object with the same keys. Each value is a key or\\n`[key, name]`, and each property is typed from it.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\nconst $Port = IoCToken<number, 'Port'>('Port');\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Url, 'localhost')\\n  .RegisterValue($Port, 8080, { Name: 'http' });\\n\\nconst { url, port } = await ioc.ResolveRecord({ url: $Url, port: [$Port, 'http'] });\\n\\nconsole.log(`${url}:${port}`); // localhost:8080\\n```\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Resolution › Names(key)\",\"Text\":\"```ts ignore\\nNames(key: IoCServiceKey<unknown>): string[]\\n```\\n\\nThe names registered for a key, here and in parents, nearest first, each listed once. The unnamed\\nregistration is listed as `$default`. Synchronous.\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Resolution › Has(key, name?)\",\"Text\":\"```ts ignore\\nHas(key: IoCServiceKey<unknown>, name?: string): boolean\\n```\\n\\n`true` when a registration of the key and name exists here or in a parent. Synchronous; it builds\\nnothing.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Db = IoCToken<string, 'Db'>('Db');\\n\\nconst ioc = new IoCContainer().RegisterValue($Db, 'kv', { Name: 'replica' });\\n\\nconsole.log(ioc.Names($Db)); // [ \\\"replica\\\" ]\\nconsole.log(ioc.Has($Db), ioc.Has($Db, 'replica')); // false true\\n```\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Resolution › How resolution behaves\",\"Text\":\"- **One build per singleton.** Concurrent resolves of a singleton that is still building share\\n  one build. If the build fails, nothing is cached: the next resolve tries again.\\n- **Cycles.** When services resolve each other through the `ioc` their factory receives (or\\n  through `Deps`), a cycle throws `IoCCircularDependencyError` at once, naming the path. Through a\\n  container captured in a closure, after an `await`, the container can't see the cycle: the\\n  resolve fails at `PendingTimeoutMs` with `IoCResolveTimeoutError` instead.\\n- **Timeouts.** A resolve still pending after `PendingTimeoutMs` (30 seconds by default) fails with\\n  `IoCResolveTimeoutError`. The build itself is not cancelled. When the stuck dependency is\\n  reached after an `await`, the error names the service you resolved, not the one that hung.\\n- **Async factories.** A factory may return a promise or any thenable; either is awaited once and\\n  shared like any other build.\\n- **Disposal races.** A build that finishes after its container (or a parent) was disposed is\\n  disposed at once, and the `Resolve` waiting for it rejects with `IoCContainerDisposedError`.\\n\\n---\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Scopes › CreateScope()\",\"Text\":\"```ts ignore\\nCreateScope(): IoCContainer<TKeys>\\n```\\n\\nCreates a child container, for one request, command, job or test.\\n\\n- The scope resolves everything its parent can. Singletons stay shared with the parent.\\n- `scoped` registrations get one instance per scope, built in and disposed with that scope.\\n- Registrations made on the scope override the parent's, for this scope only. Services the scope\\n  builds (scoped and transient ones) see those overrides; a parent's singleton doesn't, since the\\n  parent builds it. [`Isolate`](#isolatekeys) gives the scope its own copy of a singleton that\\n  does. A `Default` on a scope yields to a parent's non-default registration.\\n- A scope skips modules its parent already has, and has its own `Start()` and `State`.\\n- Dispose it when done (`await using scope = ioc.CreateScope()`). Disposing the parent disposes its\\n  live scopes too, and a scope can't be used once its parent is disposed.\\n\\n```ts\\nimport { IoCContainer } from '@fathym/ioc';\\n\\nclass RequestId {\\n  public id = crypto.randomUUID();\\n}\\n\\nconst ioc = new IoCContainer().RegisterClass(RequestId, { Lifetime: 'scoped' });\\n\\nawait using a = ioc.CreateScope();\\nawait using b = ioc.CreateScope();\\n\\nconsole.log((await a.Resolve(RequestId)) === (await a.Resolve(RequestId))); // true\\nconsole.log((await a.Resolve(RequestId)) === (await b.Resolve(RequestId))); // false\\n```\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Scopes › Isolate(...keys)\",\"Text\":\"```ts ignore\\nIsolate(...keys: (IoCServiceKey<unknown> | readonly [IoCServiceKey<unknown>, string])[]): this\\n```\\n\\nGives this scope its own copy of registrations it inherits. A singleton among them gets one\\ninstance in this scope, built from this scope's registrations (so it sees the scope's overrides of\\nits dependencies), instead of sharing the parent's. A key the scope already registers itself is\\nleft as it is.\\n\\n**Throws:** [`Isolate() works on scopes`](./errors.md#isolate-works-on-scopes-call-it-on-a-container-created-with-createscope)\\non a root container, [`IoCNotIsolatableError`](./errors.md#-cant-be-isolated-) for a value (every\\nscope shares values as they are), and `IoCServiceNotFoundError` for a key nobody registered.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Tenant = IoCToken<string, 'Tenant'>('Tenant');\\n\\nclass Greeter {\\n  constructor(public tenant: string) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Tenant, 'default')\\n  .RegisterClass(Greeter, { Deps: [$Tenant] });\\n\\nawait using scope = ioc.CreateScope()\\n  .RegisterValue($Tenant, 'acme')\\n  .Isolate(Greeter);\\n\\nconsole.log((await scope.Resolve(Greeter)).tenant); // acme\\nconsole.log((await ioc.Resolve(Greeter)).tenant); // default\\n```\\n\\n---\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Modules\",\"Text\":\"A module is a named unit of registrations with an optional lifecycle: the way a framework, a plugin\\nor a feature contributes services to a host container.\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Modules › Use(...modules)\",\"Text\":\"```ts ignore\\nUse<const TModules extends readonly IoCModule<any, any>[]>(\\n  ...modules: TModules & IoCCheckNeeds<TKeys, TModules>\\n): IoCContainer<TKeys | IoCModulesProvide<TModules>>\\n```\\n\\nAdds modules, each after the modules it `Requires`. Each module's `Register` runs once, at once,\\nwith this container. A module already added here or in a parent is skipped, so shared\\nrequirements are registered once.\\n\\n- **Before `Start()` only.** A new module added to a container that isn't `idle` throws\\n  [`Module '…' was added after Start()`](./errors.md#module--was-added-after-start). Late plugins\\n  go in a scope: `ioc.CreateScope().Use(plugin)`, then `scope.Start()`.\\n- **Not all-or-nothing.** If a module's `Register` throws, the modules registered before it stay.\\n- **One container per module.** A module added to a scope and then to its parent is added (and\\n  started) twice; add shared modules to the parent first.\\n- **On a [typed container](#typed),** `Use()` doesn't compile until every key the modules `Needs`\\n  is registered, and what [typed modules](#definemoduledefinition) register is added to the type.\\n\\n**Throws:** [`IoCModuleCycleError`](./errors.md#module-dependency-cycle-) when modules require each\\nother in a loop, and\\n[`A module needs a Name and a Register(ioc) function.`](./errors.md#a-module-needs-a-name-and-a-registerioc-function)\\n\\n```ts\\nimport { IoCContainer, type IoCModule, IoCToken } from '@fathym/ioc';\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\n\\nconst Config: IoCModule = {\\n  Name: 'Config',\\n  Register: (ioc) => ioc.RegisterValue($Url, 'kv://local', { Default: true }),\\n};\\n\\nconst Data: IoCModule = {\\n  Name: 'Data',\\n  Requires: [Config],\\n  Register: () => {},\\n  OnStart: async (ioc) => console.log(`connecting to ${await ioc.Resolve($Url)}`),\\n};\\n\\nawait using ioc = new IoCContainer().Use(Data); // adds Config, then Data\\n\\nawait ioc.Start(); // connecting to kv://local\\n```\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Modules › IoCModule\",\"Text\":\"```ts ignore\\ninterface IoCModule<TNeeds = never, TProvides = never> {\\n  readonly Name: string;\\n  readonly Requires?: readonly IoCModule<any, any>[];\\n  readonly Needs?: readonly (IoCDependencyKey<any> | readonly [IoCDependencyKey<any>, string])[];\\n  Register(ioc: IoCContainer<any>): unknown;\\n  OnStart?(ioc: IoCContainer<any>): unknown;\\n  OnStop?(ioc: IoCContainer<any>): unknown;\\n}\\n```\\n\\n| Member     | Meaning                                                                                                                                         |\\n| ---------- | ----------------------------------------------------------------------------------------------------------------------------------------------- |\\n| `Name`     | A unique, readable name, used in errors and `Describe()`. Modules are told apart by reference, not by name.                                     |\\n| `Requires` | Modules that must be added (and started) before this one. `Use()` adds them.                                                                    |\\n| `Needs`    | Type-only: keys someone else registers. On a typed container, `Use()` doesn't compile until they are registered. Not checked at runtime.        |\\n| `Register` | Adds the module's registrations. Synchronous: async setup belongs in `OnStart` or in factories. Register what the app may replace as `Default`. |\\n| `OnStart`  | Runs from `Start()`, after the modules it requires have started. May be async.                                                                  |\\n| `OnStop`   | Runs from `Dispose()`, in reverse start order, before any instance is disposed, if the module started. May be async.                            |\\n\\nEach function receives the container itself.\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Modules › DefineModule(definition)\",\"Text\":\"```ts ignore\\nfunction DefineModule<const TRequires, const TNeeds, TResult>(\\n  definition: IoCModuleDefinition<TRequires, TNeeds, TResult>,\\n): IoCModule<needs, provides>;\\n```\\n\\nDefines a typed module. It returns the definition unchanged at runtime; the types do the work:\\n\\n- Inside `Register`, `OnStart` and `OnStop`, the container is typed with the keys the module\\n  `Needs` and the keys its `Requires` register themselves. `Deps` can only name those and the\\n  module's own earlier registrations.\\n- `Register` should return its registration chain: the keys it adds become what the module\\n  provides.\\n- On a typed container, `Use(module)` adds those keys, and only compiles when the container already\\n  has what the module needs (including what its requirements need and don't get from their own\\n  requirements).\\n\\nA module's provided keys don't include those of the modules it requires. To depend on a module\\nfurther down, require it too, or list its keys in `Needs`.\\n\\n```ts\\nimport { DefineModule, IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\n\\nclass Repo {\\n  constructor(public url: string) {}\\n}\\n\\nconst RepoModule = DefineModule({\\n  Name: 'Repo',\\n  Needs: [$Url],\\n  Register: (ioc) => ioc.RegisterClass(Repo, { Deps: [$Url] }),\\n});\\n\\nconst ioc = new IoCContainer()\\n  .Typed()\\n  .RegisterValue($Url, 'kv://local')\\n  .Use(RepoModule); // compiles: $Url is registered; Repo is now in the type\\n\\nconsole.log((await ioc.Resolve(Repo)).url); // kv://local\\n```\\n\\n---\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Lifecycle › Start(options?)\",\"Text\":\"```ts ignore\\nStart(options?: { Validate?: boolean }): Promise<void>\\n```\\n\\n1. Runs [`Validate()`](#validateoptions), unless `{ Validate: false }`. A problem throws\\n   `IoCValidationError` and the state goes back to `idle`.\\n2. Runs each module's `OnStart`, one at a time, in the order the modules were added (requirements\\n   first). Each one is bounded by `PendingTimeoutMs`.\\n3. Sets `State` to `started`.\\n\\nIf an `OnStart` fails, the modules that started are stopped again (their `OnStop`, in reverse),\\nthe state goes back to `idle`, and `Start()` throws\\n[`IoCStartError`](./errors.md#module--failed-to-start-) with the module's `Name`, its error as\\n`cause`, and any `OnStop` errors as `RollbackErrors`. `Start()` can then be called again.\\n\\n- **It doesn't build services.** They are still built when first resolved; call\\n  [`Activate()`](#activate) to build every singleton at boot.\\n- Concurrent calls share one start; calling it on a started container does nothing.\\n- A scope's `Start()` runs the scope's own modules. Its parent must be started first when those\\n  modules require the parent's.\\n- On a disposed container it throws `IoCContainerDisposedError`.\\n\\n```ts\\nimport { IoCContainer, IoCStartError } from '@fathym/ioc';\\n\\nlet attempts = 0;\\n\\nconst ioc = new IoCContainer().Use({\\n  Name: 'Db',\\n  Register: () => {},\\n  OnStart: () => {\\n    if (++attempts === 1) throw new Error('connection refused');\\n  },\\n});\\n\\ntry {\\n  await ioc.Start();\\n} catch (err) {\\n  console.log((err as IoCStartError).message); // Module 'Db' failed to start: connection refused\\n}\\n\\nconsole.log(ioc.State); // idle\\n\\nawait ioc.Start(); // the retry succeeds\\n\\nconsole.log(ioc.State); // started\\n```\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Lifecycle › Activate()\",\"Text\":\"```ts ignore\\nActivate(): Promise<void>\\n```\\n\\nBuilds every singleton registered on this container now (not its parents' singletons, and not\\nscoped or transient services), so a broken service fails at boot rather than on first use. All\\nbuilds run, then one [`IoCActivationError`](./errors.md#ioc-activation-failed-for-) names every\\nservice that failed; its `errors` holds the causes, in the order of `Services`.\\n\\n```ts\\nimport { IoCActivationError, IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Db = IoCToken<string, 'Db'>('Db');\\n\\nconst ioc = new IoCContainer().RegisterFactory($Db, () => {\\n  throw new Error('no connection string');\\n});\\n\\nawait ioc.Start();\\n\\ntry {\\n  await ioc.Activate();\\n} catch (err) {\\n  console.log((err as IoCActivationError).Services); // [ \\\"Db\\\" ]\\n}\\n```\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Lifecycle › Dispose()\",\"Text\":\"```ts ignore\\nDispose(): Promise<void>\\n[Symbol.asyncDispose](): Promise<void> // enables `await using`\\n```\\n\\nShuts the container down, in this order:\\n\\n1. Waits for a running `Start()` to finish its current module.\\n2. Runs `OnStop` of every started module: the live scopes' modules first, then this container's,\\n   in reverse start order. Services are all still alive at this point.\\n3. Disposes the live scopes.\\n4. Disposes the instances this container built, in reverse creation order.\\n\\nEvery step runs even if an earlier one fails. The failures are thrown together as one\\n[`IoCDisposeError`](./errors.md#errors-occurred-while-disposing-the-ioc-container) (an\\n`AggregateError`). Calling it again returns the same promise. Afterwards, resolving, registering,\\n`Use()`, `CreateScope()`, `Start()` and `Activate()` throw `IoCContainerDisposedError`; inspection\\n(`Has`, `Names`, `Describe`, `Validate`) still works.\\n\\n```ts\\nimport { IoCContainer } from '@fathym/ioc';\\n\\nclass Pool {\\n  async [Symbol.asyncDispose]() {\\n    console.log('pool closed');\\n  }\\n}\\n\\n{\\n  await using ioc = new IoCContainer().RegisterClass(Pool);\\n\\n  await ioc.Resolve(Pool);\\n} // pool closed\\n```\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Lifecycle › What gets disposed\",\"Text\":\"- **Singletons and scoped instances** the container built, when they have `Symbol.asyncDispose` or\\n  `Symbol.dispose`, or a `Dispose` option. A singleton is disposed by the container that holds its\\n  registration; a scoped instance by its scope.\\n- **Not transient instances.** The container doesn't track them; whoever resolved one owns it.\\n- **Not values** from `RegisterValue`, unless registered with a `Dispose` option.\\n- **Each instance once,** by the container that built it, even when it is also registered\\n  elsewhere.\\n- Each disposer is bounded by `PendingTimeoutMs`.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\ninterface Kv {\\n  close(): void;\\n}\\n\\nconst $Kv = IoCToken<Kv, 'Kv'>('Kv');\\n\\nconst ioc = new IoCContainer().RegisterFactory(\\n  $Kv,\\n  () => ({ close: () => console.log('kv closed') }),\\n  { Dispose: (kv) => kv.close() },\\n);\\n\\nawait ioc.Resolve($Kv);\\n\\nawait ioc.Dispose(); // kv closed\\n```\\n\\n---\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Inspection › Validate(options?)\",\"Text\":\"```ts ignore\\nValidate(options?: { Throw?: boolean }): IoCValidationIssue[]\\n```\\n\\nChecks the registrations visible from this container without building anything, and throws one\\n[`IoCValidationError`](./errors.md#ioc-validation-failed-) listing every problem. With\\n`{ Throw: false }` it returns the issues instead (`[]` when there are none). `Start()` calls it.\\n\\n| `Kind`      | Problem                                                                                                          |\\n| ----------- | ---------------------------------------------------------------------------------------------------------------- |\\n| `missing`   | A declared dependency (`Deps`) that isn't registered, and wasn't declared with `Expect()`                        |\\n| `cycle`     | Services whose declared dependencies loop                                                                        |\\n| `captive`   | A singleton that depends on a scoped service, directly or through transients; it would keep one instance forever |\\n| `arguments` | A class registered without `Deps` whose constructor declares parameters                                          |\\n\\nOnly declared `Deps` are checked: what a factory resolves in its body is only known when it runs.\\nEach issue is `{ Kind, Service, Message, Hint }`; `Hint` says what to change, and the thrown\\nerror's message shows it as a `Fix:` line under each problem.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\n\\nclass Repo {\\n  constructor(public url: string) {}\\n}\\n\\nconst ioc = new IoCContainer().RegisterClass(Repo, { Deps: [$Url] });\\n\\nconsole.log(ioc.Validate({ Throw: false }).map((i) => i.Message));\\n// [ \\\"Repo depends on Url, which is not registered.\\\" ]\\n```\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Inspection › Describe()\",\"Text\":\"```ts ignore\\nDescribe(): IoCDescription\\n```\\n\\nReturns the container's state, registrations and modules as plain data, for logs, admin pages and\\ntests.\\n\\n| Field      | Contents                                                                                                  |\\n| ---------- | --------------------------------------------------------------------------------------------------------- |\\n| `State`    | The container's [state](#state)                                                                           |\\n| `Scope`    | `true` for a scope                                                                                        |\\n| `Services` | Every registration visible from here, nearest first, shadowed ones left out (see `IoCServiceDescription`) |\\n| `Modules`  | The modules added to this container (not its parent's), in start order: `{ Name, Requires, Started }`     |\\n\\nEach service is `{ Key, Name, Label, Kind, Lifetime, Default, Deps, Depth }`: `Kind` is `class`,\\n`factory` or `value`; `Label` is `Key` or `Key[name]`, as in error messages; `Deps` are labels;\\n`Depth` is 0 for this container, 1 for its parent, and so on.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\n\\nclass Repo {\\n  constructor(public url: string) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Url, 'kv://local')\\n  .RegisterClass(Repo, { Deps: [$Url] });\\n\\nconst repo = ioc.Describe().Services.find((s) => s.Key === 'Repo');\\n\\nconsole.log(repo?.Kind, repo?.Lifetime, repo?.Deps); // class singleton [ \\\"Url\\\" ]\\n```\\n\\n---\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Testing › Override(key, value, options?)\",\"Text\":\"```ts ignore\\nOverride<K extends IoCServiceKey<unknown>>(\\n  key: K,\\n  value: IoCServiceOf<K>,\\n  options?: { Name?: string },\\n): () => void\\n```\\n\\nReplaces a registration with a value until the returned function is called, which puts back exactly\\nwhat was there before (or removes the override if nothing was). It works on any container or\\nscope, and only changes that container. Several overrides of one key can be restored in any\\norder: once all are restored, the original is back.\\n\\n- Instances already built from the old registration keep what they were given. Override before\\n  resolving the services that use it, or override in a fresh scope.\\n- If something replaced the override in the meantime, restoring leaves that alone.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Clock = IoCToken<() => number, 'Clock'>('Clock');\\n\\nconst ioc = new IoCContainer().RegisterValue($Clock, () => Date.now());\\n\\nconst restore = ioc.Override($Clock, () => 0);\\n\\nconsole.log((await ioc.Resolve($Clock))()); // 0\\n\\nrestore();\\n\\nconsole.log((await ioc.Resolve($Clock))() > 0); // true\\n```\\n\\n---\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Types\",\"Text\":\"All types are exported from `@fathym/ioc`. Most are inferred; you rarely write them.\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Types › Key and dependency types\",\"Text\":\"| Type                          | Meaning                                                                                     |\\n| ----------------------------- | ------------------------------------------------------------------------------------------- |\\n| `IoCToken<T, TId>`            | A typed symbol key. `T` is the service type, `TId` the name (`string` unless given).        |\\n| `IoCTokenOf<TToken>`          | The service type a token carries.                                                           |\\n| `IoCServiceKey<T>`            | Anything a service is registered and resolved by: a token or a class (abstract included).   |\\n| `IoCServiceOf<TKey>`          | The service type a key resolves to: the token's type, or the class's instance type.         |\\n| `IoCServiceConstructor<T>`    | A class that can be constructed (what `RegisterClass` takes).                               |\\n| `IoCServiceKeyConstructor<T>` | A class used only as a key; abstract classes fit.                                           |\\n| `IoCDependencyKey<T>`         | A dependency key: a token or a class.                                                       |\\n| `IoCDependency<T>`            | A `Deps` entry: a key, or `[key, name]`.                                                    |\\n| `IoCDependencyValue<D>`       | The value one dependency injects.                                                           |\\n| `IoCDependencyValues<TDeps>`  | The values a `Deps` list injects, in order (a factory's parameters after `ioc`).            |\\n| `IoCDependenciesFor<P, K>`    | One dependency per constructor parameter, typed to match it (the type of a class's `Deps`). |\\n| `IoCFactoryDependency<K>`     | A dependency a factory may declare: on a typed container, a key registered so far.          |\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Types › Registry types\",\"Text\":\"These describe what a [typed container](#typed) knows. `IoCContainer<TKeys>`'s type argument is the\\nregistry; `any` (the default) means untyped.\\n\\n| Type                           | Meaning                                                                                      |\\n| ------------------------------ | -------------------------------------------------------------------------------------------- |\\n| `IoCNoKeys`                    | The registry of a typed container with nothing registered yet.                               |\\n| `IoCAllowedKeys<TKeys>`        | The dependencies a registry allows: everything when untyped, otherwise the registered keys.  |\\n| `IoCRegistered<TKey, TName>`   | What a registration adds: the key for the default name, or `[key, name]`.                    |\\n| `IoCExpected<TDeps>`           | What `Expect()` (or a module's `Needs`) adds.                                                |\\n| `IoCTypeFor<TInstance, TType>` | The `Type` option's type: the token, or `IoCTypeMismatch` when the class doesn't satisfy it. |\\n| `IoCTypeMismatch<TI, TS>`      | Shown in compile errors when a class doesn't implement its `Type` token's type.              |\\n| `IoCUnmetNeeds<TKeys, TMods>`  | The keys some modules need that a registry lacks.                                            |\\n| `IoCCheckNeeds<TKeys, TMods>`  | Makes `Use()` fail to compile, naming the unmet needs (`'@fathym/ioc/unmet-needs'`).         |\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Types › Module types\",\"Text\":\"| Type                                             | Meaning                                                                   |\\n| ------------------------------------------------ | ------------------------------------------------------------------------- |\\n| `IoCModule<TNeeds, TProvides>`                   | A module (see [IoCModule](#iocmodule)). The type arguments are type-only. |\\n| `IoCModuleDefinition<TRequires, TNeeds, TR>`     | What `DefineModule` takes.                                                |\\n| `IoCModuleKeys<TRequires, TNeeds>`               | The registry a typed module's functions see.                              |\\n| `IoCModuleNeeds<M>` / `IoCModulesNeed<Ms>`       | The keys a module (or a list of modules) needs from elsewhere.            |\\n| `IoCModuleProvides<M>` / `IoCModulesProvide<Ms>` | The keys a module (or a list of modules) registers itself.                |\\n| `IoCModuleTypes<TNeeds, TProvides>`              | The type-only marker a module carries.                                    |\\n| `IoCKeysOf<TContainer>`                          | The registry of a container type.                                         |\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Types › Other types\",\"Text\":\"| Type                      | Meaning                                                                        |\\n| ------------------------- | ------------------------------------------------------------------------------ |\\n| `IoCContainerOptions`     | `{ PendingTimeoutMs? }`                                                        |\\n| `IoCContainerState`       | `'idle' \\\\| 'starting' \\\\| 'started' \\\\| 'stopping' \\\\| 'disposed'`                |\\n| `IoCServiceOptions`       | `{ Lifetime?, Name?, Default?, Replace? }`, shared by the registration methods |\\n| `IoCRegisterClassOptions` | `RegisterClass`'s options: the shared ones plus `Deps`, `Type`, `Dispose`      |\\n| `IoCRegisterOptions`      | `RegisterFactory`'s options (besides `Deps`): the shared ones plus `Dispose`   |\\n| `IoCServiceResolver<T>`   | `(ioc: IoCContainer) => T \\\\| Promise<T>`: a factory without dependencies       |\\n| `IoCDescription`          | What `Describe()` returns                                                      |\\n| `IoCServiceDescription`   | One entry of `Describe().Services`                                             |\\n| `IoCValidationIssue`      | One problem found by `Validate()`: `{ Kind, Service, Message, Hint }`          |\\n| `IoCErrorCode`            | The union of every error code                                                  |\\n\\n---\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Errors\",\"Text\":\"```ts ignore\\nfunction isIoCError(error: unknown, code?: IoCErrorCode): error is Error & { code: IoCErrorCode };\\n```\\n\\nEvery error the container throws has a stable `code`. Match on the code rather than the message,\\nwhich may gain detail. `isIoCError(err, code?)` checks it; prefer it to `instanceof`, because\\n`IoCActivationError` and `IoCDisposeError` extend `AggregateError` rather than `IoCError`. Every\\nother class extends the abstract `IoCError`.\\n\\n| Class                           | Code                                          | Properties                                      |\\n| ------------------------------- | --------------------------------------------- | ----------------------------------------------- |\\n| `IoCServiceNotFoundError`       | `IOC_SERVICE_NOT_FOUND`                       | `Key`, `ServiceName`, `RegisteredNames`, `Path` |\\n| `IoCCircularDependencyError`    | `IOC_CIRCULAR_DEPENDENCY`                     | `Path`                                          |\\n| `IoCValidationError`            | `IOC_VALIDATION_FAILED`                       | `Problems`, `Issues`                            |\\n| `IoCContainerDisposedError`     | `IOC_CONTAINER_DISPOSED`                      | none                                            |\\n| `IoCActivationError`            | `IOC_ACTIVATION_FAILED`                       | `errors`, `Services`                            |\\n| `IoCDisposeError`               | `IOC_DISPOSE_FAILED`                          | `errors`                                        |\\n| `IoCRegistrationError`          | `IOC_INVALID_REGISTRATION`, `IOC_INVALID_KEY` | `code`                                          |\\n| `IoCScopeRequiredError`         | `IOC_SCOPE_REQUIRED`                          | `Service`                                       |\\n| `IoCDuplicateRegistrationError` | `IOC_DUPLICATE_REGISTRATION`                  | `Service`                                       |\\n| `IoCModuleCycleError`           | `IOC_MODULE_CYCLE`                            | `Path`                                          |\\n| `IoCStartError`                 | `IOC_START_FAILED`                            | `Module`, `cause`, `RollbackErrors`             |\\n| `IoCNotIsolatableError`         | `IOC_NOT_ISOLATABLE`                          | `Service`, `Reason`                             |\\n| `IoCResolveTimeoutError`        | `IOC_RESOLVE_TIMEOUT`                         | `Service`, `TimeoutMs`                          |\\n\\nEvery error class also has `DocsUrl`, the link to its code's section in the\\n[error catalog](./errors.md#error-codes); `ioCErrorDocsUrl(code)` gives the same link for a code.\\nEach message, its causes and its fix are in the [error catalog](./errors.md).\\n\\n```ts\\nimport { IoCContainer, IoCServiceNotFoundError, IoCToken, isIoCError } from '@fathym/ioc';\\n\\nconst $Missing = IoCToken<string, 'Missing'>('Missing');\\n\\ntry {\\n  await new IoCContainer().Resolve($Missing);\\n} catch (err) {\\n  console.log(isIoCError(err, 'IOC_SERVICE_NOT_FOUND')); // true\\n  console.log((err as IoCServiceNotFoundError).Key); // Missing\\n}\\n```\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › What's Next\",\"Text\":\"- Every error message, explained: [errors.md](./errors.md) _[Reference]_\\n- Learn the container step by step: [getting started](../getting-started/README.md) _[Tutorial]_\\n- Coming from 0.x: [migration guide](../migration/from-0.x.md) _[How-to]_\\n- Runnable programs: [examples](../../examples/README.md)\\n- Versioning and support: [policy.md](../policy.md) _[Reference]_\"},{\"Path\":\"docs/reference/comparison.md\",\"Title\":\"Comparison with other DI containers\",\"Text\":\"This page is generated by `deno task compare` from the code in [`compare/`](../../compare/run.ts):\\nthe same scenarios and the same small service graph in each library, at pinned versions. Re-run\\nit to check any result. Generated 2026-11-01 on Deno/2.9.6 x86_64-unknown-linux-gnu, Intel(R) Xeon(R) Processor @ 2.10GHz.\\n\\n| Library     | Package               |\\n| ----------- | --------------------- |\\n| @fathym/ioc | `this repository`     |\\n| InversifyJS | `npm:inversify@8.2.3` |\\n| awilix      | `npm:awilix@13.0.5`   |\\n| tsyringe    | `npm:tsyringe@4.10.0` |\\n\\nEach adapter uses the library the way its documentation recommends, without decorator syntax\\n(InversifyJS through `toDynamicValue` and `toResolvedValue`, tsyringe by calling `injectable()`\\nand `inject()` directly), so the suite needs no compiler flags. That changes how dependencies are\\ndeclared, not the behavior measured. Corrections are welcome: open an issue or a pull request\\nagainst the adapter.\"},{\"Path\":\"docs/reference/comparison.md\",\"Title\":\"Comparison with other DI containers › Lifecycle and wiring\",\"Text\":\"|                                                                |      @fathym/ioc      |                        InversifyJS                         |                            awilix                            |                           tsyringe                           |\\n| -------------------------------------------------------------- | :-------------------: | :--------------------------------------------------------: | :----------------------------------------------------------: | :----------------------------------------------------------: |\\n| Concurrent first resolves build an async singleton once        |           ✓           |                             ✓                              |                     ✓ the cached promise                     |                     ✓ the cached promise                     |\\n| An async dependency is injected as the instance, not a promise |           ✓           |                        ✓ `getAsync`                        |                ✗ injects the pending promise                 |                ✗ injects the pending promise                 |\\n| A failed async build is retried, not cached                    |           ✓           |                  ✗ the failure is cached                   |               ✗ the rejected promise is cached               |               ✗ the rejected promise is cached               |\\n| A request scope disposes its instances when the request throws | ✓ `await using` scope | ✓ child container + `onDeactivation`, unbound in `finally` |               ✓ `scope.dispose()` in `finally`               |         ✓ child container, `dispose()` in `finally`          |\\n| Disposal runs in reverse creation order                        |           ✓           |   ✗ A, B: follows registration order, not creation order   | ✗ A, B: a dependency is disposed before the service using it | ✗ A, B: a dependency is disposed before the service using it |\\n| A missing dependency is found at startup, before any resolve   |    ✓ `Validate()`     |        ✗ no validation API; fails at first resolve         |         ✗ no validation API; fails at first resolve          |         ✗ no validation API; fails at first resolve          |\\n| A wrong dependency fails to compile                            |           ✓           |                             ✓                              |                              ✗                               |                              ✗                               |\\n\\nWhat each row does is in [`compare/scenarios.ts`](../../compare/scenarios.ts), and how each library\\ndoes it is in [`compare/adapters/`](../../compare/adapters/ioc.ts). The compile check wires a logger\\nwhere a repository needs a database and asks whether `deno check` rejects it.\"},{\"Path\":\"docs/reference/comparison.md\",\"Title\":\"Comparison with other DI containers › Benchmarks\",\"Text\":\"The same graph in each library: two values, a singleton repository, a transient handler, and a\\nscoped request context. `Resolve` in `@fathym/ioc` always returns a promise, so each resolve\\nincludes at least one `await`; services whose dependencies are ready are built synchronously\\ninside it, and only work that is still pending gets a `PendingTimeoutMs` timer. The other three\\nresolve synchronously. Treat these as orders of magnitude on one machine, not as a ranking: at\\nabout a microsecond per resolve, the container is rarely what limits an application.\\n\\n**cold start**\\n\\n| Library     | Time per iteration | Per second |\\n| ----------- | -----------------: | ---------: |\\n| tsyringe    |             1.2 µs |    838,223 |\\n| @fathym/ioc |            18.1 µs |     55,386 |\\n| awilix      |            18.6 µs |     53,818 |\\n| InversifyJS |            50.7 µs |     19,732 |\\n\\n**resolve**\\n\\n| Library     | Time per iteration | Per second |\\n| ----------- | -----------------: | ---------: |\\n| InversifyJS |              51 ns | 19,665,279 |\\n| awilix      |             134 ns |  7,488,224 |\\n| tsyringe    |             180 ns |  5,542,185 |\\n| @fathym/ioc |             1.2 µs |    817,166 |\\n\\n**scope per request**\\n\\n| Library     | Time per iteration | Per second |\\n| ----------- | -----------------: | ---------: |\\n| tsyringe    |             4.8 µs |    207,008 |\\n| awilix      |            17.4 µs |     57,394 |\\n| @fathym/ioc |            25.7 µs |     38,961 |\\n| InversifyJS |            72.3 µs |     13,839 |\\n\\nSource: [`compare/bench.ts`](../../compare/bench.ts).\"},{\"Path\":\"docs/reference/comparison.md\",\"Title\":\"Comparison with other DI containers › What this page doesn't cover\",\"Text\":\"- **Features we leave out on purpose:** synchronous resolution, auto-registration by scanning\\n  files, property injection, and contextual bindings. See\\n  [the README](../../README.md#how-it-compares) for when to choose another library.\\n- **NestJS**, which is a framework with DI built in rather than a container library.\"},{\"Path\":\"docs/reference/comparison.md\",\"Title\":\"Comparison with other DI containers › What's Next\",\"Text\":\"- What `@fathym/ioc` promises, with the tests that prove it: [guarantees.md](./guarantees.md)\\n  _[Reference]_\\n- Every method and option: [api.md](./api.md) _[Reference]_\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog\",\"Text\":\"Search this page for the text of your error. Every message the container can produce is listed\\nhere, and CI fails if a new one is added without an entry.\\n\\n| Error class                     | Code                                          | Messages                                                                                                |\\n| ------------------------------- | --------------------------------------------- | ------------------------------------------------------------------------------------------------------- |\\n| `IoCServiceNotFoundError`       | `IOC_SERVICE_NOT_FOUND`                       | [No service is registered for …](#no-service-is-registered-for-)                                        |\\n| `IoCCircularDependencyError`    | `IOC_CIRCULAR_DEPENDENCY`                     | [Circular dependency detected: …](#circular-dependency-detected-)                                       |\\n| `IoCValidationError`            | `IOC_VALIDATION_FAILED`                       | [IoC validation failed: …](#ioc-validation-failed-), with [four kinds of problem](#validation-problems) |\\n| `IoCContainerDisposedError`     | `IOC_CONTAINER_DISPOSED`                      | [The IoC container has been disposed.](#the-ioc-container-has-been-disposed)                            |\\n| `IoCActivationError`            | `IOC_ACTIVATION_FAILED`                       | [IoC activation failed for: …](#ioc-activation-failed-for-)                                             |\\n| `IoCDisposeError`               | `IOC_DISPOSE_FAILED`                          | [Errors occurred while disposing …](#errors-occurred-while-disposing-the-ioc-container)                 |\\n| `IoCResolveTimeoutError`        | `IOC_RESOLVE_TIMEOUT`                         | [… did not finish within …ms](#-did-not-finish-within-ms)                                               |\\n| `IoCScopeRequiredError`         | `IOC_SCOPE_REQUIRED`                          | [Scoped service … was resolved outside a scope](#scoped-service--was-resolved-outside-a-scope)          |\\n| `IoCDuplicateRegistrationError` | `IOC_DUPLICATE_REGISTRATION`                  | [… is already registered](#-is-already-registered)                                                      |\\n| `IoCModuleCycleError`           | `IOC_MODULE_CYCLE`                            | [Module dependency cycle: …](#module-dependency-cycle-)                                                 |\\n| `IoCStartError`                 | `IOC_START_FAILED`                            | [Module '…' failed to start: …](#module--failed-to-start-)                                              |\\n| `IoCNotIsolatableError`         | `IOC_NOT_ISOLATABLE`                          | [… can't be isolated: …](#-cant-be-isolated-)                                                           |\\n| `IoCRegistrationError`          | `IOC_INVALID_REGISTRATION`, `IOC_INVALID_KEY` | [Registration and usage mistakes](#registration-errors)                                                 |\\n| TypeScript                      | —                                             | [Compile errors](#typescript-errors)                                                                    |\\n\\nAll error classes are exported from `@fathym/ioc`, and each has a stable `code`. Match on the code\\nrather than the message, which may gain detail. `isIoCError(err, code)` checks the code without\\n`instanceof`, so it also covers `IoCActivationError` and `IoCDisposeError`, which are\\n`AggregateError`s.\\n\\n```ts\\nimport { IoCContainer, IoCToken, isIoCError } from '@fathym/ioc';\\n\\nconst $Missing = IoCToken<string, 'Missing'>('Missing');\\n\\ntry {\\n  await new IoCContainer().Resolve($Missing);\\n} catch (err) {\\n  if (isIoCError(err, 'IOC_SERVICE_NOT_FOUND')) console.log('not registered');\\n}\\n```\\n\\nEvery error also has a `DocsUrl` that links to its code's section below, and `Validate()` puts a\\n`Fix:` line under each problem. Both are written so that a person or a coding agent can act on\\nthem directly.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Error codes › `IOC_SERVICE_NOT_FOUND`\",\"Text\":\"`IoCServiceNotFoundError`: nothing is registered for the key and name being resolved.\\n[Details](#no-service-is-registered-for-). **Fix:** register it, check the `Name`, or `Use()` the\\nmodule that provides it.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Error codes › `IOC_CIRCULAR_DEPENDENCY`\",\"Text\":\"`IoCCircularDependencyError`: resolving a service would need the service itself.\\n[Details](#circular-dependency-detected-). **Fix:** move what both sides need into a third service,\\nor resolve one side later, in a method instead of a constructor.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Error codes › `IOC_VALIDATION_FAILED`\",\"Text\":\"`IoCValidationError`: `Validate()` (or `Start()`) found problems in the wiring; each one comes with\\na `Fix:` line. [Details](#ioc-validation-failed-).\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Error codes › `IOC_CONTAINER_DISPOSED`\",\"Text\":\"`IoCContainerDisposedError`: the container, or a parent of the scope, was already disposed.\\n[Details](#the-ioc-container-has-been-disposed). **Fix:** don't use a container after\\n`Dispose()`; create a new scope per request.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Error codes › `IOC_ACTIVATION_FAILED`\",\"Text\":\"`IoCActivationError` (an `AggregateError`): `Activate()` could not build one or more singletons.\\n[Details](#ioc-activation-failed-for-). **Fix:** read `errors` for each cause; `Activate()` can be\\ncalled again.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Error codes › `IOC_DISPOSE_FAILED`\",\"Text\":\"`IoCDisposeError` (an `AggregateError`): one or more disposers or `OnStop` hooks threw; the rest\\nstill ran. [Details](#errors-occurred-while-disposing-the-ioc-container). **Fix:** read `errors`.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Error codes › `IOC_RESOLVE_TIMEOUT`\",\"Text\":\"`IoCResolveTimeoutError`: a build, `OnStart`, `OnStop` or disposer took longer than\\n`PendingTimeoutMs`. [Details](#-did-not-finish-within-ms). **Fix:** find the slow factory or hook,\\ngive it its own timeout, or raise `PendingTimeoutMs`.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Error codes › `IOC_SCOPE_REQUIRED`\",\"Text\":\"`IoCScopeRequiredError`: a scoped service was resolved from the root container.\\n[Details](#scoped-service--was-resolved-outside-a-scope). **Fix:** resolve it from\\n`ioc.CreateScope()`.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Error codes › `IOC_DUPLICATE_REGISTRATION`\",\"Text\":\"`IoCDuplicateRegistrationError`: the key and name are already registered.\\n[Details](#-is-already-registered). **Fix:** pass `Replace: true` to replace it on purpose, or give\\nit a different `Name`.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Error codes › `IOC_MODULE_CYCLE`\",\"Text\":\"`IoCModuleCycleError`: modules require each other in a loop. [Details](#module-dependency-cycle-).\\n**Fix:** move the shared registrations into a module both require.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Error codes › `IOC_START_FAILED`\",\"Text\":\"`IoCStartError`: a module's `OnStart` failed; the modules already started were stopped again.\\n[Details](#module--failed-to-start-). **Fix:** read `cause`; `Start()` can be called again.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Error codes › `IOC_NOT_ISOLATABLE`\",\"Text\":\"`IoCNotIsolatableError`: `Isolate()` was given a key it can't copy into the scope.\\n[Details](#-cant-be-isolated-). **Fix:** isolate only singletons registered in a parent.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Error codes › `IOC_INVALID_REGISTRATION`\",\"Text\":\"`IoCRegistrationError`: a registration or call was malformed.\\n[Details](#registration-errors). **Fix:** follow the message; each variant is listed there.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Error codes › `IOC_INVALID_KEY`\",\"Text\":\"`IoCRegistrationError`: a key was neither a token nor a class (a string, say).\\n[Details](#keys-must-be-tokens-or-classes-but-a--was-given). **Fix:** use\\n`IoCToken<T>('name')` or the class itself.\\n\\n---\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › No service is registered for …\",\"Text\":\"```text\\nNo service is registered for Db.\\nNo service is registered for Db with name 'replica'. Registered names: [$default, primary].\\nNo service is registered for Url. Resolution path: Repo -> Db.\\nNo service is registered for Request. It is declared with Expect(); register it on the container or scope that provides it.\\n```\\n\\n`IoCServiceNotFoundError` (`IOC_SERVICE_NOT_FOUND`). Nothing is registered for that key and name,\\nhere or in a parent. The message lists the names that _are_ registered for the key, and the\\nresolution path when a factory or `Deps` asked for it. `Key`, `ServiceName`, `RegisteredNames`\\nand `Path` hold the same details.\\n\\n**Fix:** register it, or resolve the name that is registered. If a scope provides the key (a\\nrequest, a command), resolve from that scope, not the root. To make a dependency optional, use\\n`TryResolve`, which returns `undefined` when nothing is registered.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Circular dependency detected: …\",\"Text\":\"```text\\nCircular dependency detected: Orders -> Billing -> Orders.\\n```\\n\\n`IoCCircularDependencyError` (`IOC_CIRCULAR_DEPENDENCY`). A service needs itself, directly or\\nthrough others, while it is being built. `Path` lists the chain. The container sees the chain\\nwhen factories resolve through the `ioc` they receive, or through `Deps`.\\n\\n**Fix:** break the loop. Move the shared part into a third service both depend on, or have one\\nside resolve the other later, after construction, from the `ioc` its factory received:\\n\\n```ts\\nimport { IoCContainer } from '@fathym/ioc';\\n\\nclass Billing {\\n  constructor(private orders: () => Promise<Orders>) {}\\n\\n  async total() {\\n    return (await this.orders()).count * 10;\\n  }\\n}\\n\\nclass Orders {\\n  public count = 3;\\n\\n  constructor(public billing: Billing) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  .RegisterFactory(Billing, (c) => new Billing(() => c.Resolve(Orders))) // resolved on first use\\n  .RegisterClass(Orders, { Deps: [Billing] });\\n\\nconsole.log(await (await ioc.Resolve(Orders)).billing.total()); // 30\\n```\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › IoC validation failed: …\",\"Text\":\"```text\\nIoC validation failed:\\n  - Repo depends on Url, which is not registered.\\n    Fix: Register Url with RegisterClass, RegisterFactory or RegisterValue, or Use() the module that provides it. If a scope or the host registers it later, declare it with Expect().\\n  - singleton Cache depends on scoped Session; it would keep one instance for its whole life. Make Cache scoped, or resolve Session where it is used, from the scope at hand.\\n    Fix: Register Cache with Lifetime: 'scoped', or remove Session from its Deps and resolve it from the request's scope where it is needed.\\nDocs: https://github.com/fathym/ioc/blob/main/docs/reference/errors.md#ioc_validation_failed\\n```\\n\\n`IoCValidationError` (`IOC_VALIDATION_FAILED`), from `Validate()` and from `Start()`, which\\nvalidates first. It lists every problem at once, each with a `Fix:` line; `Issues` holds them as\\n`{ Kind, Service, Message, Hint }` and `Problems` as messages. Only declared `Deps` are checked.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › IoC validation failed: … › Validation problems\",\"Text\":\"#### `missing`: X depends on Y, which is not registered.\\n\\nA declared dependency nobody registers. **Fix:** register it, or declare it with `Expect()` when\\na scope or the hosting code registers it later.\\n\\n#### `cycle`: Circular dependency: A -> B -> A.\\n\\nDeclared dependencies that loop; resolving any of them would throw\\n[`IoCCircularDependencyError`](#circular-dependency-detected-). Each cycle is reported once.\\n\\n#### `captive`: singleton X depends on scoped Y; it would keep one instance for its whole life.\\n\\n```text\\nsingleton Cache depends on scoped Session (through Helper); it would keep one instance for its whole life. Make Cache scoped, or resolve Session where it is used, from the scope at hand.\\n```\\n\\nA singleton depends, directly or through transients, on a scoped service. The singleton would\\ncapture the first scope's instance forever. **Fix:** make the singleton scoped too, or have it\\nresolve the scoped service from the scope at hand when it needs it.\\n\\n#### `arguments`: X is constructed without arguments, but its constructor declares N parameter(s); register it with Deps or with a factory.\\n\\nA class registered without `Deps` would be built with `undefined` arguments. **Fix:**\\n`RegisterClass(X, { Deps: [...] })`, or a `RegisterFactory`. Parameters with a default value\\naren't counted; a constructor inherited through `extends` is.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › The IoC container has been disposed.\",\"Text\":\"```text\\nThe IoC container has been disposed.\\n```\\n\\n`IoCContainerDisposedError` (`IOC_CONTAINER_DISPOSED`). A container, or a scope whose parent was\\ndisposed, was used after `Dispose()`. `Start()` also rejects with it when `Dispose()` runs while\\nit is starting, and so does a `Resolve` whose build finishes after the container was disposed\\n(the instance is disposed at once). **Fix:** keep a container alive while it is used; create a new one (or a new\\nscope) instead of reusing a disposed one.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › IoC activation failed for: …\",\"Text\":\"```text\\nIoC activation failed for: Db, Search.\\n```\\n\\n`IoCActivationError` (`IOC_ACTIVATION_FAILED`), an `AggregateError` from `Activate()`. Every\\nsingleton that failed to build is named; `errors` holds their errors and `Services` their\\nlabels. The rest were built. **Fix:** fix each error in `errors`; `Activate()` can be called\\nagain, and the failed ones are rebuilt.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Errors occurred while disposing the IoC container.\",\"Text\":\"```text\\nErrors occurred while disposing the IoC container.\\n```\\n\\n`IoCDisposeError` (`IOC_DISPOSE_FAILED`), an `AggregateError` from `Dispose()`. A module's\\n`OnStop`, a scope, or an instance's disposer failed. Every other step still ran; `errors` holds\\neach failure. **Fix:** fix each error in `errors`.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › … did not finish within …ms\",\"Text\":\"```text\\nReport did not finish within 30000ms. Something it awaits may never settle (a connection, a lock), or factories may wait on each other through a container captured in a closure; resolve through the factory's parameter. Raise PendingTimeoutMs if it is just slow.\\nModule 'Server' OnStart did not finish within 30000ms. …\\nDisposing Pool did not finish within 30000ms. …\\n```\\n\\n`IoCResolveTimeoutError` (`IOC_RESOLVE_TIMEOUT`). A `Resolve`, a module's `OnStart`/`OnStop`, or\\nan instance's disposer was still pending after `PendingTimeoutMs` (30 seconds unless set).\\n`Service` names what was pending; `TimeoutMs` the limit. From `Start()` it arrives as\\n`IoCStartError`'s `cause`; from `Dispose()`, inside `IoCDisposeError`.\\n\\n**Likely causes:**\\n\\n- **Something that never settles,** such as a connection that waits forever. Give the factory\\n  its own timeout (`AbortSignal.timeout(…)` for `fetch`).\\n- **A cycle the container can't see:** factories waiting on each other through a container\\n  captured in a closure, after an `await`. Resolve through the factory's `ioc` instead, so the\\n  container follows the chain and throws\\n  [`IoCCircularDependencyError`](#circular-dependency-detected-) at once.\\n- **It is just slow.** Raise `new IoCContainer({ PendingTimeoutMs: 60_000 })`, or `0` to wait\\n  forever.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Scoped service … was resolved outside a scope\",\"Text\":\"```text\\nScoped service Session was resolved outside a scope; resolve it from a scope created with CreateScope().\\n```\\n\\n`IoCScopeRequiredError` (`IOC_SCOPE_REQUIRED`). A `scoped` service was resolved from the root\\ncontainer, which has no scope to own it. **Fix:** create a scope and resolve from it:\\n\\n```ts\\nimport { IoCContainer } from '@fathym/ioc';\\n\\nclass Session {}\\n\\nconst ioc = new IoCContainer().RegisterClass(Session, { Lifetime: 'scoped' });\\n\\nawait using scope = ioc.CreateScope();\\n\\nconsole.log((await scope.Resolve(Session)) instanceof Session); // true\\n```\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › … is already registered\",\"Text\":\"```text\\nMailer is already registered; pass Replace: true to override it, or Default: true to register a default that yields to other registrations.\\n```\\n\\n`IoCDuplicateRegistrationError` (`IOC_DUPLICATE_REGISTRATION`). The same key and name were\\nregistered twice in one container. **Fix:** pass `Replace: true` on the registration meant to\\nwin, or register the first one with `Default: true` so any later one replaces it. Registering a\\nkey on a scope that its parent also registers is not a duplicate: the scope's wins there.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Module dependency cycle: …\",\"Text\":\"```text\\nModule dependency cycle: Api -> Db -> Api.\\n```\\n\\n`IoCModuleCycleError` (`IOC_MODULE_CYCLE`), from `Use()`. Modules require each other through\\n`Requires`. **Fix:** move what both need into a third module that both require.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Module '…' failed to start: …\",\"Text\":\"```text\\nModule 'Server' failed to start: port 8080 in use\\nModule 'Reports' failed to start: it requires module 'Host', which belongs to a parent container that hasn't started; start the parent first\\n```\\n\\n`IoCStartError` (`IOC_START_FAILED`), from `Start()`. A module's `OnStart` threw (its error is the\\n`cause`). The modules that had started were stopped again, in reverse; errors from their\\n`OnStop` are in `RollbackErrors`. The container is back to `idle`, so `Start()` can be called\\nagain once the cause is fixed. The second message comes from a scope whose module requires a\\nmodule of a parent that hasn't started: start the parent first.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › … can't be isolated: …\",\"Text\":\"```text\\nUrl can't be isolated: it is a value, which every scope shares as is.\\n```\\n\\n`IoCNotIsolatableError` (`IOC_NOT_ISOLATABLE`), from `Isolate()`. Values are shared as they are;\\nthere is nothing to build per scope. **Fix:** register a different value on the scope instead.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Registration errors\",\"Text\":\"`IoCRegistrationError`, code `IOC_INVALID_REGISTRATION` unless noted.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Registration errors › Keys must be tokens or classes, but a … was given.\",\"Text\":\"```text\\nKeys must be tokens or classes, but a string was given. Create a token with IoCToken<T>('Name').\\n```\\n\\nCode `IOC_INVALID_KEY`. A string, plain object or plain function was used as a key. **Fix:** use\\na token (`IoCToken<T>('Name')`) or a class.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Registration errors › RegisterClass expects a class\",\"Text\":\"```text\\nRegisterClass expects a class; register functions with RegisterFactory and other values with RegisterValue.\\n```\\n\\n**Fix:** register a function with `RegisterFactory`, and any other value with `RegisterValue`.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Registration errors › … has an unknown Lifetime '…'; use 'singleton', 'transient' or 'scoped'.\",\"Text\":\"```text\\nSession has an unknown Lifetime 'Scoped'; use 'singleton', 'transient' or 'scoped'.\\n```\\n\\nA `Lifetime` value that isn't one of the three, usually from JavaScript or a cast. **Fix:** use\\n`'singleton'` (or leave it out), `'transient'` or `'scoped'`, in lower case.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Registration errors › RegisterFactory expects a factory function.\",\"Text\":\"```text\\nRegisterFactory expects a factory function.\\n```\\n\\n**Fix:** pass a function `(ioc) => value`.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Registration errors › A module needs a Name and a Register(ioc) function.\",\"Text\":\"```text\\nA module needs a Name and a Register(ioc) function.\\n```\\n\\n`Use()` was given something that isn't a module. **Fix:** give it `Name` and `Register`.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Registration errors › Module '…' was added after Start()\",\"Text\":\"```text\\nModule 'Metrics' was added after Start(); add modules before starting the container, or give late plugins a scope: ioc.CreateScope().Use(plugin).\\n```\\n\\n**Fix:** add every module before `Start()`. To load a plugin later, create a scope for it, `Use`\\nthe plugin there, and `Start()` the scope.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Registration errors › Isolate() works on scopes; call it on a container created with CreateScope().\",\"Text\":\"```text\\nIsolate() works on scopes; call it on a container created with CreateScope().\\n```\\n\\n**Fix:** call `Isolate()` on a scope; a root container already owns its registrations.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Registration errors › PendingTimeoutMs must be a number of milliseconds from 0 (off) to 2147483647 (about 24.8 days).\",\"Text\":\"```text\\nPendingTimeoutMs must be a number of milliseconds from 0 (off) to 2147483647 (about 24.8 days).\\n```\\n\\nFrom `new IoCContainer({ PendingTimeoutMs })` with a negative, `NaN`, infinite or too-large value\\n(timers overflow above 2147483647). **Fix:** pass a number in range, or `0` for no limit.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › TypeScript errors\",\"Text\":\"Errors the compiler reports for typed keys, `Deps` and typed containers.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › TypeScript errors › `Argument of type 'string' is not assignable to parameter of type 'IoCServiceKey<unknown>'`\",\"Text\":\"The same message names `'symbol'` or `'typeof k'` when an untyped symbol (`Symbol.for('Db')`,\\n`Symbol('Db')`) is used. A key must be a typed token: `IoCToken<T>('Name')`, or a symbol cast to\\none (`Symbol('Db') as IoCToken<Db, 'Db'>`).\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › TypeScript errors › `Type 'string' does not satisfy the constraint 'IoCServiceKey<unknown>'`\",\"Text\":\"An explicit type argument from 0.x code, such as `Resolve<Db>($Db)`. The type now comes from the\\nkey: write `Resolve($Db)`.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › TypeScript errors › `Type 'typeof X' is not assignable to type 'IoCDependency<Y> …'`\",\"Text\":\"A `Deps` entry doesn't match the constructor parameter at that position: wrong order, wrong type,\\nor a missing entry (`Source has 1 element(s) but target requires 2`). Make `Deps` follow the\\nconstructor's parameters, in order.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › TypeScript errors › `Type 'IoCToken<Db, \\\"Db\\\">' is not assignable to type 'IoCTypeMismatch<NotDb, Db> | undefined'`\",\"Text\":\"`RegisterClass(NotDb, { Type: $Db })` where instances of the class don't satisfy the token's\\ntype. Make the\\nclass implement the type, or use the right token.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › TypeScript errors › `Property ''@fathym/ioc/no-keys'' is missing` or `… is not assignable to type 'IoCNoKeys | …'`\",\"Text\":\"On a [typed container](./api.md), a `Deps` entry names a key that isn't registered (or\\nexpected) yet. Register it earlier in the chain, or declare it with `Expect()`.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › TypeScript errors › `Property ''@fathym/ioc/unmet-needs'' is missing`\",\"Text\":\"On a typed container, `Use(module)` was called before the keys the module `Needs` were\\nregistered. Register them first (or `Expect()` them); the error names the missing keys.\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › What's Next\",\"Text\":\"- Every method and option: [API reference](./api.md) _[Reference]_\\n- Upgrading from 0.x: [migration guide](../migration/from-0.x.md) _[How-to]_\"},{\"Path\":\"docs/reference/guarantees.md\",\"Title\":\"Guarantees\",\"Text\":\"These are the behaviors you can build on. Each one is a sentence, followed by the tests that prove\\nit. Links of the form _file › step_ name a test step, and the docs check fails if that step is\\nrenamed or removed, so a guarantee can't outlive its proof. Changing any of them is a breaking\\nchange under the [versioning policy](../policy.md#what-counts-as-breaking).\\n\\nCoverage of `src/` is reported by `deno task coverage` on every push: lines 98.8%, branches 97.1%,\\nfunctions 99% (November 2026), with CI failing below 97% of lines or 95% of branches.\"},{\"Path\":\"docs/reference/guarantees.md\",\"Title\":\"Guarantees › Building\",\"Text\":\"- **Concurrent first resolves of a singleton or scoped service build it once.** Every caller gets\\n  the same instance.\\n  - [lazy › concurrent resolves share one async creation](../../tests/ioc/lazy.tests.ts)\\n  - [eager-retry › a successful async singleton is built once by Activate()](../../tests/ioc/eager-retry.tests.ts)\\n  - [edge-cases › a factory returning a thenable builds once and is disposed](../../tests/ioc/edge-cases.tests.ts)\\n- **A failed build isn't cached.** The next resolve runs the factory again, whether it threw or\\n  rejected, and callers waiting on the failing build all get the error.\\n  - [lazy › a rejected creation is not memoized; the next resolve retries](../../tests/ioc/lazy.tests.ts)\\n  - [lazy › concurrent resolves during a failing creation all reject, then retry once](../../tests/ioc/lazy.tests.ts)\\n  - [lazy › a synchronous throw in a factory rejects and retries](../../tests/ioc/lazy.tests.ts)\\n  - [eager-retry › a resolve after a failed Activate() retries the factory](../../tests/ioc/eager-retry.tests.ts)\\n- **A dependency cycle throws, naming the path, instead of hanging.** That includes cycles through\\n  a factory's `ioc` argument.\\n  - [cycles › A -> B -> A through factory parameters](../../tests/ioc/cycles.tests.ts)\\n  - [cycles › long cycle reports the full path](../../tests/ioc/cycles.tests.ts)\\n  - [cycles › a failed cycle leaves services resolvable once the cycle is broken](../../tests/ioc/cycles.tests.ts)\\n  - [cycles › diamond dependencies resolve and share the bottom singleton](../../tests/ioc/cycles.tests.ts)\"},{\"Path\":\"docs/reference/guarantees.md\",\"Title\":\"Guarantees › Ownership and disposal\",\"Text\":\"- **The container owns only what it built successfully.** If a factory opens something and then\\n  throws, cleaning that up is the factory's job. Dependencies that were built before a sibling\\n  failed are still owned, and disposed with the container.\\n  - [guarantees › a factory that throws cleans up after itself: the container owns only what was built](../../tests/ioc/guarantees.tests.ts)\\n  - [guarantees › dependencies built before a sibling failed are still disposed with the container](../../tests/ioc/guarantees.tests.ts)\\n\\n  ```ts\\n  import { IoCContainer } from '@fathym/ioc';\\n\\n  class Connection {\\n    static open() {\\n      return new Connection();\\n    }\\n\\n    async handshake() {}\\n\\n    async [Symbol.asyncDispose]() {}\\n  }\\n\\n  const ioc = new IoCContainer().RegisterFactory(Connection, async () => {\\n    const conn = Connection.open();\\n\\n    try {\\n      await conn.handshake();\\n      return conn; // from here on, the container owns it\\n    } catch (err) {\\n      await conn[Symbol.asyncDispose](); // the factory closes what it opened\\n      throw err;\\n    }\\n  });\\n\\n  await ioc.Resolve(Connection);\\n  await ioc.Dispose();\\n  ```\\n\\n- **Each instance is disposed once, by the container or scope that built it.** Values you register\\n  are never disposed unless you pass a `Dispose` option, and transients are never disposed.\\n  - [ownership › an alias factory returning another registration: disposed once](../../tests/ioc/ownership.tests.ts)\\n  - [ownership › a scope resolving the root's singleton: only the root disposes it](../../tests/ioc/ownership.tests.ts)\\n  - [explicit › values are never disposed by the container](../../tests/ioc/explicit.tests.ts)\\n  - [explicit › a value given a Dispose callback is disposed with the container](../../tests/ioc/explicit.tests.ts)\\n  - [scopes › transients are never disposed](../../tests/ioc/scopes.tests.ts)\\n  - [scopes › a disposed scope rejects further use; Dispose is idempotent](../../tests/ioc/scopes.tests.ts)\\n- **Instances are disposed in reverse creation order.**\\n  - [scopes › instances are disposed in reverse creation order](../../tests/ioc/scopes.tests.ts)\\n- **A scope disposes its instances when the request ends, including when the request throws.** If a\\n  disposer throws too, the caller gets a `SuppressedError` that carries both errors.\\n  - [scopes › await using disposes the scope instances](../../tests/ioc/scopes.tests.ts)\\n  - [guarantees › a scope disposes its instances when the request throws](../../tests/ioc/guarantees.tests.ts)\\n  - [guarantees › when the request and a disposer both throw, the caller gets both (SuppressedError)](../../tests/ioc/guarantees.tests.ts)\\n- **Disposing a parent disposes its live scopes first, deepest first, then its own instances.** A\\n  scope of a disposed parent rejects every use.\\n  - [scopes › disposing a parent disposes its live scopes too](../../tests/ioc/scopes.tests.ts)\\n  - [scopes › after stopping modules, live scopes are disposed deepest first, then own instances](../../tests/ioc/scopes.tests.ts)\\n  - [scopes › a scope of a disposed parent rejects every use](../../tests/ioc/scopes.tests.ts)\\n- **One failing disposer or `OnStop` doesn't stop the rest.** Every step runs, and the failures are\\n  thrown together as one `IoCDisposeError` (an `AggregateError`). The one exception: a disposer\\n  that fails on an instance that arrived after `Dispose()` has no caller left to throw to, so its\\n  error is dropped.\\n  - [scopes › disposal errors are aggregated and every instance is still disposed](../../tests/ioc/scopes.tests.ts)\\n  - [scopes › errors from disposing child scopes reach the parent Dispose](../../tests/ioc/scopes.tests.ts)\\n  - [modules › every step runs; failures are thrown together](../../tests/ioc/modules.tests.ts)\\n  - [ownership › a late arrival that fails to dispose is not thrown](../../tests/ioc/ownership.tests.ts)\\n- **`Dispose()` doesn't wait for builds in flight.** A singleton or scoped instance that finishes\\n  after `Dispose()` is disposed on arrival, and the waiting `Resolve` rejects with\\n  `IoCContainerDisposedError`. A transient that finishes later is returned to its caller, who owns\\n  it.\\n  - [ownership › an instance that finishes building after Dispose() is disposed on arrival, and the resolve rejects](../../tests/ioc/ownership.tests.ts)\\n  - [edge-cases › a scoped build landing after the parent is disposed is disposed](../../tests/ioc/edge-cases.tests.ts)\\n  - [guarantees › a transient that finishes building after Dispose() is returned to its caller, who owns it](../../tests/ioc/guarantees.tests.ts)\"},{\"Path\":\"docs/reference/guarantees.md\",\"Title\":\"Guarantees › Startup\",\"Text\":\"- **`Start()` validates, then starts modules one at a time in dependency order.** If one fails, the\\n  started ones are stopped in reverse, and `Start()` can be called again. `Dispose()` during\\n  `Start()` lets the module that is starting finish, then stops it.\\n  - [modules › validates first, unless told not to](../../tests/ioc/modules.tests.ts)\\n  - [modules › runs OnStart in order, once, and reports State](../../tests/ioc/modules.tests.ts)\\n  - [modules › a failing OnStart stops the started modules in reverse, and can be retried](../../tests/ioc/modules.tests.ts)\\n  - [modules › Dispose() during Start() lets the current module finish, then stops it](../../tests/ioc/modules.tests.ts)\\n- **`Activate()` builds every singleton, reports every failure by name, and can be retried.**\\n  - [eager-retry › Activate() rejects with every failure, named](../../tests/ioc/eager-retry.tests.ts)\\n  - [eager-retry › Activate() can be retried after a failure](../../tests/ioc/eager-retry.tests.ts)\"},{\"Path\":\"docs/reference/guarantees.md\",\"Title\":\"Guarantees › Timeouts and cancellation\",\"Text\":\"- **`PendingTimeoutMs` (default 30 seconds) bounds every `Resolve`, every `Activate()` build, and\\n  each `OnStart`, `OnStop` and disposer.** `0` turns it off.\\n  - [modules › bounds OnStart](../../tests/ioc/modules.tests.ts)\\n  - [modules › bounds OnStop and disposers](../../tests/ioc/modules.tests.ts)\\n  - [guarantees › PendingTimeoutMs: 0 turns the timeout off](../../tests/ioc/guarantees.tests.ts)\\n- **A timeout rejects the caller; it doesn't cancel the build.** The build keeps running, and if\\n  it succeeds its result is cached, so the factory isn't called again.\\n  - [guarantees › after a timeout the build keeps running, and its late result is cached](../../tests/ioc/guarantees.tests.ts)\\n- **There is no cancellation.** The container doesn't pass an `AbortSignal` to factories. A factory\\n  that needs one uses its own, such as `AbortSignal.timeout(ms)`.\"},{\"Path\":\"docs/reference/guarantees.md\",\"Title\":\"Guarantees › What `Validate()` can see\",\"Text\":\"`Validate()` walks the declared dependency graph without building anything. It reports\\n`missing`, `cycle`, `captive` and `arguments` problems, all at once.\\n\\n| Wiring                                                | Checked? | Proof                                                                                                                                |\\n| ----------------------------------------------------- | -------- | ------------------------------------------------------------------------------------------------------------------------------------ |\\n| `Deps` on `RegisterClass` and `RegisterFactory`       | Yes      | [records › Validate sees factory Deps (missing, cycles, captive)](../../tests/ioc/records.tests.ts)                                  |\\n| A class with constructor parameters but no `Deps`     | Yes      | [validate › arguments: a class without Deps whose constructor takes parameters](../../tests/ioc/validate.tests.ts)                   |\\n| Registrations made by modules (`Use`)                 | Yes      | [guarantees › module registrations are validated like any other](../../tests/ioc/guarantees.tests.ts)                                |\\n| A parent singleton's dependencies, from a scope       | Yes      | [validate › a parent's singleton is checked where it is built, not in the scope](../../tests/ioc/validate.tests.ts)                  |\\n| Keys a factory resolves through `ioc` inside its body | No       | [validate › factories without Deps are not checked](../../tests/ioc/validate.tests.ts): declare them in `Deps`                       |\\n| Registrations added after `Validate()` ran            | Next run | [guarantees › Validate checks what is registered when it runs; call it again after adding more](../../tests/ioc/guarantees.tests.ts) |\\n| A service replaced with `Override()`                  | No       | [guarantees › an Override is a value, so the overridden registration is no longer checked](../../tests/ioc/guarantees.tests.ts)      |\\n\\nSo: declare `Deps` on factories too, and call `Validate()` (or `Start()`, which calls it) after the\\nlast registration.\"},{\"Path\":\"docs/reference/guarantees.md\",\"Title\":\"Guarantees › Compile time\",\"Text\":\"- **`Deps` is checked against the constructor.** A dependency in the wrong order, missing, extra,\\n  or of the wrong type is a compile error, so changing a constructor without updating its `Deps`\\n  doesn't compile. A class registered with no `Deps` at all compiles, and `Validate()` reports it\\n  as an `arguments` problem instead.\\n  - [types › Types](../../tests/ioc/types.tests.ts)\\n  - [typed › the constructor parameter types are still checked](../../tests/ioc/typed.tests.ts)\"},{\"Path\":\"docs/reference/guarantees.md\",\"Title\":\"Guarantees › What's Next\",\"Text\":\"- Every method and option: [api.md](./api.md) _[Reference]_\\n- Every error message, its cause and the fix: [errors.md](./errors.md) _[Reference]_\\n- What may change between releases: [versioning and support policy](../policy.md) _[Reference]_\"},{\"Path\":\"examples/README.md\",\"Title\":\"Examples\",\"Text\":\"Each example is a complete program that shows one idea. CI runs every one of them\\n(`tests/docs/examples.tests.ts`), so they always work with the current code.\\n\\nRun any of them from the repository root:\\n\\n```sh\\ndeno run -A examples/basic.ts\\ndeno test -A examples/testing-overrides.test.ts\\n```\\n\\n> **Note:** These import from `../mod.ts` so they run against the source in this repository. In\\n> your own project, import from `@fathym/ioc` instead.\\n\\n| Example                                                  | Shows                                                                                                                     | Read more                                                              |\\n| -------------------------------------------------------- | ------------------------------------------------------------------------------------------------------------------------- | ---------------------------------------------------------------------- |\\n| [basic.ts](./basic.ts)                                   | Values, classes, declared `Deps`, `Validate()`, singletons                                                                | [first-container.md](../docs/getting-started/first-container.md)       |\\n| [async-services.ts](./async-services.ts)                 | Deno KV from an async factory, a flaky client that succeeds on retry, `Activate()`, `Dispose()`                           | [async-services.md](../docs/getting-started/async-services.md)         |\\n| [per-request-server.ts](./per-request-server.ts)         | An HTTP app: `Start()` and `Activate()`, a scope per request, disposable services, graceful shutdown                      | [per-request-scopes.md](../docs/getting-started/per-request-scopes.md) |\\n| [testing-overrides.test.ts](./testing-overrides.test.ts) | Validating the real module, then faking one dependency with `Override()`                                                  | [testing-your-app.md](../docs/getting-started/testing-your-app.md)     |\\n| [plugins.ts](./plugins.ts)                               | Named implementations, `ResolveAll`, `TryResolve`, `Has`                                                                  | [api.md](../docs/reference/api.md)                                     |\\n| [typed-container.ts](./typed-container.ts)               | `Typed()` chains, `DefineModule` with `Needs` checked by `Use()`, `Expect` for a per-request key                          | [api.md](../docs/reference/api.md)                                     |\\n| [modules-lifecycle.ts](./modules-lifecycle.ts)           | Typed modules, a default the app replaces, a failed `Start()` that stops what started and is retried, `OnStop` on dispose | [api.md](../docs/reference/api.md)                                     |\"}],\"Recipes\":[{\"Path\":\"README.md\",\"Title\":\"@fathym/ioc › Dependency injection for modern TypeScript. No decorators. No metadata. Async from the ground up.\",\"About\":\"**@fathym/ioc is built for how TypeScript apps are written today.** Plain classes. Typed keys.\\nAsync factories that just work. Wiring mistakes caught by the compiler, and the rest caught at\\nstartup. Clean shutdown when you're done. It runs on Deno, Node.js and Bun, in about 6 KB gzipped,\\nwith zero dependencies.\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\ninterface Mailer {\\n  send(to: string, body: string): Promise<void>;\\n}\\n\\nclass Db {\\n  static async connect(url: string) {\\n    return new Db(url); // open your real connection pool here\\n  }\\n\\n  constructor(public url: string) {}\\n\\n  async [Symbol.asyncDispose]() {\\n    console.log('db closed');\\n  }\\n}\\n\\nclass Signup {\\n  constructor(private db: Db, private mailer: Mailer) {}\\n\\n  async register(email: string) {\\n    await this.mailer.send(email, `Welcome! (saved to ${this.db.url})`);\\n  }\\n}\\n\\nconst $Mailer = IoCToken<Mailer>('app/Mailer');\\n\\n{\\n  await using ioc = new IoCContainer()\\n    .RegisterFactory(Db, () => Db.connect('postgres://localhost/app')) // async, built once\\n    .RegisterValue($Mailer, { send: async (to, body) => console.log(`to ${to}: ${body}`) })\\n    .RegisterClass(Signup, { Deps: [Db, $Mailer] }); // checked against the constructor\\n\\n  ioc.Validate(); // every wiring mistake, reported before anything runs\\n\\n  const signup = await ioc.Resolve(Signup); // typed as Signup\\n\\n  await signup.register('ada@example.com'); // to ada@example.com: Welcome! (saved to …)\\n} // db closed: whatever the container built is disposed, in reverse order\"},{\"Path\":\"README.md\",\"Title\":\"@fathym/ioc › See it in action\",\"About\":\"**A scope per request,** cleaned up when the request ends:\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Request = IoCToken<{ path: string }>('app/Request');\\n\\nclass RequestContext {\\n  public id = crypto.randomUUID().slice(0, 8);\\n}\\n\\nclass Handler {\\n  constructor(private req: { path: string }, private ctx: RequestContext) {}\\n\\n  handle() {\\n    return `${this.ctx.id} handled ${this.req.path}`;\\n  }\\n}\\n\\nconst app = new IoCContainer()\\n  .RegisterClass(RequestContext, { Lifetime: 'scoped' }) // one per request\\n  .RegisterClass(Handler, { Deps: [$Request, RequestContext], Lifetime: 'transient' });\\n\\nfor (const path of ['/notes', '/users']) {\\n  await using scope = app.CreateScope().RegisterValue($Request, { path });\\n\\n  console.log((await scope.Resolve(Handler)).handle()); // 3f9c1a2b handled /notes …\\n}\"},{\"Path\":\"README.md\",\"Title\":\"@fathym/ioc › See it in action\",\"About\":\"**A constructor change the wiring didn't follow** doesn't compile:\",\"Code\":\"import { IoCContainer } from '@fathym/ioc';\\n\\nclass Db {}\\nclass Cache {}\\n\\nclass Repo {\\n  constructor(public db: Db, public cache: Cache) {} // gained a Cache parameter\\n}\\n\\nconst ioc = new IoCContainer().RegisterClass(Db).RegisterClass(Cache);\\n\\nioc.RegisterClass(Repo, {\\n  // @ts-expect-error Source has 1 element(s) but target requires 2.\\n  Deps: [Db],\\n});\"},{\"Path\":\"README.md\",\"Title\":\"@fathym/ioc › See it in action\",\"About\":\"**Modules with a lifecycle,** started in order and stopped in reverse:\",\"Code\":\"import { DefineModule, IoCContainer } from '@fathym/ioc';\\n\\nconst Database = DefineModule({\\n  Name: 'Database',\\n  Register: (ioc) => ioc,\\n  OnStart: () => console.log('database connected'),\\n  OnStop: () => console.log('database closed'),\\n});\\n\\nconst Api = DefineModule({\\n  Name: 'Api',\\n  Requires: [Database], // started after Database, stopped before it\\n  Register: (ioc) => ioc,\\n  OnStart: () => console.log('api listening'),\\n  OnStop: () => console.log('api drained'),\\n});\\n\\n{\\n  await using app = new IoCContainer().Use(Api);\\n\\n  await app.Start(); // database connected, api listening\\n} // api drained, database closed\"},{\"Path\":\"docs/getting-started/async-services.md\",\"Title\":\"Step 3: Async Services › Register an async factory\",\"About\":\"\",\"Code\":\"import { IoCContainer } from '@fathym/ioc';\\n\\nclass NotesStore {\\n  constructor(private kv: Deno.Kv) {}\\n\\n  public async add(text: string): Promise<void> {\\n    await this.kv.set(['notes', crypto.randomUUID()], text);\\n  }\\n\\n  public async list(): Promise<string[]> {\\n    const notes: string[] = [];\\n\\n    for await (const entry of this.kv.list<string>({ prefix: ['notes'] })) {\\n      notes.push(entry.value);\\n    }\\n\\n    return notes;\\n  }\\n}\\n\\nawait using ioc = new IoCContainer() // disposed (KV closed) at the end of the program\\n  .Typed()\\n  // Deno.Kv is a class, so it works as a key. The factory is async; that's fine.\\n  .RegisterFactory(Deno.Kv, () => Deno.openKv(':memory:'))\\n  .RegisterClass(NotesStore, { Deps: [Deno.Kv] });\\n\\nawait ioc.Start(); // checks the wiring; builds nothing\\nawait ioc.Activate(); // opens KV now, so a bad connection fails at startup\\n\\nconst store = await ioc.Resolve(NotesStore);\\n\\nawait store.add('Buy milk');\\n\\nconsole.log(await store.list()); // [ \\\"Buy milk\\\" ]\"},{\"Path\":\"docs/getting-started/first-container.md\",\"Title\":\"Step 2: Your First Container › Register and resolve\",\"About\":\"\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\n// A typed token: a key that carries the type of what's registered under it.\\nconst $AppName = IoCToken<string, 'AppName'>('AppName');\\n\\nclass Clock {\\n  public now(): Date {\\n    return new Date();\\n  }\\n}\\n\\nclass NotesService {\\n  readonly #notes: string[] = [];\\n\\n  constructor(private clock: Clock) {}\\n\\n  public add(text: string): string {\\n    const note = `${this.clock.now().toISOString()} ${text}`;\\n    this.#notes.push(note);\\n    return note;\\n  }\\n\\n  public list(): string[] {\\n    return [...this.#notes];\\n  }\\n}\\n\\nconst ioc = new IoCContainer();\\n\\nioc.RegisterValue($AppName, 'Notes'); // 1. a value you already have\\nioc.RegisterClass(Clock); // 2. a class the container constructs\\nioc.RegisterFactory(NotesService, async (c) => new NotesService(await c.Resolve(Clock))); // 3. a factory\\n\\nconst notes = await ioc.Resolve(NotesService);\\n\\nnotes.add('Buy milk');\\n\\nconsole.log(await ioc.Resolve($AppName), notes.list());\\n// Notes [ \\\"2026-10-13T12:00:00.000Z Buy milk\\\" ]\"},{\"Path\":\"docs/getting-started/first-container.md\",\"Title\":\"Step 2: Your First Container › Let the container call the constructor\",\"About\":\"Writing a factory just to pass dependencies along gets repetitive. Declare the dependencies\\ninstead, and the container checks them against the constructor's parameters at compile time:\",\"Code\":\"import { IoCContainer } from '@fathym/ioc';\\n\\nclass Clock {\\n  public now(): Date {\\n    return new Date();\\n  }\\n}\\n\\nclass NotesService {\\n  constructor(public clock: Clock) {}\\n}\\n\\nconst ioc = new IoCContainer();\\n\\nioc.RegisterClass(Clock);\\nioc.RegisterClass(NotesService, { Deps: [Clock] }); // a type error if NotesService's constructor changes\\n\\nconst notes = await ioc.Resolve(NotesService);\\n\\nconsole.log(notes.clock instanceof Clock); // true\"},{\"Path\":\"docs/getting-started/first-container.md\",\"Title\":\"Step 2: Your First Container › Catch missing registrations at compile time\",\"About\":\"`Deps` checks types, but on its own it can't tell whether `Clock` was registered at all. Make the\\ncontainer **typed** and chain the registrations. Then `Deps` may only name what's registered\\nabove it:\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $AppName = IoCToken<string, 'AppName'>('AppName');\\n\\nclass Clock {\\n  public now(): Date {\\n    return new Date();\\n  }\\n}\\n\\nclass NotesService {\\n  constructor(public clock: Clock, public appName: string) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  .Typed()\\n  .RegisterValue($AppName, 'Notes')\\n  .RegisterClass(Clock)\\n  .RegisterClass(NotesService, { Deps: [Clock, $AppName] });\\n\\nconst notes = await ioc.Resolve(NotesService);\\n\\nconsole.log(notes.appName); // Notes\"},{\"Path\":\"docs/getting-started/first-container.md\",\"Title\":\"Step 2: Your First Container › Same instance, or a new one?\",\"About\":\"By default every service is a **singleton**: built once and shared. Ask for a **transient**\\nlifetime when you want a fresh instance on every resolve:\",\"Code\":\"import { IoCContainer } from '@fathym/ioc';\\n\\nclass Draft {\\n  public text = '';\\n}\\n\\nclass Clock {}\\n\\nconst ioc = new IoCContainer();\\n\\nioc.RegisterClass(Clock); // singleton (the default)\\nioc.RegisterClass(Draft, { Lifetime: 'transient' });\\n\\nconsole.log((await ioc.Resolve(Clock)) === (await ioc.Resolve(Clock))); // true\\nconsole.log((await ioc.Resolve(Draft)) === (await ioc.Resolve(Draft))); // false\"},{\"Path\":\"docs/getting-started/installation.md\",\"Title\":\"Step 1: Installation › Check it works\",\"About\":\"Create `main.ts`:\",\"Code\":\"import { IoCContainer } from '@fathym/ioc';\\n\\nclass Greeter {\\n  public greet(name: string): string {\\n    return `Hello, ${name}!`;\\n  }\\n}\\n\\nconst ioc = new IoCContainer();\\n\\nioc.RegisterClass(Greeter);\\n\\nconst greeter = await ioc.Resolve(Greeter);\\n\\nconsole.log(greeter.greet('IoC'));\"},{\"Path\":\"docs/getting-started/per-request-scopes.md\",\"Title\":\"Step 4: Per-Request Scopes › Create a scope per request\",\"About\":\"\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Request = IoCToken<Request, 'Request'>('Request');\\n\\nclass RequestContext {\\n  public readonly id = crypto.randomUUID();\\n}\\n\\nclass NotesHandler {\\n  constructor(private ctx: RequestContext, private req: Request) {}\\n\\n  public handle(): Response {\\n    return Response.json({ requestId: this.ctx.id, path: new URL(this.req.url).pathname });\\n  }\\n}\\n\\nconst ioc = new IoCContainer()\\n  .Typed()\\n  .Expect($Request) // registered on each request's scope, below\\n  .RegisterClass(RequestContext, { Lifetime: 'scoped' })\\n  .RegisterClass(NotesHandler, { Deps: [RequestContext, $Request], Lifetime: 'transient' });\\n\\nconst server = Deno.serve({ port: 0, onListen() {} }, async (req) => {\\n  await using scope = ioc.CreateScope(); // disposed when the handler returns\\n\\n  scope.RegisterValue($Request, req); // this request only\\n\\n  return (await scope.Resolve(NotesHandler)).handle();\\n});\\n\\nconst res = await fetch(`http://localhost:${server.addr.port}/notes`);\\n\\nconsole.log(await res.json()); // { requestId: \\\"…\\\", path: \\\"/notes\\\" }\\n\\nawait server.shutdown();\"},{\"Path\":\"docs/getting-started/testing-your-app.md\",\"Title\":\"Step 5: Testing Your App › Put the wiring in a module\",\"About\":\"A module is a named set of registrations, with optional `OnStart` and `OnStop` hooks. Its\\n`Register`, `OnStart` and `OnStop` each receive the container. `main.ts` and the tests both add\\nthe same module with `Use()`:\",\"Code\":\"import { DefineModule, IoCContainer } from '@fathym/ioc';\\n\\nclass NotesService {\\n  public list(): string[] {\\n    return [];\\n  }\\n}\\n\\n// notes-app.ts: the app's real wiring.\\nconst NotesApp = DefineModule({\\n  Name: 'NotesApp',\\n  Register: (ioc) => ioc.RegisterClass(NotesService),\\n  OnStart: () => console.log('notes ready'),\\n  OnStop: () => console.log('notes stopped'),\\n});\\n\\n// main.ts\\nawait using ioc = new IoCContainer().Use(NotesApp);\\n\\nawait ioc.Start(); // validates the wiring, then runs OnStart: notes ready\\n\\nconsole.log((await ioc.Resolve(NotesService)).list()); // []\\n\\n// At the end of the program, `await using` disposes the container: notes stopped\"},{\"Path\":\"docs/getting-started/testing-your-app.md\",\"Title\":\"Step 5: Testing Your App › Override a dependency in a test\",\"About\":\"\",\"Code\":\"import { assertEquals } from 'jsr:@std/assert@1.0.16';\\nimport { DefineModule, IoCContainer } from '@fathym/ioc';\\n\\n// The abstract class is the key; the app and the test provide different implementations.\\nabstract class NotesStore {\\n  public abstract add(text: string): Promise<void>;\\n  public abstract list(): Promise<string[]>;\\n}\\n\\nclass KvNotesStore extends NotesStore {\\n  constructor(private kv: Deno.Kv) {\\n    super();\\n  }\\n\\n  public async add(text: string) {\\n    await this.kv.set(['notes', crypto.randomUUID()], text);\\n  }\\n\\n  public async list() {\\n    const notes: string[] = [];\\n    for await (const e of this.kv.list<string>({ prefix: ['notes'] })) notes.push(e.value);\\n    return notes;\\n  }\\n}\\n\\nclass NotesService {\\n  constructor(private store: NotesStore) {}\\n\\n  public async addNote(text: string): Promise<string[]> {\\n    await this.store.add(text.trim());\\n    return await this.store.list();\\n  }\\n}\\n\\n// The app's real wiring, shared by main.ts and the tests.\\nconst NotesApp = DefineModule({\\n  Name: 'NotesApp',\\n  Register: (ioc) =>\\n    ioc\\n      .RegisterFactory(Deno.Kv, () => Deno.openKv(':memory:'))\\n      .RegisterFactory(NotesStore, (_ioc, kv) => new KvNotesStore(kv), { Deps: [Deno.Kv] })\\n      .RegisterClass(NotesService, { Deps: [NotesStore] }),\\n});\\n\\nDeno.test('the real wiring is valid', () => {\\n  new IoCContainer().Use(NotesApp).Validate(); // throws IoCValidationError if anything is missing\\n});\\n\\nDeno.test('NotesService trims notes before saving', async () => {\\n  await using ioc = new IoCContainer().Use(NotesApp);\\n\\n  const saved: string[] = [];\\n\\n  ioc.Override(NotesStore, {\\n    add: (text) => Promise.resolve(void saved.push(text)),\\n    list: () => Promise.resolve(saved),\\n  });\\n\\n  const service = await ioc.Resolve(NotesService);\\n\\n  assertEquals(await service.addNote('  Buy milk  '), ['Buy milk']);\\n});\"},{\"Path\":\"docs/guides/registering-many-modules.md\",\"Title\":\"Registering many modules › A barrel file\",\"About\":\"The app then adds them all at once. `Use()` also adds each module's `Requires` for you, and\\n`Start()` starts them in dependency order, so the order in the list doesn't matter:\",\"Code\":\"import { DefineModule, IoCContainer, IoCToken } from '@fathym/ioc';\\n\\ninterface Db {\\n  query(sql: string): Promise<string[]>;\\n}\\n\\nconst $Db = IoCToken<Db, 'app/Db'>('app/Db');\\n\\n// These three would live in modules/database.ts, modules/mailer.ts and modules/api.ts.\\nconst Database = DefineModule({\\n  Name: 'Database',\\n  Register: (ioc) => ioc.RegisterValue($Db, { query: async () => ['ada'] }),\\n  OnStart: () => console.log('database connected'),\\n});\\n\\nconst Mailer = DefineModule({\\n  Name: 'Mailer',\\n  Register: (ioc) => ioc,\\n  OnStart: () => console.log('mailer ready'),\\n});\\n\\nconst Api = DefineModule({\\n  Name: 'Api',\\n  Requires: [Database],\\n  Register: (ioc) => ioc,\\n  OnStart: () => console.log('api listening'),\\n});\\n\\n// modules/mod.ts\\nconst AppModules = [Api, Mailer, Database] as const;\\n\\n// main.ts\\nawait using app = new IoCContainer().Use(...AppModules);\\n\\nawait app.Start(); // database connected, api listening, mailer ready\\n\\nconsole.log(await (await app.Resolve($Db)).query('select name from users')); // ['ada']\"},{\"Path\":\"docs/migration/from-0.x.md\",\"Title\":\"Migrating from 0.x to 1.0 › Old call → new call\",\"About\":\"A typical composition root, after the change:\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\ninterface Db {\\n  url: string;\\n}\\n\\nexport const $Db = IoCToken<Db, 'Db'>('Db'); // was: ioc.Symbol('Db')\\n\\nclass Clock {\\n  public now = () => Date.now();\\n}\\n\\nclass Notes {\\n  constructor(public db: Db, public clock: Clock) {}\\n}\\n\\nconst ioc = new IoCContainer() // was: IoCContainer.Create() or { Strict: true }\\n  .RegisterClass(Clock) // was: ioc.Register(Clock)\\n  .RegisterFactory($Db, () => ({ url: 'kv://local' })) // was: ioc.Register($Db, …)\\n  .RegisterClass(Notes, { Deps: [$Db, Clock] });\\n\\nioc.Validate(); // the wiring is sound\\nawait ioc.Activate(); // build every singleton now (0.0.x did this by default)\\n\\nconsole.log((await ioc.Resolve(Notes)).db.url); // kv://local\\n\\nawait ioc.Dispose();\"},{\"Path\":\"docs/migration/from-0.x.md\",\"Title\":\"Migrating from 0.x to 1.0 › Behavior changes › Registering twice throws\",\"About\":\"**1.0:** it throws `IoCDuplicateRegistrationError` unless it says `Replace: true`, or the first\\nwas registered with `Default: true`. Frameworks register their replaceable services with\\n`Default: true`, and the application registers its own without any flag, before or after. The\\nexact rules are under [defaults](../reference/api.md#defaults).\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Greeting = IoCToken<string, 'Greeting'>('Greeting');\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Greeting, 'hello from the framework', { Default: true })\\n  .RegisterValue($Greeting, 'hello from the app'); // the default yields\\n\\nconsole.log(await ioc.Resolve($Greeting)); // hello from the app\"},{\"Path\":\"docs/migration/from-0.x.md\",\"Title\":\"Migrating from 0.x to 1.0 › Behavior changes › Modules instead of CopyTo\",\"About\":\"`CopyTo` copied one container's registrations into another. In 1.0 a package exports a module,\\nand the host adds it with `Use()`. A module lists the modules it builds on in `Requires`; they are\\nadded first, once. `Start()` runs each module's `OnStart` in that order; if one fails, the\\nstarted modules are stopped again and `Start()` can be retried. `Dispose()` runs `OnStop` in\\nreverse.\",\"Code\":\"import { IoCContainer, type IoCModule, IoCToken } from '@fathym/ioc';\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\n\\n// Was: a plugin container, copied into the host with CopyTo.\\nexport const PluginModule: IoCModule = {\\n  Name: 'Plugin',\\n  Register: (ioc) => ioc.RegisterValue($Url, 'kv://plugin', { Default: true }),\\n  OnStart: () => console.log('plugin started'),\\n};\\n\\nawait using host = new IoCContainer().Use(PluginModule);\\n\\nawait host.Start(); // plugin started\\n\\nconsole.log(await host.Resolve($Url)); // kv://plugin\"},{\"Path\":\"docs/migration/from-0.x.md\",\"Title\":\"Migrating from 0.x to 1.0 › Behavior changes › Decorate, IoCLazy, IoCAll\",\"About\":\"0.1 had three dependency helpers that 1.0 leaves out. Each has a short replacement:\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\ninterface Mailer {\\n  send(to: string): string;\\n}\\n\\nconst $Mailer = IoCToken<Mailer, 'Mailer'>('Mailer');\\nconst $Handler = IoCToken<(path: string) => string, 'Handler'>('Handler');\\n\\nclass Signup {\\n  constructor(private mailer: () => Promise<Mailer>) {}\\n\\n  async welcome(to: string) {\\n    return (await this.mailer()).send(to);\\n  }\\n}\\n\\nclass Router {\\n  constructor(public handlers: ((path: string) => string)[]) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  // Decorate: register the inner service under a name, and wrap it as the default.\\n  .RegisterValue($Mailer, { send: (to) => `sent to ${to}` }, { Name: 'inner' })\\n  .RegisterFactory($Mailer, async (c) => {\\n    const inner = await c.Resolve($Mailer, 'inner');\\n\\n    return { send: (to) => inner.send(to).toUpperCase() };\\n  })\\n  // IoCLazy: keep the factory's ioc and resolve later.\\n  .RegisterFactory(Signup, (c) => new Signup(() => c.Resolve($Mailer)))\\n  // IoCAll: resolve every named registration in the factory.\\n  .RegisterValue($Handler, (p) => `api:${p}`, { Name: 'api' })\\n  .RegisterFactory(Router, async (c) => new Router(await c.ResolveAll($Handler)));\\n\\nconsole.log(await (await ioc.Resolve(Signup)).welcome('ada')); // SENT TO ADA\\nconsole.log((await ioc.Resolve(Router)).handlers.length); // 1\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Creating a container › new IoCContainer(options?)\",\"About\":\"**Throws:** [`IoCRegistrationError`](./errors.md#pendingtimeoutms-must-be-a-number-of-milliseconds-from-0-off-to-2147483647-about-248-days)\\nwhen `PendingTimeoutMs` is negative, above 2147483647, or not a number.\",\"Code\":\"import { IoCContainer } from '@fathym/ioc';\\n\\nconst ioc = new IoCContainer({ PendingTimeoutMs: 10_000 });\\n\\nconsole.log(ioc.State); // idle\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Creating a container › State\",\"About\":\"A scope has its own state: the parent's `Start()` doesn't start it.\",\"Code\":\"import { IoCContainer } from '@fathym/ioc';\\n\\nconst ioc = new IoCContainer();\\n\\nawait ioc.Start();\\nconsole.log(ioc.State); // started\\n\\nawait ioc.Dispose();\\nconsole.log(ioc.State); // disposed\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Registration › Keys and IoCToken(name)\",\"About\":\"The optional second type argument keeps the name in the token's type. A\\n[typed container](#typed) needs it to tell apart two tokens of the same service type, such as two\\n`string` settings.\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $DbUrl = IoCToken<string, 'eac/DbUrl'>('eac/DbUrl');\\n\\nconsole.log($DbUrl === Symbol.for('eac/DbUrl')); // true\\n\\nconst ioc = new IoCContainer().RegisterValue($DbUrl, 'kv://local');\\n\\nconsole.log(await ioc.Resolve($DbUrl)); // kv://local\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Registration › RegisterClass(class, options?)\",\"About\":\"**Throws:** [`RegisterClass expects a class`](./errors.md#registerclass-expects-a-class) for\\nanything that isn't a class.\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\ninterface Db {\\n  url: string;\\n}\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\nconst $Db = IoCToken<Db, 'Db'>('Db');\\n\\nclass KvDb implements Db {\\n  constructor(public url: string) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Url, 'kv://local')\\n  .RegisterClass(KvDb, { Deps: [$Url], Type: $Db });\\n\\nconsole.log((await ioc.Resolve($Db)).url); // kv://local\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Registration › RegisterFactory(key, factory, options?)\",\"About\":\"**Throws:** [`RegisterFactory expects a factory function.`](./errors.md#registerfactory-expects-a-factory-function)\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Host = IoCToken<string, 'Host'>('Host');\\nconst $Endpoint = IoCToken<string, 'Endpoint'>('Endpoint');\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Host, 'localhost')\\n  .RegisterFactory($Endpoint, (_ioc, host) => `${host}:8080`, { Deps: [$Host] });\\n\\nconsole.log(await ioc.Resolve($Endpoint)); // localhost:8080\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Registration › RegisterValue(key, value, options?)\",\"About\":\"- **Functions are stored, never called.**\\n- **A promise (or thenable) is stored as it is,** but `Resolve` awaits it, so you get its result.\\n- **The container never disposes a value** unless you pass `Dispose`, which tells it how. The\\n  value belongs to the code that created it.\\n- **A value has no lifetime option;** it acts as a singleton and can't be [isolated](#isolatekeys).\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Handler = IoCToken<(path: string) => string, 'Handler'>('Handler');\\n\\nconst ioc = new IoCContainer().RegisterValue($Handler, (path) => `handled ${path}`);\\n\\nconsole.log((await ioc.Resolve($Handler))('/notes')); // handled /notes\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Registration › Registration options\",\"About\":\"- If a non-default registration of the key and name already exists, here or in a parent, the\\n  `Default` call does nothing. A parent registration made later also wins over a scope's\\n  default.\\n- Any later registration replaces a default without `Replace: true`; a later `Default` replaces an\\n  earlier one.\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Greeting = IoCToken<string, 'Greeting'>('Greeting');\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Greeting, 'hello', { Default: true }) // a framework default\\n  .RegisterValue($Greeting, 'hi'); // the application's choice wins, no error\\n\\nconsole.log(await ioc.Resolve($Greeting)); // hi\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Registration › Unregister(key, name?)\",\"About\":\"Removes a registration from this container, not from its parents. Returns `true` when one existed.\\nInstances already built from it are kept, and still disposed with the container.\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Flag = IoCToken<boolean, 'Flag'>('Flag');\\n\\nconst ioc = new IoCContainer().RegisterValue($Flag, true);\\n\\nconsole.log(ioc.Unregister($Flag)); // true\\nconsole.log(ioc.Has($Flag)); // false\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Typed containers › Typed()\",\"About\":\"TypeScript compares classes by shape, so an unregistered class with the same members as a\\nregistered one passes the check; a class with a private field doesn't. `Validate()` catches it.\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\n\\nclass Repo {\\n  constructor(public url: string) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  .Typed()\\n  .RegisterValue($Url, 'kv://local')\\n  .RegisterClass(Repo, { Deps: [$Url] }); // Deps: [$Url] before RegisterValue would not compile\\n\\nconsole.log((await ioc.Resolve(Repo)).url); // kv://local\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Typed containers › Expect(...keys)\",\"About\":\"Declares keys that are registered later or elsewhere (on each request scope, or by the code that\\nhosts the container), so `Deps` may name them now. Nothing is registered. `Validate()` treats\\nexpected keys as registered. Resolving one that was never registered throws\\n`IoCServiceNotFoundError` with a hint that it was expected.\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $UserId = IoCToken<string, 'UserId'>('UserId');\\n\\nclass Greeter {\\n  constructor(public userId: string) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  .Typed()\\n  .Expect($UserId) // registered on each request scope\\n  .RegisterClass(Greeter, { Deps: [$UserId], Lifetime: 'scoped' });\\n\\nawait using scope = ioc.CreateScope().RegisterValue($UserId, 'ada');\\n\\nconsole.log((await scope.Resolve(Greeter)).userId); // ada\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Resolution › Resolve(key, name?)\",\"About\":\"**Throws:** [`IoCServiceNotFoundError`](./errors.md#no-service-is-registered-for-),\\n[`IoCScopeRequiredError`](./errors.md#scoped-service--was-resolved-outside-a-scope),\\n[`IoCCircularDependencyError`](./errors.md#circular-dependency-detected-),\\n[`IoCResolveTimeoutError`](./errors.md#-did-not-finish-within-ms),\\n[`IoCContainerDisposedError`](./errors.md#the-ioc-container-has-been-disposed), or whatever the\\nfactory or constructor throws.\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Db = IoCToken<{ url: string }, 'Db'>('Db');\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Db, { url: 'kv://primary' })\\n  .RegisterValue($Db, { url: 'kv://replica' }, { Name: 'replica' });\\n\\nconsole.log((await ioc.Resolve($Db, 'replica')).url); // kv://replica\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Resolution › TryResolve(key, name?)\",\"About\":\"Like `Resolve`, but returns `undefined` when nothing is registered for the key and name. If a\\nregistration exists and building it fails, the error is still thrown.\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Cache = IoCToken<Map<string, string>, 'Cache'>('Cache');\\n\\nconst cache = await new IoCContainer().TryResolve($Cache);\\n\\nconsole.log(cache); // undefined\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Resolution › ResolveAll(key)\",\"About\":\"Resolves every registration of a key, one per name, in the order of [`Names`](#nameskey): this\\ncontainer's names first, then names only a parent has. Returns `[]` when there are none.\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Plugin = IoCToken<string, 'Plugin'>('Plugin');\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Plugin, 'auth', { Name: 'auth' })\\n  .RegisterValue($Plugin, 'metrics', { Name: 'metrics' });\\n\\nconsole.log(await ioc.ResolveAll($Plugin)); // [ \\\"auth\\\", \\\"metrics\\\" ]\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Resolution › ResolveNamed(key)\",\"About\":\"Like `ResolveAll`, but returns a `Map` from name to service.\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Plugin = IoCToken<string, 'Plugin'>('Plugin');\\n\\nconst ioc = new IoCContainer().RegisterValue($Plugin, 'auth', { Name: 'auth' });\\n\\nconsole.log((await ioc.ResolveNamed($Plugin)).get('auth')); // auth\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Resolution › ResolveRecord(record)\",\"About\":\"Resolves several services at once into an object with the same keys. Each value is a key or\\n`[key, name]`, and each property is typed from it.\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\nconst $Port = IoCToken<number, 'Port'>('Port');\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Url, 'localhost')\\n  .RegisterValue($Port, 8080, { Name: 'http' });\\n\\nconst { url, port } = await ioc.ResolveRecord({ url: $Url, port: [$Port, 'http'] });\\n\\nconsole.log(`${url}:${port}`); // localhost:8080\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Resolution › Has(key, name?)\",\"About\":\"`true` when a registration of the key and name exists here or in a parent. Synchronous; it builds\\nnothing.\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Db = IoCToken<string, 'Db'>('Db');\\n\\nconst ioc = new IoCContainer().RegisterValue($Db, 'kv', { Name: 'replica' });\\n\\nconsole.log(ioc.Names($Db)); // [ \\\"replica\\\" ]\\nconsole.log(ioc.Has($Db), ioc.Has($Db, 'replica')); // false true\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Scopes › CreateScope()\",\"About\":\"- The scope resolves everything its parent can. Singletons stay shared with the parent.\\n- `scoped` registrations get one instance per scope, built in and disposed with that scope.\\n- Registrations made on the scope override the parent's, for this scope only. Services the scope\\n  builds (scoped and transient ones) see those overrides; a parent's singleton doesn't, since the\\n  parent builds it. [`Isolate`](#isolatekeys) gives the scope its own copy of a singleton that\\n  does. A `Default` on a scope yields to a parent's non-default registration.\\n- A scope skips modules its parent already has, and has its own `Start()` and `State`.\\n- Dispose it when done (`await using scope = ioc.CreateScope()`). Disposing the parent disposes its\\n  live scopes too, and a scope can't be used once its parent is disposed.\",\"Code\":\"import { IoCContainer } from '@fathym/ioc';\\n\\nclass RequestId {\\n  public id = crypto.randomUUID();\\n}\\n\\nconst ioc = new IoCContainer().RegisterClass(RequestId, { Lifetime: 'scoped' });\\n\\nawait using a = ioc.CreateScope();\\nawait using b = ioc.CreateScope();\\n\\nconsole.log((await a.Resolve(RequestId)) === (await a.Resolve(RequestId))); // true\\nconsole.log((await a.Resolve(RequestId)) === (await b.Resolve(RequestId))); // false\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Scopes › Isolate(...keys)\",\"About\":\"**Throws:** [`Isolate() works on scopes`](./errors.md#isolate-works-on-scopes-call-it-on-a-container-created-with-createscope)\\non a root container, [`IoCNotIsolatableError`](./errors.md#-cant-be-isolated-) for a value (every\\nscope shares values as they are), and `IoCServiceNotFoundError` for a key nobody registered.\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Tenant = IoCToken<string, 'Tenant'>('Tenant');\\n\\nclass Greeter {\\n  constructor(public tenant: string) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Tenant, 'default')\\n  .RegisterClass(Greeter, { Deps: [$Tenant] });\\n\\nawait using scope = ioc.CreateScope()\\n  .RegisterValue($Tenant, 'acme')\\n  .Isolate(Greeter);\\n\\nconsole.log((await scope.Resolve(Greeter)).tenant); // acme\\nconsole.log((await ioc.Resolve(Greeter)).tenant); // default\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Modules › Use(...modules)\",\"About\":\"**Throws:** [`IoCModuleCycleError`](./errors.md#module-dependency-cycle-) when modules require each\\nother in a loop, and\\n[`A module needs a Name and a Register(ioc) function.`](./errors.md#a-module-needs-a-name-and-a-registerioc-function)\",\"Code\":\"import { IoCContainer, type IoCModule, IoCToken } from '@fathym/ioc';\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\n\\nconst Config: IoCModule = {\\n  Name: 'Config',\\n  Register: (ioc) => ioc.RegisterValue($Url, 'kv://local', { Default: true }),\\n};\\n\\nconst Data: IoCModule = {\\n  Name: 'Data',\\n  Requires: [Config],\\n  Register: () => {},\\n  OnStart: async (ioc) => console.log(`connecting to ${await ioc.Resolve($Url)}`),\\n};\\n\\nawait using ioc = new IoCContainer().Use(Data); // adds Config, then Data\\n\\nawait ioc.Start(); // connecting to kv://local\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Modules › DefineModule(definition)\",\"About\":\"A module's provided keys don't include those of the modules it requires. To depend on a module\\nfurther down, require it too, or list its keys in `Needs`.\",\"Code\":\"import { DefineModule, IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\n\\nclass Repo {\\n  constructor(public url: string) {}\\n}\\n\\nconst RepoModule = DefineModule({\\n  Name: 'Repo',\\n  Needs: [$Url],\\n  Register: (ioc) => ioc.RegisterClass(Repo, { Deps: [$Url] }),\\n});\\n\\nconst ioc = new IoCContainer()\\n  .Typed()\\n  .RegisterValue($Url, 'kv://local')\\n  .Use(RepoModule); // compiles: $Url is registered; Repo is now in the type\\n\\nconsole.log((await ioc.Resolve(Repo)).url); // kv://local\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Lifecycle › Start(options?)\",\"About\":\"- **It doesn't build services.** They are still built when first resolved; call\\n  [`Activate()`](#activate) to build every singleton at boot.\\n- Concurrent calls share one start; calling it on a started container does nothing.\\n- A scope's `Start()` runs the scope's own modules. Its parent must be started first when those\\n  modules require the parent's.\\n- On a disposed container it throws `IoCContainerDisposedError`.\",\"Code\":\"import { IoCContainer, IoCStartError } from '@fathym/ioc';\\n\\nlet attempts = 0;\\n\\nconst ioc = new IoCContainer().Use({\\n  Name: 'Db',\\n  Register: () => {},\\n  OnStart: () => {\\n    if (++attempts === 1) throw new Error('connection refused');\\n  },\\n});\\n\\ntry {\\n  await ioc.Start();\\n} catch (err) {\\n  console.log((err as IoCStartError).message); // Module 'Db' failed to start: connection refused\\n}\\n\\nconsole.log(ioc.State); // idle\\n\\nawait ioc.Start(); // the retry succeeds\\n\\nconsole.log(ioc.State); // started\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Lifecycle › Activate()\",\"About\":\"Builds every singleton registered on this container now (not its parents' singletons, and not\\nscoped or transient services), so a broken service fails at boot rather than on first use. All\\nbuilds run, then one [`IoCActivationError`](./errors.md#ioc-activation-failed-for-) names every\\nservice that failed; its `errors` holds the causes, in the order of `Services`.\",\"Code\":\"import { IoCActivationError, IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Db = IoCToken<string, 'Db'>('Db');\\n\\nconst ioc = new IoCContainer().RegisterFactory($Db, () => {\\n  throw new Error('no connection string');\\n});\\n\\nawait ioc.Start();\\n\\ntry {\\n  await ioc.Activate();\\n} catch (err) {\\n  console.log((err as IoCActivationError).Services); // [ \\\"Db\\\" ]\\n}\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Lifecycle › Dispose()\",\"About\":\"Every step runs even if an earlier one fails. The failures are thrown together as one\\n[`IoCDisposeError`](./errors.md#errors-occurred-while-disposing-the-ioc-container) (an\\n`AggregateError`). Calling it again returns the same promise. Afterwards, resolving, registering,\\n`Use()`, `CreateScope()`, `Start()` and `Activate()` throw `IoCContainerDisposedError`; inspection\\n(`Has`, `Names`, `Describe`, `Validate`) still works.\",\"Code\":\"import { IoCContainer } from '@fathym/ioc';\\n\\nclass Pool {\\n  async [Symbol.asyncDispose]() {\\n    console.log('pool closed');\\n  }\\n}\\n\\n{\\n  await using ioc = new IoCContainer().RegisterClass(Pool);\\n\\n  await ioc.Resolve(Pool);\\n} // pool closed\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Lifecycle › What gets disposed\",\"About\":\"- **Singletons and scoped instances** the container built, when they have `Symbol.asyncDispose` or\\n  `Symbol.dispose`, or a `Dispose` option. A singleton is disposed by the container that holds its\\n  registration; a scoped instance by its scope.\\n- **Not transient instances.** The container doesn't track them; whoever resolved one owns it.\\n- **Not values** from `RegisterValue`, unless registered with a `Dispose` option.\\n- **Each instance once,** by the container that built it, even when it is also registered\\n  elsewhere.\\n- Each disposer is bounded by `PendingTimeoutMs`.\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\ninterface Kv {\\n  close(): void;\\n}\\n\\nconst $Kv = IoCToken<Kv, 'Kv'>('Kv');\\n\\nconst ioc = new IoCContainer().RegisterFactory(\\n  $Kv,\\n  () => ({ close: () => console.log('kv closed') }),\\n  { Dispose: (kv) => kv.close() },\\n);\\n\\nawait ioc.Resolve($Kv);\\n\\nawait ioc.Dispose(); // kv closed\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Inspection › Validate(options?)\",\"About\":\"Only declared `Deps` are checked: what a factory resolves in its body is only known when it runs.\\nEach issue is `{ Kind, Service, Message, Hint }`; `Hint` says what to change, and the thrown\\nerror's message shows it as a `Fix:` line under each problem.\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\n\\nclass Repo {\\n  constructor(public url: string) {}\\n}\\n\\nconst ioc = new IoCContainer().RegisterClass(Repo, { Deps: [$Url] });\\n\\nconsole.log(ioc.Validate({ Throw: false }).map((i) => i.Message));\\n// [ \\\"Repo depends on Url, which is not registered.\\\" ]\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Inspection › Describe()\",\"About\":\"Each service is `{ Key, Name, Label, Kind, Lifetime, Default, Deps, Depth }`: `Kind` is `class`,\\n`factory` or `value`; `Label` is `Key` or `Key[name]`, as in error messages; `Deps` are labels;\\n`Depth` is 0 for this container, 1 for its parent, and so on.\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\n\\nclass Repo {\\n  constructor(public url: string) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Url, 'kv://local')\\n  .RegisterClass(Repo, { Deps: [$Url] });\\n\\nconst repo = ioc.Describe().Services.find((s) => s.Key === 'Repo');\\n\\nconsole.log(repo?.Kind, repo?.Lifetime, repo?.Deps); // class singleton [ \\\"Url\\\" ]\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Testing › Override(key, value, options?)\",\"About\":\"- Instances already built from the old registration keep what they were given. Override before\\n  resolving the services that use it, or override in a fresh scope.\\n- If something replaced the override in the meantime, restoring leaves that alone.\",\"Code\":\"import { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Clock = IoCToken<() => number, 'Clock'>('Clock');\\n\\nconst ioc = new IoCContainer().RegisterValue($Clock, () => Date.now());\\n\\nconst restore = ioc.Override($Clock, () => 0);\\n\\nconsole.log((await ioc.Resolve($Clock))()); // 0\\n\\nrestore();\\n\\nconsole.log((await ioc.Resolve($Clock))() > 0); // true\"},{\"Path\":\"docs/reference/api.md\",\"Title\":\"API Reference › Errors\",\"About\":\"Every error class also has `DocsUrl`, the link to its code's section in the\\n[error catalog](./errors.md#error-codes); `ioCErrorDocsUrl(code)` gives the same link for a code.\\nEach message, its causes and its fix are in the [error catalog](./errors.md).\",\"Code\":\"import { IoCContainer, IoCServiceNotFoundError, IoCToken, isIoCError } from '@fathym/ioc';\\n\\nconst $Missing = IoCToken<string, 'Missing'>('Missing');\\n\\ntry {\\n  await new IoCContainer().Resolve($Missing);\\n} catch (err) {\\n  console.log(isIoCError(err, 'IOC_SERVICE_NOT_FOUND')); // true\\n  console.log((err as IoCServiceNotFoundError).Key); // Missing\\n}\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog\",\"About\":\"All error classes are exported from `@fathym/ioc`, and each has a stable `code`. Match on the code\\nrather than the message, which may gain detail. `isIoCError(err, code)` checks the code without\\n`instanceof`, so it also covers `IoCActivationError` and `IoCDisposeError`, which are\\n`AggregateError`s.\",\"Code\":\"import { IoCContainer, IoCToken, isIoCError } from '@fathym/ioc';\\n\\nconst $Missing = IoCToken<string, 'Missing'>('Missing');\\n\\ntry {\\n  await new IoCContainer().Resolve($Missing);\\n} catch (err) {\\n  if (isIoCError(err, 'IOC_SERVICE_NOT_FOUND')) console.log('not registered');\\n}\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Circular dependency detected: …\",\"About\":\"**Fix:** break the loop. Move the shared part into a third service both depend on, or have one\\nside resolve the other later, after construction, from the `ioc` its factory received:\",\"Code\":\"import { IoCContainer } from '@fathym/ioc';\\n\\nclass Billing {\\n  constructor(private orders: () => Promise<Orders>) {}\\n\\n  async total() {\\n    return (await this.orders()).count * 10;\\n  }\\n}\\n\\nclass Orders {\\n  public count = 3;\\n\\n  constructor(public billing: Billing) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  .RegisterFactory(Billing, (c) => new Billing(() => c.Resolve(Orders))) // resolved on first use\\n  .RegisterClass(Orders, { Deps: [Billing] });\\n\\nconsole.log(await (await ioc.Resolve(Orders)).billing.total()); // 30\"},{\"Path\":\"docs/reference/errors.md\",\"Title\":\"Error Catalog › Scoped service … was resolved outside a scope\",\"About\":\"`IoCScopeRequiredError` (`IOC_SCOPE_REQUIRED`). A `scoped` service was resolved from the root\\ncontainer, which has no scope to own it. **Fix:** create a scope and resolve from it:\",\"Code\":\"import { IoCContainer } from '@fathym/ioc';\\n\\nclass Session {}\\n\\nconst ioc = new IoCContainer().RegisterClass(Session, { Lifetime: 'scoped' });\\n\\nawait using scope = ioc.CreateScope();\\n\\nconsole.log((await scope.Resolve(Session)) instanceof Session); // true\"},{\"Path\":\"examples/async-services.ts\",\"Title\":\"Example program: examples/async-services.ts\",\"About\":\"\",\"Code\":\"/**\\n * Async services: a Deno KV opened by an async factory, a flaky remote client that succeeds on retry, startup\\n * activation and disposal.\\n *\\n * Run: deno run --unstable-kv examples/async-services.ts\\n */\\nimport { IoCContainer, IoCToken } from '../mod.ts';\\n\\ninterface RemoteConfig {\\n  featureFlags: string[];\\n}\\n\\nconst $RemoteConfig = IoCToken<RemoteConfig, 'RemoteConfig'>('RemoteConfig');\\n\\nlet configAttempts = 0;\\n\\n/** Pretends to fetch configuration; the first call fails like a service that is still starting. */\\nasync function fetchRemoteConfig(): Promise<RemoteConfig> {\\n  await new Promise((resolve) => setTimeout(resolve, 5));\\n\\n  if (++configAttempts === 1) throw new Error('config service not ready');\\n\\n  return { featureFlags: ['notes-v2'] };\\n}\\n\\nconst ioc = new IoCContainer();\\n\\n// Nothing is built at registration.\\nioc.RegisterFactory(Deno.Kv, () => Deno.openKv(':memory:'));\\nioc.RegisterFactory($RemoteConfig, fetchRemoteConfig);\\n\\n// Activate builds every singleton now and reports all failures together.\\ntry {\\n  await ioc.Activate();\\n} catch (err) {\\n  console.log(`Startup attempt failed: ${(err as AggregateError).message}`);\\n}\\n\\n// Failed creations are not cached, so activating again retries only what failed.\\nawait ioc.Activate();\\n\\nconst [kv, config] = await Promise.all([ioc.Resolve(Deno.Kv), ioc.Resolve($RemoteConfig)]);\\n\\nawait kv.set(['flags'], config.featureFlags);\\n\\nconsole.log('Flags in KV:', (await kv.get<string[]>(['flags'])).value);\\n\\nawait ioc.Dispose(); // closes the KV connection\\n\\nif (configAttempts !== 2) throw new Error(`expected 2 attempts, got ${configAttempts}`);\"},{\"Path\":\"examples/basic.ts\",\"Title\":\"Example program: examples/basic.ts\",\"About\":\"\",\"Code\":\"/**\\n * Basic registration and resolution: a value, classes and declared dependencies.\\n *\\n * Run: deno run examples/basic.ts\\n */\\nimport { IoCContainer, IoCToken } from '../mod.ts';\\n\\nconst $AppName = IoCToken<string, 'AppName'>('AppName');\\n\\nclass Clock {\\n  public now(): Date {\\n    return new Date();\\n  }\\n}\\n\\nclass Greeter {\\n  constructor(private clock: Clock, private appName: string) {}\\n\\n  public greet(name: string): string {\\n    return `[${this.appName} @ ${this.clock.now().toISOString()}] Hello, ${name}!`;\\n  }\\n}\\n\\nconst ioc = new IoCContainer();\\n\\nioc.RegisterValue($AppName, 'Basic example');\\nioc.RegisterClass(Clock);\\nioc.RegisterClass(Greeter, { Deps: [Clock, $AppName] });\\n\\nioc.Validate();\\n\\nconst greeter = await ioc.Resolve(Greeter);\\n\\nconsole.log(greeter.greet('world'));\\n\\nif ((await ioc.Resolve(Greeter)) !== greeter) throw new Error('expected a singleton');\"},{\"Path\":\"examples/modules-lifecycle.ts\",\"Title\":\"Example program: examples/modules-lifecycle.ts\",\"About\":\"\",\"Code\":\"/**\\n * Modules and lifecycle: typed modules with DefineModule, Requires deciding the start order, a\\n * framework default the app replaces, a failed Start() that stops what started and is retried,\\n * and Dispose() stopping the modules in reverse.\\n *\\n * Run: deno run examples/modules-lifecycle.ts\\n */\\nimport { DefineModule, IoCContainer, IoCToken, isIoCError } from '../mod.ts';\\n\\nconst $DbUrl = IoCToken<string, 'example/DbUrl'>('example/DbUrl');\\n\\nconst events: string[] = [];\\n\\nfunction log(event: string): void {\\n  events.push(event);\\n  console.log(`  ${event}`);\\n}\\n\\nclass Db {\\n  public open = false;\\n\\n  constructor(public url: string) {}\\n\\n  [Symbol.asyncDispose](): Promise<void> {\\n    log(`db disposed (${this.url})`);\\n    return Promise.resolve();\\n  }\\n}\\n\\nclass MemoryCache {\\n  public readonly entries = new Map<string, string>();\\n}\\n\\n// A default: the module says \\\"the app may replace this\\\".\\nconst Config = DefineModule({\\n  Name: 'Config',\\n  Register: (ioc) => ioc.RegisterValue($DbUrl, 'postgres://localhost/app', { Default: true }),\\n});\\n\\nconst Database = DefineModule({\\n  Name: 'Database',\\n  Requires: [Config], // added and started before Database\\n  Register: (ioc) => ioc.RegisterClass(Db, { Deps: [$DbUrl] }), // $DbUrl is typed in from Config\\n  OnStart: async (ioc) => {\\n    (await ioc.Resolve(Db)).open = true;\\n    log('database connected');\\n  },\\n  OnStop: async (ioc) => {\\n    (await ioc.Resolve(Db)).open = false;\\n    log('database drained');\\n  },\\n});\\n\\nconst Cache = DefineModule({\\n  Name: 'Cache',\\n  Register: (ioc) => ioc.RegisterClass(MemoryCache),\\n  OnStart: () => log('cache warmed'),\\n  OnStop: () => log('cache flushed'),\\n});\\n\\nlet portFree = false;\\n\\nconst Server = DefineModule({\\n  Name: 'Server',\\n  Requires: [Database, Cache],\\n  Register: () => {},\\n  OnStart: () => {\\n    if (!portFree) throw new Error('port 8080 in use');\\n    log('server listening');\\n  },\\n  OnStop: () => log('server closed'),\\n});\\n\\n{\\n  await using ioc = new IoCContainer()\\n    .Typed()\\n    .Use(Server) // adds Config, Database, Cache, then Server\\n    .RegisterValue($DbUrl, 'postgres://db.internal/app'); // replaces Config's default\\n\\n  console.log(`Start order: ${ioc.Describe().Modules.map((m) => m.Name).join(', ')}`);\\n\\n  console.log('First start:');\\n\\n  try {\\n    await ioc.Start();\\n  } catch (err) {\\n    if (!isIoCError(err, 'IOC_START_FAILED')) throw err;\\n    console.log(`  ${err.message}; state is back to '${ioc.State}'`);\\n  }\\n\\n  portFree = true;\\n\\n  console.log('Second start:');\\n\\n  await ioc.Start();\\n\\n  const db = await ioc.Resolve(Db);\\n\\n  if (db.url !== 'postgres://db.internal/app' || !db.open) throw new Error('unexpected Db');\\n\\n  console.log('Shutdown:');\\n} // `await using` disposes the container here: modules stop in reverse, then instances\\n\\nconst expected = [\\n  // First start: Server fails, so the modules that started are stopped again, in reverse.\\n  'database connected',\\n  'cache warmed',\\n  'cache flushed',\\n  'database drained',\\n  // Second start.\\n  'database connected',\\n  'cache warmed',\\n  'server listening',\\n  // Dispose().\\n  'server closed',\\n  'cache flushed',\\n  'database drained',\\n  'db disposed (postgres://db.internal/app)',\\n];\\n\\nif (events.join('|') !== expected.join('|')) throw new Error(`unexpected order: ${events}`);\"},{\"Path\":\"examples/per-request-server.ts\",\"Title\":\"Example program: examples/per-request-server.ts\",\"About\":\"\",\"Code\":\"/**\\n * A realistic end-to-end app: an HTTP server where every request gets its own scope, request\\n * value and scoped services, with graceful shutdown that disposes the root container.\\n *\\n * Run: deno run -A --unstable-kv examples/per-request-server.ts\\n * (it starts on a random port, sends itself three requests, prints the results and exits)\\n */\\nimport { IoCContainer, IoCToken } from '../mod.ts';\\n\\nconst $Request = IoCToken<Request, 'Request'>('Request');\\n\\nabstract class NotesStore {\\n  public abstract add(text: string): Promise<void>;\\n  public abstract count(): Promise<number>;\\n}\\n\\nclass KvNotesStore extends NotesStore {\\n  constructor(private kv: Deno.Kv) {\\n    super();\\n  }\\n\\n  public async add(text: string): Promise<void> {\\n    await this.kv.set(['notes', crypto.randomUUID()], text);\\n  }\\n\\n  public async count(): Promise<number> {\\n    let n = 0;\\n    for await (const _ of this.kv.list({ prefix: ['notes'] })) n++;\\n    return n;\\n  }\\n}\\n\\n/** One per request: the scope disposes it when the response is done. */\\nclass RequestLog implements Disposable {\\n  public static closed = 0;\\n\\n  public readonly id = crypto.randomUUID().slice(0, 8);\\n\\n  public [Symbol.dispose](): void {\\n    RequestLog.closed++;\\n  }\\n}\\n\\nclass NotesHandler {\\n  constructor(private req: Request, private log: RequestLog, private store: NotesStore) {}\\n\\n  public async handle(): Promise<Response> {\\n    if (this.req.method === 'POST') await this.store.add(await this.req.text());\\n\\n    return Response.json({ request: this.log.id, notes: await this.store.count() });\\n  }\\n}\\n\\n// Composition root.\\nconst ioc = new IoCContainer();\\n\\nioc.RegisterFactory(Deno.Kv, () => Deno.openKv(':memory:'));\\nioc.RegisterFactory(NotesStore, (_ioc, kv) => new KvNotesStore(kv), { Deps: [Deno.Kv] });\\nioc.Expect($Request); // registered on each request's scope, below\\nioc.RegisterClass(RequestLog, { Lifetime: 'scoped' });\\nioc.RegisterClass(NotesHandler, {\\n  Deps: [$Request, RequestLog, NotesStore],\\n  Lifetime: 'transient',\\n});\\n\\nawait ioc.Start(); // validates the wiring\\nawait ioc.Activate(); // opens KV now, so a bad setup fails at startup\\n\\nconst server = Deno.serve({ port: 0, onListen() {} }, async (req) => {\\n  await using scope = ioc.CreateScope();\\n\\n  scope.RegisterValue($Request, req);\\n\\n  return await (await scope.Resolve(NotesHandler)).handle();\\n});\\n\\nconst url = `http://localhost:${server.addr.port}/notes`;\\n\\nfor (const body of ['Buy milk', 'Call Ada']) {\\n  console.log(await (await fetch(url, { method: 'POST', body })).json());\\n}\\n\\nconsole.log(await (await fetch(url)).json());\\n\\nawait server.shutdown();\\nawait ioc.Dispose(); // closes KV\\n\\nif (RequestLog.closed !== 3) {\\n  throw new Error(`expected 3 disposed request logs, got ${RequestLog.closed}`);\\n}\"},{\"Path\":\"examples/plugins.ts\",\"Title\":\"Example program: examples/plugins.ts\",\"About\":\"\",\"Code\":\"/**\\n * Plugins: several named implementations of one key, collected with ResolveAll and picked by\\n * name with TryResolve.\\n *\\n * Run: deno run examples/plugins.ts\\n */\\nimport { IoCContainer, IoCToken } from '../mod.ts';\\n\\ninterface Exporter {\\n  readonly format: string;\\n  export(rows: string[]): string;\\n}\\n\\nconst $Exporter = IoCToken<Exporter, 'Exporter'>('Exporter');\\n\\nconst ioc = new IoCContainer();\\n\\nioc.RegisterValue($Exporter, { format: 'csv', export: (rows) => rows.join(',') }, { Name: 'csv' });\\nioc.RegisterValue($Exporter, { format: 'json', export: (rows) => JSON.stringify(rows) }, {\\n  Name: 'json',\\n});\\nioc.RegisterValue($Exporter, { format: 'lines', export: (rows) => rows.join('\\\\n') }, {\\n  Name: 'lines',\\n});\\n\\nconst all = await ioc.ResolveAll($Exporter);\\n\\nconsole.log('Available formats:', all.map((e) => e.format).join(', '));\\n\\nconst requested = 'json';\\nconst exporter = await ioc.TryResolve($Exporter, requested);\\n\\nif (!exporter) throw new Error(`no exporter for ${requested}`);\\n\\nconsole.log(exporter.export(['a', 'b']));\\n\\nconsole.log('Has xml?', ioc.Has($Exporter, 'xml'));\"},{\"Path\":\"examples/testing-overrides.test.ts\",\"Title\":\"Example program: examples/testing-overrides.test.ts\",\"About\":\"\",\"Code\":\"/**\\n * Testing with overrides: validate the real app module, fake one dependency with `Override()`,\\n * and put the original back with the function `Override()` returns.\\n *\\n * Run: deno test examples/testing-overrides.test.ts\\n */\\nimport { assertEquals, assertRejects } from 'jsr:@std/assert@1.0.16';\\nimport { DefineModule, IoCContainer, IoCToken } from '../mod.ts';\\n\\ninterface Mailer {\\n  send(to: string, subject: string): Promise<void>;\\n}\\n\\nconst $Mailer = IoCToken<Mailer, 'example/Mailer'>('example/Mailer');\\n\\nclass SignupService {\\n  constructor(private mailer: Mailer) {}\\n\\n  public async signUp(email: string): Promise<void> {\\n    await this.mailer.send(email.toLowerCase(), 'Welcome!');\\n  }\\n}\\n\\n/** The production wiring, shared by the app and the tests. */\\nconst App = DefineModule({\\n  Name: 'App',\\n  Register: (ioc) =>\\n    ioc\\n      .RegisterFactory($Mailer, () => ({\\n        send: () => Promise.reject(new Error('no SMTP server in tests')),\\n      }))\\n      .RegisterClass(SignupService, { Deps: [$Mailer], Lifetime: 'transient' }),\\n});\\n\\nDeno.test('the production wiring is valid', () => {\\n  new IoCContainer().Use(App).Validate();\\n});\\n\\nDeno.test('signUp sends a welcome mail to the normalized address', async () => {\\n  await using ioc = new IoCContainer().Use(App);\\n\\n  const sent: string[] = [];\\n\\n  // Override before resolving the services that use it.\\n  ioc.Override($Mailer, {\\n    send: (to, subject) => Promise.resolve(void sent.push(`${to}: ${subject}`)),\\n  });\\n\\n  await (await ioc.Resolve(SignupService)).signUp('Ada@Example.com');\\n\\n  assertEquals(sent, ['ada@example.com: Welcome!']);\\n});\\n\\nDeno.test('the function Override() returns puts the original back', async () => {\\n  await using ioc = new IoCContainer().Use(App); // imagine it shared by several tests\\n\\n  const restore = ioc.Override($Mailer, { send: () => Promise.resolve() });\\n\\n  await (await ioc.Resolve(SignupService)).signUp('ada@example.com'); // the fake: no error\\n\\n  restore();\\n\\n  await assertRejects(\\n    async () => await (await ioc.Resolve(SignupService)).signUp('ada@example.com'),\\n    Error,\\n    'no SMTP server in tests',\\n  );\\n});\"},{\"Path\":\"examples/typed-container.ts\",\"Title\":\"Example program: examples/typed-container.ts\",\"About\":\"\",\"Code\":\"/**\\n * Typed containers: `Typed()` plus chained registrations, so `Deps` may only name what's already\\n * registered. Feature modules made with `DefineModule` state the keys they need, `Use()` checks\\n * them, and a per-request key is declared with `Expect`.\\n *\\n * Run: deno run examples/typed-container.ts\\n */\\nimport { DefineModule, IoCContainer, IoCToken } from '../mod.ts';\\n\\ninterface Db {\\n  query(sql: string): string[];\\n}\\n\\nconst $Db = IoCToken<Db, 'Db'>('Db');\\nconst $Table = IoCToken<string, 'Table'>('Table');\\nconst $Request = IoCToken<Request, 'Request'>('Request');\\n\\nclass NotesRepo {\\n  constructor(public db: Db, public table: string) {}\\n\\n  public list(): string[] {\\n    return this.db.query(`select * from ${this.table}`);\\n  }\\n}\\n\\nclass NotesHandler {\\n  constructor(public repo: NotesRepo, public req: Request) {}\\n\\n  public handle(): string {\\n    return `${new URL(this.req.url).pathname}: ${this.repo.list().join(', ')}`;\\n  }\\n}\\n\\n// data.ts: provides $Db and nothing else.\\nconst Data = DefineModule({\\n  Name: 'Data',\\n  Register: (ioc) => ioc.RegisterValue($Db, { query: (sql) => [`ran \\\"${sql}\\\"`] }),\\n});\\n\\n// notes.ts: needs $Db and $Request from someone else. Inside Register, Deps may name those,\\n// plus what this chain registered above.\\nconst Notes = DefineModule({\\n  Name: 'Notes',\\n  Needs: [$Db, $Request],\\n  Register: (ioc) =>\\n    ioc\\n      .RegisterValue($Table, 'notes')\\n      .RegisterClass(NotesRepo, { Deps: [$Db, $Table] })\\n      .RegisterClass(NotesHandler, { Deps: [NotesRepo, $Request], Lifetime: 'transient' }),\\n});\\n\\n// main.ts: drop `.Use(Data)` or `.Expect($Request)` and the `.Use(Notes)` line won't compile.\\nconst ioc = new IoCContainer()\\n  .Typed()\\n  .Expect($Request) // registered on each request's scope\\n  .Use(Data)\\n  .Use(Notes);\\n\\nioc.Validate();\\n\\nawait using scope = ioc.CreateScope();\\n\\nscope.RegisterValue($Request, new Request('http://localhost/notes'));\\n\\nconst output = (await scope.Resolve(NotesHandler)).handle();\\n\\nconsole.log(output); // /notes: ran \\\"select * from notes\\\"\\n\\nif (output !== '/notes: ran \\\"select * from notes\\\"') throw new Error(`unexpected: ${output}`);\"}],\"Api\":[{\"Name\":\"API Reference\",\"Text\":\"API Reference\\n\\nEverything is exported from `@fathym/ioc`. The generated docs on\\n[JSR](https://jsr.io/@fathym/ioc/doc) come from the same JSDoc and always match a release. This\\npage groups the API by task and adds behavior notes and examples.\\n\\nSignature blocks are declarations, shown for reading (they are marked `ts ignore`). Every other\\ncode block is a complete, runnable example, checked in CI.\\n\\n**Contents:**\\n\\n- **Creating:** [new IoCContainer](#new-ioccontaineroptions), [State](#state)\\n- **Registration:** [keys and IoCToken](#keys-and-ioctokenname),\\n  [RegisterClass](#registerclassclass-options),\\n  [RegisterFactory](#registerfactorykey-factory-options),\\n  [RegisterValue](#registervaluekey-value-options), [options](#registration-options),\\n  [Unregister](#unregisterkey-name)\\n- **Typed containers:** [Typed](#typed), [Expect](#expectkeys)\\n- **Resolution:** [Resolve](#resolvekey-name), [TryResolve](#tryresolvekey-name),\\n  [ResolveAll](#resolveallkey), [ResolveNamed](#resolvenamedkey),\\n  [ResolveRecord](#resolverecordrecord), [Names](#nameskey), [Has](#haskey-name),\\n  [how resolution behaves](#how-resolution-behaves)\\n- **Scopes:** [CreateScope](#createscope), [Isolate](#isolatekeys)\\n- **Modules:** [Use](#usemodules), [IoCModule](#iocmodule),\\n  [DefineModule](#definemoduledefinition)\\n- **Lifecycle:** [Start](#startoptions), [Activate](#activate), [Dispose](#dispose),\\n  [what gets disposed](#what-gets-disposed)\\n- **Inspection:** [Validate](#validateoptions), [Describe](#describe)\\n- **Testing:** [Override](#overridekey-value-options)\\n- **Types:** [keys and dependencies](#key-and-dependency-types),\\n  [registry types](#registry-types), [module types](#module-types),\\n  [other types](#other-types)\\n- **Errors:** [isIoCError and the error classes](#errors)\\n\\n---\"},{\"Name\":\"IoCContainer\",\"Text\":\"API Reference › Creating a container › new IoCContainer(options?)\\n\\n```ts ignore\\nnew IoCContainer(options?: IoCContainerOptions)\\n```\\n\\nCreates a root container. With no options it is already strict (registering a key and name twice\\nthrows), lazy (nothing is built until it is resolved or [`Activate()`](#activate) runs) and\\nprotected against hangs.\\n\\n`IoCContainerOptions` has one option, **`PendingTimeoutMs`** (default `30000`): a `Resolve`, a\\nmodule's `OnStart`/`OnStop`, or an instance's disposer still pending after this many milliseconds\\nfails with [`IoCResolveTimeoutError`](./errors.md#-did-not-finish-within-ms). `0` turns it off;\\nthe maximum is 2147483647.\\n\\nThe options are frozen when the container is created. Scopes inherit them.\\n\\n**Throws:** [`IoCRegistrationError`](./errors.md#pendingtimeoutms-must-be-a-number-of-milliseconds-from-0-off-to-2147483647-about-248-days)\\nwhen `PendingTimeoutMs` is negative, above 2147483647, or not a number.\\n\\n```ts\\nimport { IoCContainer } from '@fathym/ioc';\\n\\nconst ioc = new IoCContainer({ PendingTimeoutMs: 10_000 });\\n\\nconsole.log(ioc.State); // idle\\n```\"},{\"Name\":\"State\",\"Text\":\"API Reference › Creating a container › State\\n\\n```ts ignore\\nget State(): IoCContainerState // 'idle' | 'starting' | 'started' | 'stopping' | 'disposed'\\n```\\n\\n| State      | Means                                              |\\n| ---------- | -------------------------------------------------- |\\n| `idle`     | Created, or a `Start()` failed and was rolled back |\\n| `starting` | `Start()` is running                               |\\n| `started`  | `Start()` succeeded                                |\\n| `stopping` | `Dispose()` is running                             |\\n| `disposed` | Done; resolving, registering and starting throw    |\\n\\nA scope has its own state: the parent's `Start()` doesn't start it.\\n\\n```ts\\nimport { IoCContainer } from '@fathym/ioc';\\n\\nconst ioc = new IoCContainer();\\n\\nawait ioc.Start();\\nconsole.log(ioc.State); // started\\n\\nawait ioc.Dispose();\\nconsole.log(ioc.State); // disposed\\n```\\n\\n---\"},{\"Name\":\"Registration\",\"Text\":\"API Reference › Registration\\n\\nNothing is built at registration. Registering the same key and name twice in one container throws\\n[`IoCDuplicateRegistrationError`](./errors.md#-is-already-registered), unless the new registration\\nsays `Replace: true` or the existing one was registered with `Default: true`. A registration on a\\nscope is not a duplicate of the parent's: it overrides it for that scope.\\n\\nEvery registration method returns the container, so calls chain. On a disposed container\\n`RegisterClass`, `RegisterFactory`, `RegisterValue` and `Override` throw\\n[`IoCContainerDisposedError`](./errors.md#the-ioc-container-has-been-disposed).\"},{\"Name\":\"IoCToken\",\"Text\":\"API Reference › Registration › Keys and IoCToken(name)\\n\\n```ts ignore\\nfunction IoCToken<T, const TId extends string = string>(id: TId): IoCToken<T, TId>;\\n```\\n\\nA key is either a token or a class.\\n\\n- **A token is its name.** `IoCToken<Db>('Db')` returns `Symbol.for('Db')`, typed with the service\\n  it resolves. Two packages that call `IoCToken('Db')` share one key, and a plain `Symbol.for('Db')`\\n  from 0.x code is the same key at runtime. Pick names that won't collide across packages\\n  (`'eac/Config'` rather than `'Config'`).\\n- **A unique symbol** works as a private key if you type it as a token:\\n  `Symbol('Secret') as IoCToken<Secret, 'Secret'>`. A bare `Symbol()` or `Symbol.for()` doesn't\\n  compile as a key; it carries no service type.\\n- **A class is keyed by reference.** Two different classes named `Config` are two keys. Abstract\\n  classes work as typed \\\"interface\\\" keys for `RegisterFactory`.\\n- **Anything else is rejected:** strings, plain objects, arrow functions and other non-class\\n  functions used as keys throw\\n  [`IoCRegistrationError` with `IOC_INVALID_KEY`](./errors.md#keys-must-be-tokens-or-classes-but-a--was-given).\\n  (`RegisterClass` given a non-class throws `IOC_INVALID_REGISTRATION` instead.)\\n\\nThe optional second type argument keeps the name in the token's type. A\\n[typed container](#typed) needs it to tell apart two tokens of the same service type, such as two\\n`string` settings.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $DbUrl = IoCToken<string, 'eac/DbUrl'>('eac/DbUrl');\\n\\nconsole.log($DbUrl === Symbol.for('eac/DbUrl')); // true\\n\\nconst ioc = new IoCContainer().RegisterValue($DbUrl, 'kv://local');\\n\\nconsole.log(await ioc.Resolve($DbUrl)); // kv://local\\n```\"},{\"Name\":\"RegisterClass\",\"Text\":\"API Reference › Registration › RegisterClass(class, options?)\\n\\n```ts ignore\\nRegisterClass<C, TName = '$default', TType = never>(\\n  clazz: C,\\n  options?: IoCRegisterClassOptions<C, TKeys, TName, TType>,\\n): IoCContainer<TKeys | IoCRegistered<C or TType, TName>>\\n```\\n\\nRegisters a class the container constructs with `new clazz(...deps)`. The key is the class itself,\\nor the token given as `Type`.\\n\\n- **`Deps`** lists the services passed to the constructor, in parameter order. Each entry is a key\\n  or `[key, name]`. It is type-checked against the constructor's parameters, and on a\\n  [typed container](#typed) against the keys registered so far. The dependencies are resolved by\\n  the container that builds the instance: for a singleton, the container it is registered in; for\\n  `scoped` and `transient` services, the scope that resolves it. To make a singleton see a scope's\\n  overrides, [`Isolate`](#isolatekeys) it in that scope.\\n- **Without `Deps`** the class is constructed with no arguments. [`Validate()`](#validateoptions)\\n  reports a class whose constructor declares parameters.\\n- **`Type`** registers the class under a token instead (`{ Type: $Db }`). The class's instances\\n  must satisfy the token's type, or the call doesn't compile.\\n\\n**Throws:** [`RegisterClass expects a class`](./errors.md#registerclass-expects-a-class) for\\nanything that isn't a class.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\ninterface Db {\\n  url: string;\\n}\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\nconst $Db = IoCToken<Db, 'Db'>('Db');\\n\\nclass KvDb implements Db {\\n  constructor(public url: string) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Url, 'kv://local')\\n  .RegisterClass(KvDb, { Deps: [$Url], Type: $Db });\\n\\nconsole.log((await ioc.Resolve($Db)).url); // kv://local\\n```\"},{\"Name\":\"RegisterFactory\",\"Text\":\"API Reference › Registration › RegisterFactory(key, factory, options?)\\n\\n```ts ignore\\nRegisterFactory<K, TName = '$default', TDeps = []>(\\n  key: K,\\n  factory: (ioc: IoCContainer, ...deps: IoCDependencyValues<TDeps>) =>\\n    IoCServiceOf<K> | Promise<IoCServiceOf<K>>,\\n  options?: IoCRegisterOptions<TName, IoCServiceOf<K>> & { Deps?: TDeps },\\n): IoCContainer<TKeys | IoCRegistered<K, TName>>\\n```\\n\\nRegisters a function that builds the service, under a token or a class (abstract classes\\nincluded). The return type is checked against the key, and the function may be async.\\n\\n- **The first parameter is the container that builds the service** (the registering container\\n  for a singleton, the resolving scope for scoped and transient services). Resolve through it, not\\n  through a container captured in a closure: then a cycle throws\\n  [`IoCCircularDependencyError`](./errors.md#circular-dependency-detected-) at once, and a scope\\n  gets its own scoped services.\\n- **`Deps`** lists services to resolve and pass after the container, each parameter typed from its\\n  key. `Validate()` checks them; what the factory resolves in its body can't be checked before it\\n  runs.\\n\\n**Throws:** [`RegisterFactory expects a factory function.`](./errors.md#registerfactory-expects-a-factory-function)\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Host = IoCToken<string, 'Host'>('Host');\\nconst $Endpoint = IoCToken<string, 'Endpoint'>('Endpoint');\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Host, 'localhost')\\n  .RegisterFactory($Endpoint, (_ioc, host) => `${host}:8080`, { Deps: [$Host] });\\n\\nconsole.log(await ioc.Resolve($Endpoint)); // localhost:8080\\n```\"},{\"Name\":\"RegisterValue\",\"Text\":\"API Reference › Registration › RegisterValue(key, value, options?)\\n\\n```ts ignore\\nRegisterValue<K, TName = '$default'>(\\n  key: K,\\n  value: IoCServiceOf<K>,\\n  options?: { Name?: TName; Dispose?: (value) => unknown; Default?: boolean; Replace?: boolean },\\n): IoCContainer<TKeys | IoCRegistered<K, TName>>\\n```\\n\\nRegisters an existing value, shared as it is by every scope.\\n\\n- **Functions are stored, never called.**\\n- **A promise (or thenable) is stored as it is,** but `Resolve` awaits it, so you get its result.\\n- **The container never disposes a value** unless you pass `Dispose`, which tells it how. The\\n  value belongs to the code that created it.\\n- **A value has no lifetime option;** it acts as a singleton and can't be [isolated](#isolatekeys).\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Handler = IoCToken<(path: string) => string, 'Handler'>('Handler');\\n\\nconst ioc = new IoCContainer().RegisterValue($Handler, (path) => `handled ${path}`);\\n\\nconsole.log((await ioc.Resolve($Handler))('/notes')); // handled /notes\\n```\"},{\"Name\":\"Registration options\",\"Text\":\"API Reference › Registration › Registration options\\n\\n| Option     | On                                 | Default      | Meaning                                                                                                                                                                                                    |\\n| ---------- | ---------------------------------- | ------------ | ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |\\n| `Lifetime` | `RegisterClass`, `RegisterFactory` | singleton    | `'singleton'` (or omitted): one shared instance. `'transient'`: a new instance per resolve. `'scoped'`: one instance per [scope](#createscope); resolving it from the root throws `IoCScopeRequiredError`. |\\n| `Name`     | all three                          | `'$default'` | Registers under a name, so several services share one key. Named and unnamed registrations never stand in for each other.                                                                                  |\\n| `Default`  | all three                          | `false`      | A replaceable default; see [defaults](#defaults) below.                                                                                                                                                    |\\n| `Replace`  | all three                          | `false`      | Replaces an existing registration in this container on purpose. Without it, registering a key and name again throws.                                                                                       |\\n| `Dispose`  | all three                          | none         | `(instance) => …`: cleanup run when the owning container is disposed, for resources without `Symbol.asyncDispose` / `Symbol.dispose` (`(kv) => kv.close()`).                                               |\\n| `Deps`     | `RegisterClass`, `RegisterFactory` | none         | The services to inject, in order: keys or `[key, name]`.                                                                                                                                                   |\\n| `Type`     | `RegisterClass`                    | the class    | The token to register the class under; the class must satisfy its type.                                                                                                                                    |\\n\\n#### Defaults\\n\\nFrameworks and modules register what an application may replace with `Default: true`:\\n\\n- If a non-default registration of the key and name already exists, here or in a parent, the\\n  `Default` call does nothing. A parent registration made later also wins over a scope's\\n  default.\\n- Any later registration replaces a default without `Replace: true`; a later `Default` replaces an\\n  earlier one.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Greeting = IoCToken<string, 'Greeting'>('Greeting');\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Greeting, 'hello', { Default: true }) // a framework default\\n  .RegisterValue($Greeting, 'hi'); // the application's choice wins, no error\\n\\nconsole.log(await ioc.Resolve($Greeting)); // hi\\n```\"},{\"Name\":\"Unregister\",\"Text\":\"API Reference › Registration › Unregister(key, name?)\\n\\n```ts ignore\\nUnregister(key: IoCServiceKey<unknown>, name?: string): boolean\\n```\\n\\nRemoves a registration from this container, not from its parents. Returns `true` when one existed.\\nInstances already built from it are kept, and still disposed with the container.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Flag = IoCToken<boolean, 'Flag'>('Flag');\\n\\nconst ioc = new IoCContainer().RegisterValue($Flag, true);\\n\\nconsole.log(ioc.Unregister($Flag)); // true\\nconsole.log(ioc.Has($Flag)); // false\\n```\\n\\n---\"},{\"Name\":\"Typed containers\",\"Text\":\"API Reference › Typed containers\\n\\nA typed container tracks, in its type, every key registered so far. `Deps` may then only name keys\\nthat are already registered, so a missing dependency is a compile error rather than a runtime one.\\nRuntime behavior is unchanged.\"},{\"Name\":\"Typed\",\"Text\":\"API Reference › Typed containers › Typed()\\n\\n```ts ignore\\nTyped(): IoCContainer<IoCNoKeys>\\n```\\n\\nReturns the same container, typed with an empty registry. Each registration then adds its key (or\\n`[key, name]` for a named registration) to the type. Give tokens a name type argument\\n(`IoCToken<string, 'Url'>('Url')`) so that tokens of the same service type stay distinct.\\n\\nTypeScript compares classes by shape, so an unregistered class with the same members as a\\nregistered one passes the check; a class with a private field doesn't. `Validate()` catches it.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\n\\nclass Repo {\\n  constructor(public url: string) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  .Typed()\\n  .RegisterValue($Url, 'kv://local')\\n  .RegisterClass(Repo, { Deps: [$Url] }); // Deps: [$Url] before RegisterValue would not compile\\n\\nconsole.log((await ioc.Resolve(Repo)).url); // kv://local\\n```\"},{\"Name\":\"Expect\",\"Text\":\"API Reference › Typed containers › Expect(...keys)\\n\\n```ts ignore\\nExpect<const TDeps extends readonly (IoCDependencyKey<any> | readonly [IoCDependencyKey<any>, string])[]>(\\n  ...deps: TDeps\\n): IoCContainer<TKeys | IoCExpected<TDeps>>\\n```\\n\\nDeclares keys that are registered later or elsewhere (on each request scope, or by the code that\\nhosts the container), so `Deps` may name them now. Nothing is registered. `Validate()` treats\\nexpected keys as registered. Resolving one that was never registered throws\\n`IoCServiceNotFoundError` with a hint that it was expected.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $UserId = IoCToken<string, 'UserId'>('UserId');\\n\\nclass Greeter {\\n  constructor(public userId: string) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  .Typed()\\n  .Expect($UserId) // registered on each request scope\\n  .RegisterClass(Greeter, { Deps: [$UserId], Lifetime: 'scoped' });\\n\\nawait using scope = ioc.CreateScope().RegisterValue($UserId, 'ada');\\n\\nconsole.log((await scope.Resolve(Greeter)).userId); // ada\\n```\\n\\n---\"},{\"Name\":\"Resolution\",\"Text\":\"API Reference › Resolution\\n\\nEvery resolution method is async. A service is built the first time it is resolved.\"},{\"Name\":\"Resolve\",\"Text\":\"API Reference › Resolution › Resolve(key, name?)\\n\\n```ts ignore\\nResolve<K extends IoCServiceKey<unknown>>(key: K, name?: string): Promise<IoCServiceOf<K>>\\n```\\n\\nResolves the nearest registration of the key and name (`$default` when no name is given),\\nsearching this container, then its parents. The result is typed from the key; don't pass a type\\nargument.\\n\\n**Throws:** [`IoCServiceNotFoundError`](./errors.md#no-service-is-registered-for-),\\n[`IoCScopeRequiredError`](./errors.md#scoped-service--was-resolved-outside-a-scope),\\n[`IoCCircularDependencyError`](./errors.md#circular-dependency-detected-),\\n[`IoCResolveTimeoutError`](./errors.md#-did-not-finish-within-ms),\\n[`IoCContainerDisposedError`](./errors.md#the-ioc-container-has-been-disposed), or whatever the\\nfactory or constructor throws.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Db = IoCToken<{ url: string }, 'Db'>('Db');\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Db, { url: 'kv://primary' })\\n  .RegisterValue($Db, { url: 'kv://replica' }, { Name: 'replica' });\\n\\nconsole.log((await ioc.Resolve($Db, 'replica')).url); // kv://replica\\n```\"},{\"Name\":\"TryResolve\",\"Text\":\"API Reference › Resolution › TryResolve(key, name?)\\n\\n```ts ignore\\nTryResolve<K>(key: K, name?: string): Promise<IoCServiceOf<K> | undefined>\\n```\\n\\nLike `Resolve`, but returns `undefined` when nothing is registered for the key and name. If a\\nregistration exists and building it fails, the error is still thrown.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Cache = IoCToken<Map<string, string>, 'Cache'>('Cache');\\n\\nconst cache = await new IoCContainer().TryResolve($Cache);\\n\\nconsole.log(cache); // undefined\\n```\"},{\"Name\":\"ResolveAll\",\"Text\":\"API Reference › Resolution › ResolveAll(key)\\n\\n```ts ignore\\nResolveAll<K>(key: K): Promise<IoCServiceOf<K>[]>\\n```\\n\\nResolves every registration of a key, one per name, in the order of [`Names`](#nameskey): this\\ncontainer's names first, then names only a parent has. Returns `[]` when there are none.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Plugin = IoCToken<string, 'Plugin'>('Plugin');\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Plugin, 'auth', { Name: 'auth' })\\n  .RegisterValue($Plugin, 'metrics', { Name: 'metrics' });\\n\\nconsole.log(await ioc.ResolveAll($Plugin)); // [ \\\"auth\\\", \\\"metrics\\\" ]\\n```\"},{\"Name\":\"ResolveNamed\",\"Text\":\"API Reference › Resolution › ResolveNamed(key)\\n\\n```ts ignore\\nResolveNamed<K>(key: K): Promise<Map<string, IoCServiceOf<K>>>\\n```\\n\\nLike `ResolveAll`, but returns a `Map` from name to service.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Plugin = IoCToken<string, 'Plugin'>('Plugin');\\n\\nconst ioc = new IoCContainer().RegisterValue($Plugin, 'auth', { Name: 'auth' });\\n\\nconsole.log((await ioc.ResolveNamed($Plugin)).get('auth')); // auth\\n```\"},{\"Name\":\"ResolveRecord\",\"Text\":\"API Reference › Resolution › ResolveRecord(record)\\n\\n```ts ignore\\nResolveRecord<const R extends Record<string, IoCDependency<any>>>(\\n  record: R,\\n): Promise<{ -readonly [K in keyof R]: IoCDependencyValue<R[K]> }>\\n```\\n\\nResolves several services at once into an object with the same keys. Each value is a key or\\n`[key, name]`, and each property is typed from it.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\nconst $Port = IoCToken<number, 'Port'>('Port');\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Url, 'localhost')\\n  .RegisterValue($Port, 8080, { Name: 'http' });\\n\\nconst { url, port } = await ioc.ResolveRecord({ url: $Url, port: [$Port, 'http'] });\\n\\nconsole.log(`${url}:${port}`); // localhost:8080\\n```\"},{\"Name\":\"Names\",\"Text\":\"API Reference › Resolution › Names(key)\\n\\n```ts ignore\\nNames(key: IoCServiceKey<unknown>): string[]\\n```\\n\\nThe names registered for a key, here and in parents, nearest first, each listed once. The unnamed\\nregistration is listed as `$default`. Synchronous.\"},{\"Name\":\"Has\",\"Text\":\"API Reference › Resolution › Has(key, name?)\\n\\n```ts ignore\\nHas(key: IoCServiceKey<unknown>, name?: string): boolean\\n```\\n\\n`true` when a registration of the key and name exists here or in a parent. Synchronous; it builds\\nnothing.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Db = IoCToken<string, 'Db'>('Db');\\n\\nconst ioc = new IoCContainer().RegisterValue($Db, 'kv', { Name: 'replica' });\\n\\nconsole.log(ioc.Names($Db)); // [ \\\"replica\\\" ]\\nconsole.log(ioc.Has($Db), ioc.Has($Db, 'replica')); // false true\\n```\"},{\"Name\":\"How resolution behaves\",\"Text\":\"API Reference › Resolution › How resolution behaves\\n\\n- **One build per singleton.** Concurrent resolves of a singleton that is still building share\\n  one build. If the build fails, nothing is cached: the next resolve tries again.\\n- **Cycles.** When services resolve each other through the `ioc` their factory receives (or\\n  through `Deps`), a cycle throws `IoCCircularDependencyError` at once, naming the path. Through a\\n  container captured in a closure, after an `await`, the container can't see the cycle: the\\n  resolve fails at `PendingTimeoutMs` with `IoCResolveTimeoutError` instead.\\n- **Timeouts.** A resolve still pending after `PendingTimeoutMs` (30 seconds by default) fails with\\n  `IoCResolveTimeoutError`. The build itself is not cancelled. When the stuck dependency is\\n  reached after an `await`, the error names the service you resolved, not the one that hung.\\n- **Async factories.** A factory may return a promise or any thenable; either is awaited once and\\n  shared like any other build.\\n- **Disposal races.** A build that finishes after its container (or a parent) was disposed is\\n  disposed at once, and the `Resolve` waiting for it rejects with `IoCContainerDisposedError`.\\n\\n---\"},{\"Name\":\"CreateScope\",\"Text\":\"API Reference › Scopes › CreateScope()\\n\\n```ts ignore\\nCreateScope(): IoCContainer<TKeys>\\n```\\n\\nCreates a child container, for one request, command, job or test.\\n\\n- The scope resolves everything its parent can. Singletons stay shared with the parent.\\n- `scoped` registrations get one instance per scope, built in and disposed with that scope.\\n- Registrations made on the scope override the parent's, for this scope only. Services the scope\\n  builds (scoped and transient ones) see those overrides; a parent's singleton doesn't, since the\\n  parent builds it. [`Isolate`](#isolatekeys) gives the scope its own copy of a singleton that\\n  does. A `Default` on a scope yields to a parent's non-default registration.\\n- A scope skips modules its parent already has, and has its own `Start()` and `State`.\\n- Dispose it when done (`await using scope = ioc.CreateScope()`). Disposing the parent disposes its\\n  live scopes too, and a scope can't be used once its parent is disposed.\\n\\n```ts\\nimport { IoCContainer } from '@fathym/ioc';\\n\\nclass RequestId {\\n  public id = crypto.randomUUID();\\n}\\n\\nconst ioc = new IoCContainer().RegisterClass(RequestId, { Lifetime: 'scoped' });\\n\\nawait using a = ioc.CreateScope();\\nawait using b = ioc.CreateScope();\\n\\nconsole.log((await a.Resolve(RequestId)) === (await a.Resolve(RequestId))); // true\\nconsole.log((await a.Resolve(RequestId)) === (await b.Resolve(RequestId))); // false\\n```\"},{\"Name\":\"Isolate\",\"Text\":\"API Reference › Scopes › Isolate(...keys)\\n\\n```ts ignore\\nIsolate(...keys: (IoCServiceKey<unknown> | readonly [IoCServiceKey<unknown>, string])[]): this\\n```\\n\\nGives this scope its own copy of registrations it inherits. A singleton among them gets one\\ninstance in this scope, built from this scope's registrations (so it sees the scope's overrides of\\nits dependencies), instead of sharing the parent's. A key the scope already registers itself is\\nleft as it is.\\n\\n**Throws:** [`Isolate() works on scopes`](./errors.md#isolate-works-on-scopes-call-it-on-a-container-created-with-createscope)\\non a root container, [`IoCNotIsolatableError`](./errors.md#-cant-be-isolated-) for a value (every\\nscope shares values as they are), and `IoCServiceNotFoundError` for a key nobody registered.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Tenant = IoCToken<string, 'Tenant'>('Tenant');\\n\\nclass Greeter {\\n  constructor(public tenant: string) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Tenant, 'default')\\n  .RegisterClass(Greeter, { Deps: [$Tenant] });\\n\\nawait using scope = ioc.CreateScope()\\n  .RegisterValue($Tenant, 'acme')\\n  .Isolate(Greeter);\\n\\nconsole.log((await scope.Resolve(Greeter)).tenant); // acme\\nconsole.log((await ioc.Resolve(Greeter)).tenant); // default\\n```\\n\\n---\"},{\"Name\":\"Modules\",\"Text\":\"API Reference › Modules\\n\\nA module is a named unit of registrations with an optional lifecycle: the way a framework, a plugin\\nor a feature contributes services to a host container.\"},{\"Name\":\"Use\",\"Text\":\"API Reference › Modules › Use(...modules)\\n\\n```ts ignore\\nUse<const TModules extends readonly IoCModule<any, any>[]>(\\n  ...modules: TModules & IoCCheckNeeds<TKeys, TModules>\\n): IoCContainer<TKeys | IoCModulesProvide<TModules>>\\n```\\n\\nAdds modules, each after the modules it `Requires`. Each module's `Register` runs once, at once,\\nwith this container. A module already added here or in a parent is skipped, so shared\\nrequirements are registered once.\\n\\n- **Before `Start()` only.** A new module added to a container that isn't `idle` throws\\n  [`Module '…' was added after Start()`](./errors.md#module--was-added-after-start). Late plugins\\n  go in a scope: `ioc.CreateScope().Use(plugin)`, then `scope.Start()`.\\n- **Not all-or-nothing.** If a module's `Register` throws, the modules registered before it stay.\\n- **One container per module.** A module added to a scope and then to its parent is added (and\\n  started) twice; add shared modules to the parent first.\\n- **On a [typed container](#typed),** `Use()` doesn't compile until every key the modules `Needs`\\n  is registered, and what [typed modules](#definemoduledefinition) register is added to the type.\\n\\n**Throws:** [`IoCModuleCycleError`](./errors.md#module-dependency-cycle-) when modules require each\\nother in a loop, and\\n[`A module needs a Name and a Register(ioc) function.`](./errors.md#a-module-needs-a-name-and-a-registerioc-function)\\n\\n```ts\\nimport { IoCContainer, type IoCModule, IoCToken } from '@fathym/ioc';\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\n\\nconst Config: IoCModule = {\\n  Name: 'Config',\\n  Register: (ioc) => ioc.RegisterValue($Url, 'kv://local', { Default: true }),\\n};\\n\\nconst Data: IoCModule = {\\n  Name: 'Data',\\n  Requires: [Config],\\n  Register: () => {},\\n  OnStart: async (ioc) => console.log(`connecting to ${await ioc.Resolve($Url)}`),\\n};\\n\\nawait using ioc = new IoCContainer().Use(Data); // adds Config, then Data\\n\\nawait ioc.Start(); // connecting to kv://local\\n```\"},{\"Name\":\"IoCModule\",\"Text\":\"API Reference › Modules › IoCModule\\n\\n```ts ignore\\ninterface IoCModule<TNeeds = never, TProvides = never> {\\n  readonly Name: string;\\n  readonly Requires?: readonly IoCModule<any, any>[];\\n  readonly Needs?: readonly (IoCDependencyKey<any> | readonly [IoCDependencyKey<any>, string])[];\\n  Register(ioc: IoCContainer<any>): unknown;\\n  OnStart?(ioc: IoCContainer<any>): unknown;\\n  OnStop?(ioc: IoCContainer<any>): unknown;\\n}\\n```\\n\\n| Member     | Meaning                                                                                                                                         |\\n| ---------- | ----------------------------------------------------------------------------------------------------------------------------------------------- |\\n| `Name`     | A unique, readable name, used in errors and `Describe()`. Modules are told apart by reference, not by name.                                     |\\n| `Requires` | Modules that must be added (and started) before this one. `Use()` adds them.                                                                    |\\n| `Needs`    | Type-only: keys someone else registers. On a typed container, `Use()` doesn't compile until they are registered. Not checked at runtime.        |\\n| `Register` | Adds the module's registrations. Synchronous: async setup belongs in `OnStart` or in factories. Register what the app may replace as `Default`. |\\n| `OnStart`  | Runs from `Start()`, after the modules it requires have started. May be async.                                                                  |\\n| `OnStop`   | Runs from `Dispose()`, in reverse start order, before any instance is disposed, if the module started. May be async.                            |\\n\\nEach function receives the container itself.\"},{\"Name\":\"DefineModule\",\"Text\":\"API Reference › Modules › DefineModule(definition)\\n\\n```ts ignore\\nfunction DefineModule<const TRequires, const TNeeds, TResult>(\\n  definition: IoCModuleDefinition<TRequires, TNeeds, TResult>,\\n): IoCModule<needs, provides>;\\n```\\n\\nDefines a typed module. It returns the definition unchanged at runtime; the types do the work:\\n\\n- Inside `Register`, `OnStart` and `OnStop`, the container is typed with the keys the module\\n  `Needs` and the keys its `Requires` register themselves. `Deps` can only name those and the\\n  module's own earlier registrations.\\n- `Register` should return its registration chain: the keys it adds become what the module\\n  provides.\\n- On a typed container, `Use(module)` adds those keys, and only compiles when the container already\\n  has what the module needs (including what its requirements need and don't get from their own\\n  requirements).\\n\\nA module's provided keys don't include those of the modules it requires. To depend on a module\\nfurther down, require it too, or list its keys in `Needs`.\\n\\n```ts\\nimport { DefineModule, IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\n\\nclass Repo {\\n  constructor(public url: string) {}\\n}\\n\\nconst RepoModule = DefineModule({\\n  Name: 'Repo',\\n  Needs: [$Url],\\n  Register: (ioc) => ioc.RegisterClass(Repo, { Deps: [$Url] }),\\n});\\n\\nconst ioc = new IoCContainer()\\n  .Typed()\\n  .RegisterValue($Url, 'kv://local')\\n  .Use(RepoModule); // compiles: $Url is registered; Repo is now in the type\\n\\nconsole.log((await ioc.Resolve(Repo)).url); // kv://local\\n```\\n\\n---\"},{\"Name\":\"Start\",\"Text\":\"API Reference › Lifecycle › Start(options?)\\n\\n```ts ignore\\nStart(options?: { Validate?: boolean }): Promise<void>\\n```\\n\\n1. Runs [`Validate()`](#validateoptions), unless `{ Validate: false }`. A problem throws\\n   `IoCValidationError` and the state goes back to `idle`.\\n2. Runs each module's `OnStart`, one at a time, in the order the modules were added (requirements\\n   first). Each one is bounded by `PendingTimeoutMs`.\\n3. Sets `State` to `started`.\\n\\nIf an `OnStart` fails, the modules that started are stopped again (their `OnStop`, in reverse),\\nthe state goes back to `idle`, and `Start()` throws\\n[`IoCStartError`](./errors.md#module--failed-to-start-) with the module's `Name`, its error as\\n`cause`, and any `OnStop` errors as `RollbackErrors`. `Start()` can then be called again.\\n\\n- **It doesn't build services.** They are still built when first resolved; call\\n  [`Activate()`](#activate) to build every singleton at boot.\\n- Concurrent calls share one start; calling it on a started container does nothing.\\n- A scope's `Start()` runs the scope's own modules. Its parent must be started first when those\\n  modules require the parent's.\\n- On a disposed container it throws `IoCContainerDisposedError`.\\n\\n```ts\\nimport { IoCContainer, IoCStartError } from '@fathym/ioc';\\n\\nlet attempts = 0;\\n\\nconst ioc = new IoCContainer().Use({\\n  Name: 'Db',\\n  Register: () => {},\\n  OnStart: () => {\\n    if (++attempts === 1) throw new Error('connection refused');\\n  },\\n});\\n\\ntry {\\n  await ioc.Start();\\n} catch (err) {\\n  console.log((err as IoCStartError).message); // Module 'Db' failed to start: connection refused\\n}\\n\\nconsole.log(ioc.State); // idle\\n\\nawait ioc.Start(); // the retry succeeds\\n\\nconsole.log(ioc.State); // started\\n```\"},{\"Name\":\"Activate\",\"Text\":\"API Reference › Lifecycle › Activate()\\n\\n```ts ignore\\nActivate(): Promise<void>\\n```\\n\\nBuilds every singleton registered on this container now (not its parents' singletons, and not\\nscoped or transient services), so a broken service fails at boot rather than on first use. All\\nbuilds run, then one [`IoCActivationError`](./errors.md#ioc-activation-failed-for-) names every\\nservice that failed; its `errors` holds the causes, in the order of `Services`.\\n\\n```ts\\nimport { IoCActivationError, IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Db = IoCToken<string, 'Db'>('Db');\\n\\nconst ioc = new IoCContainer().RegisterFactory($Db, () => {\\n  throw new Error('no connection string');\\n});\\n\\nawait ioc.Start();\\n\\ntry {\\n  await ioc.Activate();\\n} catch (err) {\\n  console.log((err as IoCActivationError).Services); // [ \\\"Db\\\" ]\\n}\\n```\"},{\"Name\":\"Dispose\",\"Text\":\"API Reference › Lifecycle › Dispose()\\n\\n```ts ignore\\nDispose(): Promise<void>\\n[Symbol.asyncDispose](): Promise<void> // enables `await using`\\n```\\n\\nShuts the container down, in this order:\\n\\n1. Waits for a running `Start()` to finish its current module.\\n2. Runs `OnStop` of every started module: the live scopes' modules first, then this container's,\\n   in reverse start order. Services are all still alive at this point.\\n3. Disposes the live scopes.\\n4. Disposes the instances this container built, in reverse creation order.\\n\\nEvery step runs even if an earlier one fails. The failures are thrown together as one\\n[`IoCDisposeError`](./errors.md#errors-occurred-while-disposing-the-ioc-container) (an\\n`AggregateError`). Calling it again returns the same promise. Afterwards, resolving, registering,\\n`Use()`, `CreateScope()`, `Start()` and `Activate()` throw `IoCContainerDisposedError`; inspection\\n(`Has`, `Names`, `Describe`, `Validate`) still works.\\n\\n```ts\\nimport { IoCContainer } from '@fathym/ioc';\\n\\nclass Pool {\\n  async [Symbol.asyncDispose]() {\\n    console.log('pool closed');\\n  }\\n}\\n\\n{\\n  await using ioc = new IoCContainer().RegisterClass(Pool);\\n\\n  await ioc.Resolve(Pool);\\n} // pool closed\\n```\"},{\"Name\":\"What gets disposed\",\"Text\":\"API Reference › Lifecycle › What gets disposed\\n\\n- **Singletons and scoped instances** the container built, when they have `Symbol.asyncDispose` or\\n  `Symbol.dispose`, or a `Dispose` option. A singleton is disposed by the container that holds its\\n  registration; a scoped instance by its scope.\\n- **Not transient instances.** The container doesn't track them; whoever resolved one owns it.\\n- **Not values** from `RegisterValue`, unless registered with a `Dispose` option.\\n- **Each instance once,** by the container that built it, even when it is also registered\\n  elsewhere.\\n- Each disposer is bounded by `PendingTimeoutMs`.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\ninterface Kv {\\n  close(): void;\\n}\\n\\nconst $Kv = IoCToken<Kv, 'Kv'>('Kv');\\n\\nconst ioc = new IoCContainer().RegisterFactory(\\n  $Kv,\\n  () => ({ close: () => console.log('kv closed') }),\\n  { Dispose: (kv) => kv.close() },\\n);\\n\\nawait ioc.Resolve($Kv);\\n\\nawait ioc.Dispose(); // kv closed\\n```\\n\\n---\"},{\"Name\":\"Validate\",\"Text\":\"API Reference › Inspection › Validate(options?)\\n\\n```ts ignore\\nValidate(options?: { Throw?: boolean }): IoCValidationIssue[]\\n```\\n\\nChecks the registrations visible from this container without building anything, and throws one\\n[`IoCValidationError`](./errors.md#ioc-validation-failed-) listing every problem. With\\n`{ Throw: false }` it returns the issues instead (`[]` when there are none). `Start()` calls it.\\n\\n| `Kind`      | Problem                                                                                                          |\\n| ----------- | ---------------------------------------------------------------------------------------------------------------- |\\n| `missing`   | A declared dependency (`Deps`) that isn't registered, and wasn't declared with `Expect()`                        |\\n| `cycle`     | Services whose declared dependencies loop                                                                        |\\n| `captive`   | A singleton that depends on a scoped service, directly or through transients; it would keep one instance forever |\\n| `arguments` | A class registered without `Deps` whose constructor declares parameters                                          |\\n\\nOnly declared `Deps` are checked: what a factory resolves in its body is only known when it runs.\\nEach issue is `{ Kind, Service, Message, Hint }`; `Hint` says what to change, and the thrown\\nerror's message shows it as a `Fix:` line under each problem.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\n\\nclass Repo {\\n  constructor(public url: string) {}\\n}\\n\\nconst ioc = new IoCContainer().RegisterClass(Repo, { Deps: [$Url] });\\n\\nconsole.log(ioc.Validate({ Throw: false }).map((i) => i.Message));\\n// [ \\\"Repo depends on Url, which is not registered.\\\" ]\\n```\"},{\"Name\":\"Describe\",\"Text\":\"API Reference › Inspection › Describe()\\n\\n```ts ignore\\nDescribe(): IoCDescription\\n```\\n\\nReturns the container's state, registrations and modules as plain data, for logs, admin pages and\\ntests.\\n\\n| Field      | Contents                                                                                                  |\\n| ---------- | --------------------------------------------------------------------------------------------------------- |\\n| `State`    | The container's [state](#state)                                                                           |\\n| `Scope`    | `true` for a scope                                                                                        |\\n| `Services` | Every registration visible from here, nearest first, shadowed ones left out (see `IoCServiceDescription`) |\\n| `Modules`  | The modules added to this container (not its parent's), in start order: `{ Name, Requires, Started }`     |\\n\\nEach service is `{ Key, Name, Label, Kind, Lifetime, Default, Deps, Depth }`: `Kind` is `class`,\\n`factory` or `value`; `Label` is `Key` or `Key[name]`, as in error messages; `Deps` are labels;\\n`Depth` is 0 for this container, 1 for its parent, and so on.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\n\\nclass Repo {\\n  constructor(public url: string) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($Url, 'kv://local')\\n  .RegisterClass(Repo, { Deps: [$Url] });\\n\\nconst repo = ioc.Describe().Services.find((s) => s.Key === 'Repo');\\n\\nconsole.log(repo?.Kind, repo?.Lifetime, repo?.Deps); // class singleton [ \\\"Url\\\" ]\\n```\\n\\n---\"},{\"Name\":\"Override\",\"Text\":\"API Reference › Testing › Override(key, value, options?)\\n\\n```ts ignore\\nOverride<K extends IoCServiceKey<unknown>>(\\n  key: K,\\n  value: IoCServiceOf<K>,\\n  options?: { Name?: string },\\n): () => void\\n```\\n\\nReplaces a registration with a value until the returned function is called, which puts back exactly\\nwhat was there before (or removes the override if nothing was). It works on any container or\\nscope, and only changes that container. Several overrides of one key can be restored in any\\norder: once all are restored, the original is back.\\n\\n- Instances already built from the old registration keep what they were given. Override before\\n  resolving the services that use it, or override in a fresh scope.\\n- If something replaced the override in the meantime, restoring leaves that alone.\\n\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Clock = IoCToken<() => number, 'Clock'>('Clock');\\n\\nconst ioc = new IoCContainer().RegisterValue($Clock, () => Date.now());\\n\\nconst restore = ioc.Override($Clock, () => 0);\\n\\nconsole.log((await ioc.Resolve($Clock))()); // 0\\n\\nrestore();\\n\\nconsole.log((await ioc.Resolve($Clock))() > 0); // true\\n```\\n\\n---\"},{\"Name\":\"Types\",\"Text\":\"API Reference › Types\\n\\nAll types are exported from `@fathym/ioc`. Most are inferred; you rarely write them.\"},{\"Name\":\"Key and dependency types\",\"Text\":\"API Reference › Types › Key and dependency types\\n\\n| Type                          | Meaning                                                                                     |\\n| ----------------------------- | ------------------------------------------------------------------------------------------- |\\n| `IoCToken<T, TId>`            | A typed symbol key. `T` is the service type, `TId` the name (`string` unless given).        |\\n| `IoCTokenOf<TToken>`          | The service type a token carries.                                                           |\\n| `IoCServiceKey<T>`            | Anything a service is registered and resolved by: a token or a class (abstract included).   |\\n| `IoCServiceOf<TKey>`          | The service type a key resolves to: the token's type, or the class's instance type.         |\\n| `IoCServiceConstructor<T>`    | A class that can be constructed (what `RegisterClass` takes).                               |\\n| `IoCServiceKeyConstructor<T>` | A class used only as a key; abstract classes fit.                                           |\\n| `IoCDependencyKey<T>`         | A dependency key: a token or a class.                                                       |\\n| `IoCDependency<T>`            | A `Deps` entry: a key, or `[key, name]`.                                                    |\\n| `IoCDependencyValue<D>`       | The value one dependency injects.                                                           |\\n| `IoCDependencyValues<TDeps>`  | The values a `Deps` list injects, in order (a factory's parameters after `ioc`).            |\\n| `IoCDependenciesFor<P, K>`    | One dependency per constructor parameter, typed to match it (the type of a class's `Deps`). |\\n| `IoCFactoryDependency<K>`     | A dependency a factory may declare: on a typed container, a key registered so far.          |\"},{\"Name\":\"Registry types\",\"Text\":\"API Reference › Types › Registry types\\n\\nThese describe what a [typed container](#typed) knows. `IoCContainer<TKeys>`'s type argument is the\\nregistry; `any` (the default) means untyped.\\n\\n| Type                           | Meaning                                                                                      |\\n| ------------------------------ | -------------------------------------------------------------------------------------------- |\\n| `IoCNoKeys`                    | The registry of a typed container with nothing registered yet.                               |\\n| `IoCAllowedKeys<TKeys>`        | The dependencies a registry allows: everything when untyped, otherwise the registered keys.  |\\n| `IoCRegistered<TKey, TName>`   | What a registration adds: the key for the default name, or `[key, name]`.                    |\\n| `IoCExpected<TDeps>`           | What `Expect()` (or a module's `Needs`) adds.                                                |\\n| `IoCTypeFor<TInstance, TType>` | The `Type` option's type: the token, or `IoCTypeMismatch` when the class doesn't satisfy it. |\\n| `IoCTypeMismatch<TI, TS>`      | Shown in compile errors when a class doesn't implement its `Type` token's type.              |\\n| `IoCUnmetNeeds<TKeys, TMods>`  | The keys some modules need that a registry lacks.                                            |\\n| `IoCCheckNeeds<TKeys, TMods>`  | Makes `Use()` fail to compile, naming the unmet needs (`'@fathym/ioc/unmet-needs'`).         |\"},{\"Name\":\"Module types\",\"Text\":\"API Reference › Types › Module types\\n\\n| Type                                             | Meaning                                                                   |\\n| ------------------------------------------------ | ------------------------------------------------------------------------- |\\n| `IoCModule<TNeeds, TProvides>`                   | A module (see [IoCModule](#iocmodule)). The type arguments are type-only. |\\n| `IoCModuleDefinition<TRequires, TNeeds, TR>`     | What `DefineModule` takes.                                                |\\n| `IoCModuleKeys<TRequires, TNeeds>`               | The registry a typed module's functions see.                              |\\n| `IoCModuleNeeds<M>` / `IoCModulesNeed<Ms>`       | The keys a module (or a list of modules) needs from elsewhere.            |\\n| `IoCModuleProvides<M>` / `IoCModulesProvide<Ms>` | The keys a module (or a list of modules) registers itself.                |\\n| `IoCModuleTypes<TNeeds, TProvides>`              | The type-only marker a module carries.                                    |\\n| `IoCKeysOf<TContainer>`                          | The registry of a container type.                                         |\"},{\"Name\":\"Other types\",\"Text\":\"API Reference › Types › Other types\\n\\n| Type                      | Meaning                                                                        |\\n| ------------------------- | ------------------------------------------------------------------------------ |\\n| `IoCContainerOptions`     | `{ PendingTimeoutMs? }`                                                        |\\n| `IoCContainerState`       | `'idle' \\\\| 'starting' \\\\| 'started' \\\\| 'stopping' \\\\| 'disposed'`                |\\n| `IoCServiceOptions`       | `{ Lifetime?, Name?, Default?, Replace? }`, shared by the registration methods |\\n| `IoCRegisterClassOptions` | `RegisterClass`'s options: the shared ones plus `Deps`, `Type`, `Dispose`      |\\n| `IoCRegisterOptions`      | `RegisterFactory`'s options (besides `Deps`): the shared ones plus `Dispose`   |\\n| `IoCServiceResolver<T>`   | `(ioc: IoCContainer) => T \\\\| Promise<T>`: a factory without dependencies       |\\n| `IoCDescription`          | What `Describe()` returns                                                      |\\n| `IoCServiceDescription`   | One entry of `Describe().Services`                                             |\\n| `IoCValidationIssue`      | One problem found by `Validate()`: `{ Kind, Service, Message, Hint }`          |\\n| `IoCErrorCode`            | The union of every error code                                                  |\\n\\n---\"},{\"Name\":\"Errors\",\"Text\":\"API Reference › Errors\\n\\n```ts ignore\\nfunction isIoCError(error: unknown, code?: IoCErrorCode): error is Error & { code: IoCErrorCode };\\n```\\n\\nEvery error the container throws has a stable `code`. Match on the code rather than the message,\\nwhich may gain detail. `isIoCError(err, code?)` checks it; prefer it to `instanceof`, because\\n`IoCActivationError` and `IoCDisposeError` extend `AggregateError` rather than `IoCError`. Every\\nother class extends the abstract `IoCError`.\\n\\n| Class                           | Code                                          | Properties                                      |\\n| ------------------------------- | --------------------------------------------- | ----------------------------------------------- |\\n| `IoCServiceNotFoundError`       | `IOC_SERVICE_NOT_FOUND`                       | `Key`, `ServiceName`, `RegisteredNames`, `Path` |\\n| `IoCCircularDependencyError`    | `IOC_CIRCULAR_DEPENDENCY`                     | `Path`                                          |\\n| `IoCValidationError`            | `IOC_VALIDATION_FAILED`                       | `Problems`, `Issues`                            |\\n| `IoCContainerDisposedError`     | `IOC_CONTAINER_DISPOSED`                      | none                                            |\\n| `IoCActivationError`            | `IOC_ACTIVATION_FAILED`                       | `errors`, `Services`                            |\\n| `IoCDisposeError`               | `IOC_DISPOSE_FAILED`                          | `errors`                                        |\\n| `IoCRegistrationError`          | `IOC_INVALID_REGISTRATION`, `IOC_INVALID_KEY` | `code`                                          |\\n| `IoCScopeRequiredError`         | `IOC_SCOPE_REQUIRED`                          | `Service`                                       |\\n| `IoCDuplicateRegistrationError` | `IOC_DUPLICATE_REGISTRATION`                  | `Service`                                       |\\n| `IoCModuleCycleError`           | `IOC_MODULE_CYCLE`                            | `Path`                                          |\\n| `IoCStartError`                 | `IOC_START_FAILED`                            | `Module`, `cause`, `RollbackErrors`             |\\n| `IoCNotIsolatableError`         | `IOC_NOT_ISOLATABLE`                          | `Service`, `Reason`                             |\\n| `IoCResolveTimeoutError`        | `IOC_RESOLVE_TIMEOUT`                         | `Service`, `TimeoutMs`                          |\\n\\nEvery error class also has `DocsUrl`, the link to its code's section in the\\n[error catalog](./errors.md#error-codes); `ioCErrorDocsUrl(code)` gives the same link for a code.\\nEach message, its causes and its fix are in the [error catalog](./errors.md).\\n\\n```ts\\nimport { IoCContainer, IoCServiceNotFoundError, IoCToken, isIoCError } from '@fathym/ioc';\\n\\nconst $Missing = IoCToken<string, 'Missing'>('Missing');\\n\\ntry {\\n  await new IoCContainer().Resolve($Missing);\\n} catch (err) {\\n  console.log(isIoCError(err, 'IOC_SERVICE_NOT_FOUND')); // true\\n  console.log((err as IoCServiceNotFoundError).Key); // Missing\\n}\\n```\"},{\"Name\":\"What's Next\",\"Text\":\"API Reference › What's Next\\n\\n- Every error message, explained: [errors.md](./errors.md) _[Reference]_\\n- Learn the container step by step: [getting started](../getting-started/README.md) _[Tutorial]_\\n- Coming from 0.x: [migration guide](../migration/from-0.x.md) _[How-to]_\\n- Runnable programs: [examples](../../examples/README.md)\\n- Versioning and support: [policy.md](../policy.md) _[Reference]_\"},{\"Name\":\"IoCErrorCode\",\"Text\":\"typeAlias IoCErrorCode\\n\\nThe stable code carried by every error the container throws. Match on the code rather than the\\nmessage: messages are written for people and may gain detail, codes never change meaning.\"},{\"Name\":\"isIoCError\",\"Text\":\"function isIoCError\\n\\nTrue when `error` was thrown by the container, optionally with a specific code. Prefer it to\\n`instanceof`: it also covers `IoCActivationError` and `IoCDisposeError`, which extend\\n`AggregateError` rather than {@link IoCError}.\\n\\n```ts\\nimport { IoCContainer, IoCToken, isIoCError } from '@fathym/ioc';\\n\\nconst ioc = new IoCContainer();\\n\\ntry {\\n  await ioc.Resolve(IoCToken<string>('Missing'));\\n} catch (err) {\\n  console.log(isIoCError(err, 'IOC_SERVICE_NOT_FOUND')); // true\\n}\\n```\"},{\"Name\":\"ioCErrorDocsUrl\",\"Text\":\"function ioCErrorDocsUrl\\n\\nThe error catalog entry for `code`: what it means, the likely causes, and the fix.\\n\\n```ts\\nimport { ioCErrorDocsUrl } from '@fathym/ioc';\\n\\nconsole.log(ioCErrorDocsUrl('IOC_SERVICE_NOT_FOUND'));\\n// https://github.com/fathym/ioc/blob/main/docs/reference/errors.md#ioc_service_not_found\\n```\"},{\"Name\":\"IoCError\",\"Text\":\"class IoCError\\n\\nBase class of the container's errors. Every subclass has a stable {@link IoCErrorCode}.\"},{\"Name\":\"IoCServiceNotFoundError\",\"Text\":\"class IoCServiceNotFoundError\\n\\nThrown when a service is resolved that has no registration for its key and name. The message\\nlists the names that are registered for the key and the resolution path, when there are any.\"},{\"Name\":\"IoCContainerDisposedError\",\"Text\":\"class IoCContainerDisposedError\\n\\nThrown when a container (or scope) is used after it, or one of its parents, was disposed.\"},{\"Name\":\"IoCValidationIssue\",\"Text\":\"interface IoCValidationIssue\\n\\nOne problem found by `Validate()`.\"},{\"Name\":\"IoCValidationError\",\"Text\":\"class IoCValidationError\\n\\nThrown by `Validate()`, listing every problem found in the registrations.\"},{\"Name\":\"IoCCircularDependencyError\",\"Text\":\"class IoCCircularDependencyError\\n\\nThrown when resolving a service would require the service itself, directly or through other\\nservices (`A -> B -> A`), when the chain is followed through factories' `ioc` or `Deps`. Without\\nthis check such a graph would wait on itself forever.\"},{\"Name\":\"IoCRegistrationError\",\"Text\":\"class IoCRegistrationError\\n\\nThrown when a call is invalid: a key that isn't a token or class (`IOC_INVALID_KEY`); or a\\nnon-class given to `RegisterClass`, a non-function factory, an unknown `Lifetime`, a non-module\\ngiven to `Use()`, a module added after `Start()`, `Isolate()` on a root container, or an\\nout-of-range `PendingTimeoutMs` (`IOC_INVALID_REGISTRATION`).\"},{\"Name\":\"IoCScopeRequiredError\",\"Text\":\"class IoCScopeRequiredError\\n\\nThrown when a `scoped` service is resolved outside a scope (from the root container).\"},{\"Name\":\"IoCDuplicateRegistrationError\",\"Text\":\"class IoCDuplicateRegistrationError\\n\\nThrown when a key and name that already have a registration in the same container are\\nregistered again without `Replace: true` (or `Default: true`).\"},{\"Name\":\"IoCActivationError\",\"Text\":\"class IoCActivationError\\n\\nThrown by `Activate()`, wrapping every failure. It is an `AggregateError` too.\"},{\"Name\":\"IoCDisposeError\",\"Text\":\"class IoCDisposeError\\n\\nThrown by `Dispose()`, wrapping every error raised while disposing. It is an `AggregateError`\\ntoo.\"},{\"Name\":\"IoCModuleCycleError\",\"Text\":\"class IoCModuleCycleError\\n\\nThrown by `Use()` when modules require each other in a loop.\"},{\"Name\":\"IoCStartError\",\"Text\":\"class IoCStartError\\n\\nThrown by `Start()` when a module's `OnStart` fails. By then the modules that had started were\\nstopped again, in reverse order; errors from their `OnStop` are in `RollbackErrors`. The\\nmodule's error is the `cause`.\"},{\"Name\":\"IoCNotIsolatableError\",\"Text\":\"class IoCNotIsolatableError\\n\\nThrown by `Isolate()` for a registration that can't be copied into a scope.\"},{\"Name\":\"IoCResolveTimeoutError\",\"Text\":\"class IoCResolveTimeoutError\\n\\nThrown when a resolve, or a module's `OnStart`/`OnStop`, or an instance's disposer, is still\\npending after `PendingTimeoutMs` (30 seconds unless configured).\"},{\"Name\":\"IoCContainerState\",\"Text\":\"typeAlias IoCContainerState\\n\\nWhere the container is in its lifecycle (see {@link IoCContainer.State}).\"},{\"Name\":\"IoCContainerOptions\",\"Text\":\"interface IoCContainerOptions\\n\\nOptions for a container. Its scopes inherit them.\"},{\"Name\":\"IoCServiceDescription\",\"Text\":\"interface IoCServiceDescription\\n\\nOne registration, as reported by {@link IoCContainer.Describe}.\"},{\"Name\":\"IoCDescription\",\"Text\":\"interface IoCDescription\\n\\nWhat {@link IoCContainer.Describe} returns.\"},{\"Name\":\"IoCServiceConstructor\",\"Text\":\"typeAlias IoCServiceConstructor\\n\\nA class that can be registered and used as a resolution key.\"},{\"Name\":\"IoCServiceKeyConstructor\",\"Text\":\"typeAlias IoCServiceKeyConstructor\\n\\nA class used only as a key (it is never constructed by the container), so abstract classes\\nwork as typed \\\"interface\\\" keys: `ioc.RegisterFactory(Repo, () => new PgRepo())`.\"},{\"Name\":\"IoCServiceKey\",\"Text\":\"typeAlias IoCServiceKey\\n\\nAnything a service can be registered and resolved by: a typed token, or a class.\"},{\"Name\":\"IoCServiceOf\",\"Text\":\"typeAlias IoCServiceOf\\n\\nThe service type a key resolves to: the token's type, the class's instance, else `unknown`.\"},{\"Name\":\"IoCServiceOptions\",\"Text\":\"typeAlias IoCServiceOptions\\n\\nOptions shared by every registration method.\"},{\"Name\":\"IoCDependencyKey\",\"Text\":\"typeAlias IoCDependencyKey\\n\\nA dependency key: a typed token, or a class (abstract classes included).\"},{\"Name\":\"IoCDependency\",\"Text\":\"typeAlias IoCDependency\\n\\nA declared dependency: a key, or `[key, name]` for a named registration.\"},{\"Name\":\"IoCDependencyValue\",\"Text\":\"typeAlias IoCDependencyValue\\n\\nThe value a dependency injects.\"},{\"Name\":\"IoCDependencyValues\",\"Text\":\"typeAlias IoCDependencyValues\\n\\nThe values a list of dependencies injects, in order.\"},{\"Name\":\"IoCNoKeys\",\"Text\":\"typeAlias IoCNoKeys\\n\\nThe registry of a {@link IoCContainer.Typed typed container} that has nothing registered yet.\\nNo dependency matches it.\"},{\"Name\":\"IoCAllowedKeys\",\"Text\":\"typeAlias IoCAllowedKeys\\n\\nThe dependencies a container's registry allows: every key when the container is untyped\\n(`any`), otherwise only the keys registered (or expected) so far.\"},{\"Name\":\"IoCDependenciesFor\",\"Text\":\"typeAlias IoCDependenciesFor\\n\\nOne dependency per constructor parameter, each typed to match its parameter and, on a typed\\ncontainer, limited to the keys already registered.\"},{\"Name\":\"IoCFactoryDependency\",\"Text\":\"typeAlias IoCFactoryDependency\\n\\nA dependency a factory may declare in `Deps`: on a typed container, a key registered so far.\"},{\"Name\":\"IoCRegistered\",\"Text\":\"typeAlias IoCRegistered\\n\\nWhat a registration adds to a typed container's registry: the key itself for the default name,\\nor `[key, name]` for a named registration.\"},{\"Name\":\"IoCExpected\",\"Text\":\"typeAlias IoCExpected\\n\\nWhat {@link IoCContainer.Expect} adds to a typed container's registry.\"},{\"Name\":\"IoCTypeFor\",\"Text\":\"typeAlias IoCTypeFor\\n\\nThe `Type` option of {@link IoCContainer.RegisterClass}: a token whose type the class's\\ninstances satisfy.\"},{\"Name\":\"IoCTypeMismatch\",\"Text\":\"typeAlias IoCTypeMismatch\\n\\nReported when `RegisterClass(clazz, { Type })` names a token the class does not satisfy.\"},{\"Name\":\"IoCRegisterClassOptions\",\"Text\":\"typeAlias IoCRegisterClassOptions\\n\\nOptions accepted by {@link IoCContainer.RegisterClass}.\"},{\"Name\":\"IoCRegisterOptions\",\"Text\":\"typeAlias IoCRegisterOptions\\n\\nOptions for registrations whose key is given separately.\"},{\"Name\":\"IoCServiceResolver\",\"Text\":\"typeAlias IoCServiceResolver\\n\\nA factory: receives the container and returns the service (or a promise of it).\"},{\"Name\":\"IoCUnmetNeeds\",\"Text\":\"typeAlias IoCUnmetNeeds\\n\\nReported by `Use()` on a typed container when a module needs keys the container lacks.\"},{\"Name\":\"IoCCheckNeeds\",\"Text\":\"typeAlias IoCCheckNeeds\\n\\nMakes `Use()` fail to compile, naming the missing keys, when a module's needs are unmet. An\\nuntyped container (`any` registry) checks nothing.\"},{\"Name\":\"IoCContainer\",\"Text\":\"class IoCContainer\\n\\nA small, async-first, decorator-free inversion-of-control container.\\n\\nDocs: https://github.com/fathym/ioc/blob/main/docs/README.md\\n\\nRegister and resolve\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $DbUrl = IoCToken<string>('DbUrl');\\n\\nclass Repo {\\n  constructor(public url: string) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  .RegisterValue($DbUrl, 'kv://local')\\n  .RegisterClass(Repo, { Deps: [$DbUrl] });\\n\\nconsole.log((await ioc.Resolve(Repo)).url); // kv://local\\n```\\n\\nA typed container: `Deps` may only name what is already registered\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $DbUrl = IoCToken<string, 'DbUrl'>('DbUrl');\\n\\nclass Repo {\\n  constructor(public url: string) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  .Typed()\\n  .RegisterValue($DbUrl, 'kv://local')\\n  .RegisterClass(Repo, { Deps: [$DbUrl] }); // a key registered later would not compile\\n\\nconst repo = await ioc.Resolve(Repo); // repo: Repo\\n```\"},{\"Name\":\"IoCModule\",\"Text\":\"interface IoCModule\\n\\nA named unit of registrations with an optional lifecycle: the way a framework, a plugin or a\\nfeature contributes services to a host container. Add modules with {@link IoCContainer.Use}.\\n\\n- `Register` adds the module's services. It runs once per container, after the modules it\\n  `Requires`.\\n- `OnStart` runs from {@link IoCContainer.Start}, one module at a time, after the modules it\\n  requires.\\n- `OnStop` runs from {@link IoCContainer.Dispose}, in the reverse order, before any instance is\\n  disposed, for modules that started.\\n\\nEach of them receives the container.\\n\\nUse {@link DefineModule} to get a typed module, whose `Register` is checked against what the\\nmodule needs and whose provided keys flow into a typed container.\\n\\n```ts\\nimport { IoCContainer, type IoCModule, IoCToken } from '@fathym/ioc';\\n\\ninterface Clock {\\n  now(): number;\\n}\\n\\nconst $Clock = IoCToken<Clock, 'Clock'>('Clock');\\n\\nconst ClockModule: IoCModule = {\\n  Name: 'Clock',\\n  Register: (ioc) => {\\n    ioc.RegisterValue($Clock, { now: () => Date.now() }, { Default: true });\\n  },\\n};\\n\\nawait using ioc = new IoCContainer().Use(ClockModule);\\n\\nawait ioc.Start();\\n\\nconsole.log((await ioc.Resolve($Clock)).now() > 0);\\n```\"},{\"Name\":\"IoCModuleTypes\",\"Text\":\"typeAlias IoCModuleTypes\\n\\nThe type-only marker of a module. Its parameter is compared both ways (a method signature), so\\na typed module still fits wherever a plain `IoCModule` is expected.\"},{\"Name\":\"IoCModuleProvides\",\"Text\":\"typeAlias IoCModuleProvides\\n\\nThe keys a module itself registers (type-only). What the modules it requires register is theirs:\\na module's type never grows with the depth of its requirements, so type-checking stays cheap.\"},{\"Name\":\"IoCModuleNeeds\",\"Text\":\"typeAlias IoCModuleNeeds\\n\\nThe keys a module needs from elsewhere, including what the modules it requires need and don't\\nget from their own requirements (type-only).\"},{\"Name\":\"IoCModulesProvide\",\"Text\":\"typeAlias IoCModulesProvide\\n\\nThe keys the listed modules register themselves (type-only).\"},{\"Name\":\"IoCModulesNeed\",\"Text\":\"typeAlias IoCModulesNeed\\n\\nThe keys needed by a list of modules (type-only).\"},{\"Name\":\"IoCKeysOf\",\"Text\":\"typeAlias IoCKeysOf\\n\\nThe registry of a container, read from its type (type-only).\"},{\"Name\":\"IoCModuleKeys\",\"Text\":\"typeAlias IoCModuleKeys\\n\\nThe registry a typed module's `Register`, `OnStart` and `OnStop` see.\"},{\"Name\":\"IoCModuleDefinition\",\"Text\":\"interface IoCModuleDefinition\\n\\nWhat {@link DefineModule} takes.\"},{\"Name\":\"DefineModule\",\"Text\":\"function DefineModule\\n\\nDefines a typed module. Inside `Register`, the container is typed with the keys the module\\n`Needs` and the keys its `Requires` register themselves, so `Deps` can only name those and the\\nmodule's own earlier registrations. Return the registration chain: its keys become what the\\nmodule provides.\\nOn a {@link IoCContainer.Typed typed container}, `Use(module)` adds those keys, and only\\ncompiles when the container already has what the module needs.\\n\\nEach module type-checks its own short chain, so large applications stay fast to compile.\\n\\n```ts\\nimport { DefineModule, IoCContainer, IoCToken } from '@fathym/ioc';\\n\\nconst $Url = IoCToken<string, 'Url'>('Url');\\n\\nclass Repo {\\n  constructor(public url: string) {}\\n}\\n\\nconst RepoModule = DefineModule({\\n  Name: 'Repo',\\n  Needs: [$Url],\\n  Register: (ioc) => ioc.RegisterClass(Repo, { Deps: [$Url] }),\\n});\\n\\nconst ioc = new IoCContainer()\\n  .Typed()\\n  .RegisterValue($Url, 'kv://local')\\n  .Use(RepoModule); // compiles: $Url is registered; Repo is now typed in\\n\\nconsole.log((await ioc.Resolve(Repo)).url); // kv://local\\n```\"},{\"Name\":\"IoCToken\",\"Text\":\"typeAlias IoCToken\\n\\nA key for a service that isn't a class: an interface, a function type, a string, a config\\nobject. It carries the service's type, so resolving it needs no explicit generic:\\n\\nRegister and resolve by token\\n```ts\\nimport { IoCContainer, IoCToken } from '@fathym/ioc';\\n\\ninterface Db {\\n  query(sql: string): string;\\n}\\n\\nconst $Db = IoCToken<Db>('Db');\\n\\nconst ioc = new IoCContainer();\\n\\nioc.RegisterFactory($Db, () => ({ query: (sql) => sql })); // the factory must return a Db\\n\\nconst db = await ioc.Resolve($Db); // db: Db\\n```\\n\\n**A token is its name.** `IoCToken('Db')` is `Symbol.for('Db')`, so two packages that each call\\n`IoCToken('Db')` share one key, as 0.x keys did. Pick names that won't collide across packages\\n(`'eac/Config'` rather than `'Config'`).\\n\\nThe optional second type argument fixes the name in the token's type. Two tokens of the same\\nservice type are then still told apart by a {@link IoCContainer.Typed typed container}, which\\nmatters for tokens of plain types such as `string`:\\n\\n```ts\\nimport { IoCToken } from '@fathym/ioc';\\n\\nconst $DbUrl = IoCToken<string, 'DbUrl'>('DbUrl');\\n```\"},{\"Name\":\"IoCTokenOf\",\"Text\":\"typeAlias IoCTokenOf\\n\\nThe service type carried by a token.\"}],\"Errors\":[{\"Code\":\"IOC_SERVICE_NOT_FOUND\",\"Text\":\"`IoCServiceNotFoundError`: nothing is registered for the key and name being resolved.\\n[Details](#no-service-is-registered-for-). **Fix:** register it, check the `Name`, or `Use()` the\\nmodule that provides it.\\n\\n### No service is registered for …\\n\\n```text\\nNo service is registered for Db.\\nNo service is registered for Db with name 'replica'. Registered names: [$default, primary].\\nNo service is registered for Url. Resolution path: Repo -> Db.\\nNo service is registered for Request. It is declared with Expect(); register it on the container or scope that provides it.\\n```\\n\\n`IoCServiceNotFoundError` (`IOC_SERVICE_NOT_FOUND`). Nothing is registered for that key and name,\\nhere or in a parent. The message lists the names that _are_ registered for the key, and the\\nresolution path when a factory or `Deps` asked for it. `Key`, `ServiceName`, `RegisteredNames`\\nand `Path` hold the same details.\\n\\n**Fix:** register it, or resolve the name that is registered. If a scope provides the key (a\\nrequest, a command), resolve from that scope, not the root. To make a dependency optional, use\\n`TryResolve`, which returns `undefined` when nothing is registered.\\n\\nCatalog: https://github.com/fathym/ioc/blob/main/docs/reference/errors.md#ioc_service_not_found\"},{\"Code\":\"IOC_CIRCULAR_DEPENDENCY\",\"Text\":\"`IoCCircularDependencyError`: resolving a service would need the service itself.\\n[Details](#circular-dependency-detected-). **Fix:** move what both sides need into a third service,\\nor resolve one side later, in a method instead of a constructor.\\n\\n### Circular dependency detected: …\\n\\n```text\\nCircular dependency detected: Orders -> Billing -> Orders.\\n```\\n\\n`IoCCircularDependencyError` (`IOC_CIRCULAR_DEPENDENCY`). A service needs itself, directly or\\nthrough others, while it is being built. `Path` lists the chain. The container sees the chain\\nwhen factories resolve through the `ioc` they receive, or through `Deps`.\\n\\n**Fix:** break the loop. Move the shared part into a third service both depend on, or have one\\nside resolve the other later, after construction, from the `ioc` its factory received:\\n\\n```ts\\nimport { IoCContainer } from '@fathym/ioc';\\n\\nclass Billing {\\n  constructor(private orders: () => Promise<Orders>) {}\\n\\n  async total() {\\n    return (await this.orders()).count * 10;\\n  }\\n}\\n\\nclass Orders {\\n  public count = 3;\\n\\n  constructor(public billing: Billing) {}\\n}\\n\\nconst ioc = new IoCContainer()\\n  .RegisterFactory(Billing, (c) => new Billing(() => c.Resolve(Orders))) // resolved on first use\\n  .RegisterClass(Orders, { Deps: [Billing] });\\n\\nconsole.log(await (await ioc.Resolve(Orders)).billing.total()); // 30\\n```\\n\\nCatalog: https://github.com/fathym/ioc/blob/main/docs/reference/errors.md#ioc_circular_dependency\"},{\"Code\":\"IOC_VALIDATION_FAILED\",\"Text\":\"`IoCValidationError`: `Validate()` (or `Start()`) found problems in the wiring; each one comes with\\na `Fix:` line. [Details](#ioc-validation-failed-).\\n\\n### IoC validation failed: …\\n\\n```text\\nIoC validation failed:\\n  - Repo depends on Url, which is not registered.\\n    Fix: Register Url with RegisterClass, RegisterFactory or RegisterValue, or Use() the module that provides it. If a scope or the host registers it later, declare it with Expect().\\n  - singleton Cache depends on scoped Session; it would keep one instance for its whole life. Make Cache scoped, or resolve Session where it is used, from the scope at hand.\\n    Fix: Register Cache with Lifetime: 'scoped', or remove Session from its Deps and resolve it from the request's scope where it is needed.\\nDocs: https://github.com/fathym/ioc/blob/main/docs/reference/errors.md#ioc_validation_failed\\n```\\n\\n`IoCValidationError` (`IOC_VALIDATION_FAILED`), from `Validate()` and from `Start()`, which\\nvalidates first. It lists every problem at once, each with a `Fix:` line; `Issues` holds them as\\n`{ Kind, Service, Message, Hint }` and `Problems` as messages. Only declared `Deps` are checked.\\n\\nCatalog: https://github.com/fathym/ioc/blob/main/docs/reference/errors.md#ioc_validation_failed\"},{\"Code\":\"IOC_CONTAINER_DISPOSED\",\"Text\":\"`IoCContainerDisposedError`: the container, or a parent of the scope, was already disposed.\\n[Details](#the-ioc-container-has-been-disposed). **Fix:** don't use a container after\\n`Dispose()`; create a new scope per request.\\n\\n### The IoC container has been disposed.\\n\\n```text\\nThe IoC container has been disposed.\\n```\\n\\n`IoCContainerDisposedError` (`IOC_CONTAINER_DISPOSED`). A container, or a scope whose parent was\\ndisposed, was used after `Dispose()`. `Start()` also rejects with it when `Dispose()` runs while\\nit is starting, and so does a `Resolve` whose build finishes after the container was disposed\\n(the instance is disposed at once). **Fix:** keep a container alive while it is used; create a new one (or a new\\nscope) instead of reusing a disposed one.\\n\\nCatalog: https://github.com/fathym/ioc/blob/main/docs/reference/errors.md#ioc_container_disposed\"},{\"Code\":\"IOC_ACTIVATION_FAILED\",\"Text\":\"`IoCActivationError` (an `AggregateError`): `Activate()` could not build one or more singletons.\\n[Details](#ioc-activation-failed-for-). **Fix:** read `errors` for each cause; `Activate()` can be\\ncalled again.\\n\\n### IoC activation failed for: …\\n\\n```text\\nIoC activation failed for: Db, Search.\\n```\\n\\n`IoCActivationError` (`IOC_ACTIVATION_FAILED`), an `AggregateError` from `Activate()`. Every\\nsingleton that failed to build is named; `errors` holds their errors and `Services` their\\nlabels. The rest were built. **Fix:** fix each error in `errors`; `Activate()` can be called\\nagain, and the failed ones are rebuilt.\\n\\nCatalog: https://github.com/fathym/ioc/blob/main/docs/reference/errors.md#ioc_activation_failed\"},{\"Code\":\"IOC_DISPOSE_FAILED\",\"Text\":\"`IoCDisposeError` (an `AggregateError`): one or more disposers or `OnStop` hooks threw; the rest\\nstill ran. [Details](#errors-occurred-while-disposing-the-ioc-container). **Fix:** read `errors`.\\n\\n### Errors occurred while disposing the IoC container.\\n\\n```text\\nErrors occurred while disposing the IoC container.\\n```\\n\\n`IoCDisposeError` (`IOC_DISPOSE_FAILED`), an `AggregateError` from `Dispose()`. A module's\\n`OnStop`, a scope, or an instance's disposer failed. Every other step still ran; `errors` holds\\neach failure. **Fix:** fix each error in `errors`.\\n\\nCatalog: https://github.com/fathym/ioc/blob/main/docs/reference/errors.md#ioc_dispose_failed\"},{\"Code\":\"IOC_RESOLVE_TIMEOUT\",\"Text\":\"`IoCResolveTimeoutError`: a build, `OnStart`, `OnStop` or disposer took longer than\\n`PendingTimeoutMs`. [Details](#-did-not-finish-within-ms). **Fix:** find the slow factory or hook,\\ngive it its own timeout, or raise `PendingTimeoutMs`.\\n\\n### … did not finish within …ms\\n\\n```text\\nReport did not finish within 30000ms. Something it awaits may never settle (a connection, a lock), or factories may wait on each other through a container captured in a closure; resolve through the factory's parameter. Raise PendingTimeoutMs if it is just slow.\\nModule 'Server' OnStart did not finish within 30000ms. …\\nDisposing Pool did not finish within 30000ms. …\\n```\\n\\n`IoCResolveTimeoutError` (`IOC_RESOLVE_TIMEOUT`). A `Resolve`, a module's `OnStart`/`OnStop`, or\\nan instance's disposer was still pending after `PendingTimeoutMs` (30 seconds unless set).\\n`Service` names what was pending; `TimeoutMs` the limit. From `Start()` it arrives as\\n`IoCStartError`'s `cause`; from `Dispose()`, inside `IoCDisposeError`.\\n\\n**Likely causes:**\\n\\n- **Something that never settles,** such as a connection that waits forever. Give the factory\\n  its own timeout (`AbortSignal.timeout(…)` for `fetch`).\\n- **A cycle the container can't see:** factories waiting on each other through a container\\n  captured in a closure, after an `await`. Resolve through the factory's `ioc` instead, so the\\n  container follows the chain and throws\\n  [`IoCCircularDependencyError`](#circular-dependency-detected-) at once.\\n- **It is just slow.** Raise `new IoCContainer({ PendingTimeoutMs: 60_000 })`, or `0` to wait\\n  forever.\\n\\nCatalog: https://github.com/fathym/ioc/blob/main/docs/reference/errors.md#ioc_resolve_timeout\"},{\"Code\":\"IOC_SCOPE_REQUIRED\",\"Text\":\"`IoCScopeRequiredError`: a scoped service was resolved from the root container.\\n[Details](#scoped-service--was-resolved-outside-a-scope). **Fix:** resolve it from\\n`ioc.CreateScope()`.\\n\\n### Scoped service … was resolved outside a scope\\n\\n```text\\nScoped service Session was resolved outside a scope; resolve it from a scope created with CreateScope().\\n```\\n\\n`IoCScopeRequiredError` (`IOC_SCOPE_REQUIRED`). A `scoped` service was resolved from the root\\ncontainer, which has no scope to own it. **Fix:** create a scope and resolve from it:\\n\\n```ts\\nimport { IoCContainer } from '@fathym/ioc';\\n\\nclass Session {}\\n\\nconst ioc = new IoCContainer().RegisterClass(Session, { Lifetime: 'scoped' });\\n\\nawait using scope = ioc.CreateScope();\\n\\nconsole.log((await scope.Resolve(Session)) instanceof Session); // true\\n```\\n\\nCatalog: https://github.com/fathym/ioc/blob/main/docs/reference/errors.md#ioc_scope_required\"},{\"Code\":\"IOC_DUPLICATE_REGISTRATION\",\"Text\":\"`IoCDuplicateRegistrationError`: the key and name are already registered.\\n[Details](#-is-already-registered). **Fix:** pass `Replace: true` to replace it on purpose, or give\\nit a different `Name`.\\n\\n### … is already registered\\n\\n```text\\nMailer is already registered; pass Replace: true to override it, or Default: true to register a default that yields to other registrations.\\n```\\n\\n`IoCDuplicateRegistrationError` (`IOC_DUPLICATE_REGISTRATION`). The same key and name were\\nregistered twice in one container. **Fix:** pass `Replace: true` on the registration meant to\\nwin, or register the first one with `Default: true` so any later one replaces it. Registering a\\nkey on a scope that its parent also registers is not a duplicate: the scope's wins there.\\n\\nCatalog: https://github.com/fathym/ioc/blob/main/docs/reference/errors.md#ioc_duplicate_registration\"},{\"Code\":\"IOC_MODULE_CYCLE\",\"Text\":\"`IoCModuleCycleError`: modules require each other in a loop. [Details](#module-dependency-cycle-).\\n**Fix:** move the shared registrations into a module both require.\\n\\n### Module dependency cycle: …\\n\\n```text\\nModule dependency cycle: Api -> Db -> Api.\\n```\\n\\n`IoCModuleCycleError` (`IOC_MODULE_CYCLE`), from `Use()`. Modules require each other through\\n`Requires`. **Fix:** move what both need into a third module that both require.\\n\\nCatalog: https://github.com/fathym/ioc/blob/main/docs/reference/errors.md#ioc_module_cycle\"},{\"Code\":\"IOC_START_FAILED\",\"Text\":\"`IoCStartError`: a module's `OnStart` failed; the modules already started were stopped again.\\n[Details](#module--failed-to-start-). **Fix:** read `cause`; `Start()` can be called again.\\n\\n### Module '…' failed to start: …\\n\\n```text\\nModule 'Server' failed to start: port 8080 in use\\nModule 'Reports' failed to start: it requires module 'Host', which belongs to a parent container that hasn't started; start the parent first\\n```\\n\\n`IoCStartError` (`IOC_START_FAILED`), from `Start()`. A module's `OnStart` threw (its error is the\\n`cause`). The modules that had started were stopped again, in reverse; errors from their\\n`OnStop` are in `RollbackErrors`. The container is back to `idle`, so `Start()` can be called\\nagain once the cause is fixed. The second message comes from a scope whose module requires a\\nmodule of a parent that hasn't started: start the parent first.\\n\\nCatalog: https://github.com/fathym/ioc/blob/main/docs/reference/errors.md#ioc_start_failed\"},{\"Code\":\"IOC_NOT_ISOLATABLE\",\"Text\":\"`IoCNotIsolatableError`: `Isolate()` was given a key it can't copy into the scope.\\n[Details](#-cant-be-isolated-). **Fix:** isolate only singletons registered in a parent.\\n\\n### … can't be isolated: …\\n\\n```text\\nUrl can't be isolated: it is a value, which every scope shares as is.\\n```\\n\\n`IoCNotIsolatableError` (`IOC_NOT_ISOLATABLE`), from `Isolate()`. Values are shared as they are;\\nthere is nothing to build per scope. **Fix:** register a different value on the scope instead.\\n\\nCatalog: https://github.com/fathym/ioc/blob/main/docs/reference/errors.md#ioc_not_isolatable\"},{\"Code\":\"IOC_INVALID_REGISTRATION\",\"Text\":\"`IoCRegistrationError`: a registration or call was malformed.\\n[Details](#registration-errors). **Fix:** follow the message; each variant is listed there.\\n\\n### Registration errors\\n\\n`IoCRegistrationError`, code `IOC_INVALID_REGISTRATION` unless noted.\\n\\nCatalog: https://github.com/fathym/ioc/blob/main/docs/reference/errors.md#ioc_invalid_registration\"},{\"Code\":\"IOC_INVALID_KEY\",\"Text\":\"`IoCRegistrationError`: a key was neither a token nor a class (a string, say).\\n[Details](#keys-must-be-tokens-or-classes-but-a--was-given). **Fix:** use\\n`IoCToken<T>('name')` or the class itself.\\n\\n---\\n\\n### Keys must be tokens or classes, but a … was given.\\n\\n```text\\nKeys must be tokens or classes, but a string was given. Create a token with IoCToken<T>('Name').\\n```\\n\\nCode `IOC_INVALID_KEY`. A string, plain object or plain function was used as a key. **Fix:** use\\na token (`IoCToken<T>('Name')`) or a class.\\n\\nCatalog: https://github.com/fathym/ioc/blob/main/docs/reference/errors.md#ioc_invalid_key\"}]}");
